import { createElement } from "react";
import { PuzzleContentType } from "sockapi/scope-specs/puzzle-content-spec";
import { Spinner } from "components/Loading";
import {
  PuzzleContentRenderContext,
  usePuzzleContent,
} from "components/PuzzleContent/usePuzzleContent";
import "./PuzzleContentDisplay.css";

export function PuzzleContentDisplayPreloaded(props: {
  renderCtx: PuzzleContentRenderContext;
}) {
  const {
    renderCtx: { elem, components, props: elemProps },
  } = props;
  return (
    <div className="puzzle-content clipboard-container">
      {createElement(elem, {
        components,
        ...elemProps,
      })}
    </div>
  );
}

function PuzzleContentDisplay(props: {
  puzName: string;
  contentType?: PuzzleContentType;
  isPreview?: boolean;
}) {
  const { contentType = PuzzleContentType.PUZZLE, puzName, isPreview } = props;
  const { renderCtx } = usePuzzleContent(puzName, contentType, isPreview);
  if (renderCtx === null) return <Spinner inline />;
  return <PuzzleContentDisplayPreloaded renderCtx={renderCtx} />;
}

export default PuzzleContentDisplay;
