const formatNumber = Intl.NumberFormat("en-US").format;

function BigGraph() {
  const graphRef = useRef<HTMLDivElement>(null);
  const inited = useRef(false);

  useEffect(() => {
    if (graphRef.current === null) return;

    let isCanceled = false;
    const initChart = async () => {
      if (inited.current) return;
      const teams = (await (
        await fetch(`/static/posthunt-state/biggraph.json`)
      ).json()) as {
        name: string;
        type: "line";
        itemStyle: object;
        data: number[][];
      }[];
      if (isCanceled) return;

      inited.current = true;
      echarts.init(graphRef.current).setOption({
        title: {
          left: "center",
          textStyle: { color: "white" },
          text: `Top ${teams.length} Teams`,
        },
        legend: {
          type: "scroll",
          orient: "horizontal",
          align: "left",
          bottom: 35,
          textStyle: { color: "white", overflow: "truncate", width: 70 },
          pageTextStyle: { color: "white" },
          data: teams.map((team) => team.name),
        },
        toolbox: {
          feature: {
            dataZoom: {
              yAxisIndex: "none",
            },
            saveAsImage: {},
          },
        },
        grid: {
          containLabel: true,
        },
        xAxis: [
          {
            type: "time",
            boundaryGap: false,
            data: [],
          },
        ],
        yAxis: [
          {
            type: "value",
          },
        ],
        dataZoom: [
          {
            id: "dataZoomX",
            type: "slider",
            xAxisIndex: [0],
            filterMode: "filter",
            height: 20,
            top: 35,
            fillerColor: "rgba(233, 236, 241, 0.4)",
          },
        ],
        tooltip: {
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          formatter: function (params: any) {
            const teamName = params.seriesName;

            const date = new Date(params.data[0]);
            const score = params.data[1];
            const info = params.data[2];

            // team name and color;
            const div1 = document.createElement("div");
            const span = document.createElement("span");
            span.className = "tooltip-colored-circle";
            span.style.backgroundColor = params.color;
            div1.appendChild(span);
            div1.appendChild(document.createTextNode(teamName));

            const div2 = document.createElement("div");
            const sl = document.createElement("small");
            sl.textContent = "Solved: ";
            div2.appendChild(sl);
            div2.appendChild(document.createTextNode(info));
            const ns = document.createElement("strong");
            ns.textContent = " → " + score;
            div2.appendChild(ns);

            const div3 = document.createElement("div");
            div3.textContent = date.toLocaleString();

            const div = document.createElement("div");
            div.appendChild(div1);
            div.appendChild(div2);
            div.appendChild(div3);
            return div.outerHTML;
          },
        },
        series: teams.map((team) => ({
          ...team,
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          symbolSize: (data: any) => (data[3] ? 10 : 4),
        })),
      });
    };

    initChart().catch(console.error);
    return () => {
      isCanceled = true;
    };
  }, []);

  return (
    <details>
      <summary>
        <h2>Big Graph</h2>
      </summary>
      <div
        ref={graphRef}
        style={{ minHeight: "400px", width: "600px", margin: "auto" }}
      />
    </details>
  );
}

function VisitorMap() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const inited = useRef(false);

  useEffect(() => {
    const context = canvasRef.current?.getContext("2d");
    if (!context || inited.current) return;
    inited.current = true;

    const cheapGradient = (start: string, end: string) => {
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      const context = document.createElement("canvas").getContext("2d")!;
      const gradient = context.createLinearGradient(0, 0, 100, 0);
      gradient.addColorStop(0, start);
      gradient.addColorStop(1, end);
      context.fillStyle = gradient;
      context.fillRect(0, 0, 100, 1);

      return (percentage: number) => {
        const [r, g, b, a] = context.getImageData(
          100 * percentage,
          0,
          1,
          1
        ).data;
        return `rgb(${r} ${g} ${b} / ${(100 * a) / 255}%)`;
      };
    };

    const initMap = async () => {
      const coords = (await (
        await fetch("/static/posthunt-state/coords.json")
      ).json()) as Record<string, number>;

      context.lineJoin = "round";
      context.lineWidth = 1;
      context.scale(10, 10);

      const color = cheapGradient("#f003", "#f00");
      const maxLogSize = Math.max(
        ...Object.values(coords).map((val) => Math.log(val))
      );

      for (const [latlon, size] of Object.entries(coords)) {
        const [lat, long] = latlon.split(",").map(Number);
        const sizeRatio = Math.log(size) / maxLogSize;
        context.strokeStyle = color(sizeRatio);
        context.strokeRect(180 + long, 90 - lat, 0.1, 0.1);
      }
    };

    initMap().catch(console.error);
  }, []);

  return (
    <details>
      <summary>
        <h2>Visitor Map</h2>
      </summary>
      <p>
        It’s unclear how accurate this is, but we’d like to imagine that
        Galactic Puzzle Hunt is a popular worldwide phenomenon.
      </p>
      <div style={{ position: "relative" }}>
        <img
          src="https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Equirectangular-projection.jpg/1280px-Equirectangular-projection.jpg"
          style={{ width: "100%", filter: "saturate(0.5)", opacity: 0.5 }}
        />
        <canvas
          ref={canvasRef}
          height="1800"
          width="3600"
          style={{
            position: "absolute",
            inset: 0,
            width: "100%",
            height: "100%",
          }}
        />
      </div>
    </details>
  );
}

async function fetchGachaStats() {
  return (await (
    await fetch(`/static/posthunt-state/gacha_stats.json`)
  ).json()) as {
    numSolves: number[];
    musicalIntuitionHist: { [score: string]: number };
    dontGoogleItHist: {
      puz136: { [answer: string]: number };
      puz177: { [answer: string]: number };
    };
    firstBlood: {
      [teamId: string]: { puzName: string; timestamp: number }[];
    };
    fastBlood: { [teamId: string]: { puzName: string; millis: number }[] };
    teamToCans: { [teamId: string]: number };
    teamToHints: { [teamId: string]: number };
    teamToWishes: { [teamId: string]: number };
    teamToGold: { [teamId: string]: number };
    teamToDust: { [teamId: string]: number };
    teamToNumCollectibles: { [teamId: string]: number };
    teamToHopeGiven: { [teamId: string]: number };
    teamToHopeTaken: { [teamId: string]: number };
  };
}

type GachaStats = Awaited<ReturnType<typeof fetchGachaStats>>;

function TeamListStats({
  stats,
  ascending = false,
  max = 5,
}: {
  stats: Record<string, number>;
  ascending?: boolean;
  max?: number;
}) {
  return (
    <ul>
      {Object.entries(stats)
        .sort((a, b) => (ascending ? a[1] - b[1] : b[1] - a[1]))
        .slice(0, max)
        .map(([teamId, num]) => (
          <li key={teamId}>
            <b>{formatNumber(num)}: </b>
            <TeamDisplayNameDisplay teamId={teamId} />
          </li>
        ))}
    </ul>
  );
}

