export default function WrapupStatsPage() {
  const [stats, setStats] = useState<GachaStats | null>(null);
  const teamData = useGlobalScopeStatePosthuntable(ScopeType.TEAM_LIST, true, {
    hasPosthunt: true,
  });
  const puzzles = useAccessiblePuzzles();

  useEffect(() => {
    fetchGachaStats().then(setStats).catch(console.error);
  }, []);

  return (
    <WrapupWrapper>
      <h1>Appendix: More Statistics</h1>
      {stats && teamData && puzzles ? (
        <>
          <BigGraph />
          <VisitorMap />
          <TeamShoutouts stats={stats} />
          <BloodStats stats={stats} statKey="firstBlood" />
          <BloodStats stats={stats} statKey="fastBlood" />
          <PuzzleHistograms stats={stats} />
          <DefinitionOfInsanity />
          <TeamChoices />
        </>
      ) : (
        <div style={{ textAlign: "center" }}>
          <LargeSpinner inline />
          Loading data. This might take a while.
        </div>
      )}
    </WrapupWrapper>
  );
}
