import { motion } from "framer-motion";

import { capitalize } from "util/util";
import {
  GachaPull,
  GachaPrizeType,
  Rarity,
  JACKPOT_MESSAGES,
} from "sockapi/gacha/pulls";
import { ScopeType } from "sockapi/scope-types";
import { isPuzzleMicropuzzle } from "sockapi/puzzle-data";
import { OLIVE_CONFIG } from "sockapi/scope-specs/team-olive-spec";
import { BLOCKS_CONFIG } from "sockapi/scope-specs/team-blocks-spec";
import {
  useScopeStateResolvable,
  useTeamScopeState,
  usePuzzleDisplayNames,
} from "stores/ScopeStateStore";
import { starHue, PrizeIcon } from "components/Icon";
import { RoutedLink, PuzzleLink } from "components/Link";
import { Spinner } from "components/Loading";
import { makeTeamPagePath } from "components/TeamDisplayNameDisplay";
import "./WishResultDisplay.css";

function PrizeBody(props: { teamId: string; prize: GachaPull }) {
  const { teamId, prize } = props;
  const teamScopeState = useTeamScopeState(teamId);
  const teamCollectiblesScopeState = useScopeStateResolvable(
    ScopeType.TEAM_COLLECTIBLES,
    teamId === null ? null : { teamId }
  );
  const displayNames = usePuzzleDisplayNames();

  if (
    teamScopeState === null ||
    teamCollectiblesScopeState === null ||
    displayNames === null
  )
    return <Spinner inline={true} />;
  const { puzzles } = teamScopeState;

  switch (prize.type) {
    case GachaPrizeType.UNLOCK: {
      const { puzName } = prize;
      const puzData = puzzles[puzName];
      if (puzData === undefined) return null;
      const {
        rarity = Rarity.COMMON,
        isCelestial = false,
        isFindCelestial = false,
      } = puzData;
      const rarityArticle = {
        [Rarity.COMMON]: "a",
        [Rarity.UNCOMMON]: "an",
        [Rarity.RARE]: "a",
        [Rarity.EPIC]: "an",
        [Rarity.LEGENDARY]: "a",
      }[rarity];
      return (
        <>
          {isCelestial || isFindCelestial ? (
            <h4>You found a celestial!</h4>
          ) : !isPuzzleMicropuzzle(puzData) ? (
            <h4>You found a star!</h4>
          ) : (
            <h4>
              You found {rarityArticle}{" "}
              <span
                style={{
                  color: "#ffac33",
                  filter: `hue-rotate(${starHue[rarity]}deg)`,
                }}
              >
                {rarity}
              </span>{" "}
              star!
            </h4>
          )}
          <PuzzleLink puzName={puzName} button={true}>
            {isCelestial || isFindCelestial ? "Are they okay?" : "Investigate"}
          </PuzzleLink>
        </>
      );
    }
    case GachaPrizeType.CANNED_HINT: {
      const { puzName } = prize;
      return (
        <>
          <h4>You found a canned hint!</h4>
          <div>
            It&rsquo;s labeled{" "}
            <PuzzleLink puzName={puzName} subpage="hints">
              {displayNames[puzName]}
            </PuzzleLink>
            &hellip;
          </div>
        </>
      );
    }
    case GachaPrizeType.HINT_TOKEN: {
      return (
        <>
          <h4>You found a hint token!</h4>
          <div>
            Use this in the &ldquo;Hints&rdquo; tab on any puzzle to request a
            custom hint.
          </div>
          <RoutedLink path="/lastpuzzle" button={true}>
            Aw yeah
          </RoutedLink>
        </>
      );
    }
    case GachaPrizeType.JACKPOT: {
      const { amount, msgIndex } = prize;
      return (
        <>
          <h4>You gained {amount} hope!</h4>
          <div>{JACKPOT_MESSAGES[msgIndex]}</div>
        </>
      );
    }
    case GachaPrizeType.COLLECTIBLE: {
      const collectibleData =
        teamCollectiblesScopeState.collectibles[prize.collectibleId];
      return (
        <>
          <h4>
            You found{" "}
            {prize.num === 1
              ? collectibleData.nounPrefix !== ""
                ? `${collectibleData.nounPrefix} `
                : ""
              : `${prize.num} `}{" "}
            {capitalize(collectibleData.name)}!
          </h4>
          <RoutedLink
            path={makeTeamPagePath(teamScopeState.displayName)}
            button={true}
          >
            {collectibleData.isHiddenFromTeamName ? "Let’s go" : "Woah"}
          </RoutedLink>
        </>
      );
    }
    case GachaPrizeType.OLIVE: {
      return (
        <>
          <h4>You&rsquo;re not sure what this is...</h4>
          <PuzzleLink puzName={OLIVE_CONFIG.puzName} button={true}>
            Ask Olive
          </PuzzleLink>
        </>
      );
    }
    case GachaPrizeType.BLOCKS: {
      return (
        <>
          <h4>You found some blocks!</h4>
          <PuzzleLink puzName={BLOCKS_CONFIG.puzName} button={true}>
            Exciting
          </PuzzleLink>
        </>
      );
    }
  }
}

function WishResultDisplay({
  teamId,
  pull,
  isLatest,
}: {
  teamId: string;
  pull: GachaPull;
  isLatest: boolean;
}) {
  return (
    <>
      <motion.div
        className="wish-result-icon"
        style={{ transform: "translateY(0) scale(1)" }}
        exit={isLatest ? { transform: "translateY(50vh) scale(0.25)" } : {}}
        transition={{ duration: 0.3 }}
      >
        <PrizeIcon teamId={teamId} prize={pull} />
      </motion.div>
      <motion.div
        className="wish-result"
        style={{ transform: "scale(1)" }}
        exit={isLatest ? { transform: "scale(1.02)" } : {}}
        transition={{ duration: 0.3 }}
      >
        <PrizeBody teamId={teamId} prize={pull} />
      </motion.div>
    </>
  );
}

export default WishResultDisplay;
