import "./BlocksPuzzle.css";

import { Fragment, useState, useEffect, useCallback } from "react";
import { ScopeType } from "sockapi/scope-types";
import { BLOCKS_CONFIG } from "sockapi/scope-specs/team-blocks-spec";
import {
  useTeamId,
  useSockClient,
  useShouldDisplayAdmin,
} from "stores/ServerInteractionStore";
import { useScopeStateResolvable } from "stores/ScopeStateStore";
import {
  useBlocksPuzzleBoardState,
  useUpdateBrowserWidePersistentState,
} from "stores/BrowserWidePersistentState";
import { Spinner } from "components/Loading";
import { clsObj } from "client-util";

function range(n: number) {
  return [...Array(n).keys()];
}

type Loc = [number, number];
export type BlocksPuzzleBoardState = Loc[];

type Block = {
  text: string;
  locPredicate: (rd: number, cd: number) => boolean;
  countPredicate: (matches: number, others: number) => boolean;
  inverter: boolean;
};

function parseLocPredicate(s: string) {
  // console.log("predicate: " + s);
  let match;
  if ((match = /^\((\d+)\)$/.exec(s))) {
    const thresh2 = Number(match[1]) ** 2;
    return (rd: number, cd: number) => rd ** 2 + cd ** 2 < thresh2;
  }

  if ((match = /^\[(\d+)\]$/.exec(s))) {
    const thresh = Number(match[1]);
    return (rd: number, cd: number) =>
      Math.max(Math.abs(rd), Math.abs(cd)) < thresh;
  }

  if ((match = /^<(\d+)>$/.exec(s))) {
    const thresh = Number(match[1]);
    return (rd: number, cd: number) => Math.abs(rd) + Math.abs(cd) < thresh;
  }

  if ("/w" === s) {
    return (_rd: number, cd: number) => cd < 0;
  }
  if ("/e" === s) {
    return (_rd: number, cd: number) => cd > 0;
  }
  if ("/ne" === s) {
    return (rd: number, cd: number) => -rd + cd > 0;
  }
  if ("/sw" === s) {
    return (rd: number, cd: number) => rd - cd > 0;
  }
  if ("/nw" === s) {
    return (rd: number, cd: number) => rd + cd < 0;
  }
  if ("/se" === s) {
    return (rd: number, cd: number) => rd + cd > 0;
  }
  if ("/s" === s) {
    return (rd: number, _cd: number) => rd > 0;
  }

  if ("R" === s) {
    return (rd: number, cd: number) => rd === 0 || cd === 0;
  }
  if ("B" === s) {
    return (rd: number, cd: number) => Math.abs(rd) === Math.abs(cd);
  }
  if ("N" === s) {
    return (rd: number, cd: number) => {
      const ard = Math.abs(rd);
      const acd = Math.abs(cd);
      return Math.min(ard, acd) === 1 && Math.max(ard, acd) === 2;
    };
  }
  if ("Q" === s) {
    return (rd: number, cd: number) =>
      rd === 0 || cd === 0 || Math.abs(rd) === Math.abs(cd);
  }

  throw new Error(`what? ${s}`);
}

function parseBlock(text: string): Block {
  // console.log(text);
  let countPredicate = (matches: number, _others: number) => matches === 0;
  let inverter = false;
  let s = text;

  if (s[0] === "*") {
    s = s.slice(1);
    countPredicate = (matches: number, others: number) => matches === others;
  }
  if (s[0] === "!") {
    s = s.slice(1);
    countPredicate = (_matches: number, _others: number) => true;
    inverter = true;
  }
  let match;
  if ((match = /^(\d+)/.exec(s))) {
    s = s.slice(match[1].length);
    const count = Number(match[1]);
    countPredicate = (matches: number, _others: number) => matches === count;
  }

  return {
    text,
    countPredicate,
    locPredicate: parseLocPredicate(s),
    inverter,
  };
}

export function BlocksPuzzleBoard(props: {
  /** The board index. If not provided, renders statically. */
  boardIndex?: number;
  blocks: string[];
  locs?: BlocksPuzzleBoardState;
}) {
  const { boardIndex, blocks } = props;
  const boardId = boardIndex?.toString();
  const updateBrowserWidePersistentState =
    useUpdateBrowserWidePersistentState();
  const savedLocs = useBlocksPuzzleBoardState(boardId ?? null);
  const locs =
    savedLocs ?? props.locs ?? range(blocks.length).map((i) => [0, i]);
  const setLocs = (newLocs: BlocksPuzzleBoardState) => {
    if (boardId === undefined) return;
    updateBrowserWidePersistentState({
      blocksPuzzleBoardsState: {
        [boardId]: newLocs,
      },
    });
  };
  // blocks[i] is at locs[i]
  const [clickedIndex, setClickedIndex] = useState<number | null>(null);
  const sockClient = useSockClient();
  const teamId = useTeamId();
  const teamBlocksState = useScopeStateResolvable(
    ScopeType.TEAM_BLOCKS,
    teamId === null ? null : { teamId }
  );
  const shouldDisplayAdmin = useShouldDisplayAdmin();

  const table: ({ ix: number; block: string; valid: boolean } | null)[][] =
    range(15).map((r) => range(15).map((c) => null));
  const inverted = locs.map((_) => false);
  const parsedBlocks = blocks.map(parseBlock);
  parsedBlocks.forEach((block, ix) => {
    if (block.inverter) {
      const [r, c] = locs[ix];
      locs.forEach((oloc, oix) => {
        if (oix !== ix) {
          const [or, oc] = oloc;
          if (block.locPredicate(or - r, oc - c)) {
            inverted[oix] = true;
          }
        }
      });
    }
  });
  parsedBlocks.forEach((block, ix) => {
    let valid = true;
    const [r, c] = locs[ix];
    const { text, locPredicate, countPredicate } = block;

    let matches = 0;
    locs.forEach((oloc, oix) => {
      if (oix !== ix) {
        const [or, oc] = oloc;
        if (locPredicate(or - r, oc - c) !== inverted[ix]) {
          matches += 1;
        }
        // console.log([r, c, or, oc, dist2, thresh2, matches]);
      }
    });
    valid = countPredicate(matches, locs.length - 1);

    table[r][c] = { ix, block: text, valid };
  });

  const isUnsolvedSynced =
    boardIndex !== undefined &&
    teamBlocksState !== null &&
    !(teamBlocksState.solvedBoards[boardIndex] ?? false);
  const isSolved = table.flat(2).every((block) => block?.valid ?? true);
  const setSolved = useCallback(
    (newIsSolved: boolean) => {
      if (teamId === null) return;
      if (boardIndex === undefined) return;
      sockClient
        .sendScopeStepAndWaitAsync(
          {
            type: ScopeType.TEAM_BLOCKS,
            teamId,
          },
          {
            setBoardSolved: {
              boardIndex,
              isSolved: newIsSolved,
            },
          }
        )
        .catch(console.error);
    },
    [sockClient, teamId, boardIndex]
  );

  // Use an effect for this, so that if a board is solved, but the
  // step fails, refreshing the page will resend the request.
  useEffect(() => {
    if (boardIndex === undefined) return;
    if (teamId === null) return;
    if (!isUnsolvedSynced) return;
    if (!isSolved) return;
    setSolved(true);
  }, [teamId, isUnsolvedSynced, isSolved, sockClient, boardIndex, setSolved]);

  function handle(r: number, c: number, ix: number | undefined) {
    if (boardId === undefined) return;
    if (clickedIndex !== null) {
      const newLocs = [...locs];
      if (ix !== undefined) {
        newLocs[ix] = newLocs[clickedIndex];
      }
      newLocs[clickedIndex] = [r, c];
      setLocs(newLocs);
      setClickedIndex(null);
    } else if (ix !== undefined) {
      setClickedIndex(ix);
    }
  }

  if (teamId === null) return <Spinner inline />;

  return (
    <>
      {boardIndex !== undefined && shouldDisplayAdmin ? (
        <div>
          <button
            onClick={() => {
              setSolved(isUnsolvedSynced);
            }}
          >
            Set {isUnsolvedSynced ? "solved" : "unsolved"} (admin only)
          </button>
        </div>
      ) : null}
      <table
        className={clsObj({
          "blocks-puzzle-table": true,
          "blocks-puzzle-moving": clickedIndex !== null,
        })}
      >
        <tbody>
          {range(15).map((r) => (
            <tr key={r}>
              {range(15).map((c) => (
                <td
                  key={c}
                  onClick={() => handle(r, c, table[r][c]?.ix)}
                  className={clsObj({
                    clicked: table[r][c]?.ix === clickedIndex,
                    valid: table[r][c]?.valid ?? false,
                    invalid: (table[r][c] && !table[r][c]?.valid) ?? false,
                  })}
                  {...{
                    "data-copy-only-styles":
                      "border: 1px dotted black; color: white;",
                  }}
                >
                  {table[r][c]?.block}
                  <br />
                  {table[r][c] && (table[r][c]?.valid ? "✅" : "❌")}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </>
  );
}

export function BlocksPuzzle() {
  const teamId = useTeamId();
  const teamBlocksScopeState = useScopeStateResolvable(
    ScopeType.TEAM_BLOCKS,
    teamId === null ? null : { teamId }
  );

  if (teamBlocksScopeState === null) return <Spinner inline />;
  const { maxNumBoards, boardSpecs, solvedBoards, inscription } =
    teamBlocksScopeState;
  const numBoardsSolved = Object.values(solvedBoards).filter(
    (isSolved) => isSolved
  ).length;
  const numBoardsRemainingForInscription =
    BLOCKS_CONFIG.inscriptionNumBoards - numBoardsSolved;

  return (
    <>
      <p>
        {boardSpecs.length >= maxNumBoards ? (
          <>You found all the blocks!</>
        ) : (
          <>
            You found {boardSpecs.length} of my {maxNumBoards} groups of blocks.
            Wishing might help you find more!
          </>
        )}
      </p>
      <p>
        Click a block and an empty square to move it there, or two blocks to
        swap them.
      </p>
      <div className="blocks-puzzle-boards">
        {boardSpecs.map((boardSpec, i) => (
          <Fragment key={i}>
            {solvedBoards[i] ?? false ? (
              <div className="note">
                You&rsquo;ve found a way to arrange this group of blocks! You
                may still play around with it, if you&rsquo;d like.
              </div>
            ) : null}
            <div
              className={clsObj({
                "blocks-puzzle-board-wrapper": true,
                "blocks-puzzle-board-wrapper-solved": solvedBoards[i] ?? false,
              })}
            >
              <BlocksPuzzleBoard boardIndex={i} blocks={boardSpec} />
            </div>
          </Fragment>
        ))}
      </div>
      <p>
        {numBoardsRemainingForInscription > 0 ? (
          <>
            You’ve arranged {numBoardsSolved}{" "}
            {numBoardsSolved === 1 ? "group" : "groups"} of blocks. If you
            arrange {numBoardsRemainingForInscription} more, I might just be
            able to remember something.
          </>
        ) : (
          <>
            Thanks for arranging my blocks! Here’s something I remember:
            <pre>{inscription}</pre>
          </>
        )}
      </p>
    </>
  );
}
