import { PuzzleImage } from "components/PuzzleContent/puzzle-components";

export function Puzzle329Card(props: {
  staticPuzDir: string;
  headerNum?: number;
  name: string;
}) {
  const { staticPuzDir, headerNum, name } = props;

  return (
    <div
      className={`puz329-card ${
        headerNum === undefined ? "puz329-card-no-header" : undefined
      }`}
    >
      {headerNum !== undefined ? (
        <div className="puz329-card-header">
          <div className="puz329-card-header-left">
            <div className="puz329-card-header-part">Part</div>
            <div className="puz329-card-header-num">{headerNum}</div>
          </div>
          <div className="puz329-card-header-right">
            <span />
          </div>
        </div>
      ) : null}
      <PuzzleImage staticPuzDir={staticPuzDir} name={name} />
      <div className="puz329-card-footer">
        <div className="puz329-card-question-mark">?</div>
        <div className="puz329-card-footer-right">
          <div />
          <div />
          <div />
        </div>
      </div>
    </div>
  );
}
