/**
 * Takes a timestamp and indicates whether the current time is before
 * the timestamp, reacting dynamically when the time is up.
 * Returns null if the timestamp is null.
 */
const useIsNowBeforeTimestamp = (timestamp: number | null): boolean | null => {
  const isAfter = useReactiveTimeout(timestamp);
  return isAfter === null ? null : !isAfter;
};

function Puzzle105SupportingDocument(props: {
  puzName: string;
  isLocked?: boolean;
}) {
  const { puzName, isLocked = false } = props;
  const teamId = useTeamId();
  const sockClient = useServerInteractionStore(
    (state) => state.getSockClient
  )();
  const puz105State = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_105,
    teamId === null ? null : { teamId }
  );
  const titleInputRef = useRef<HTMLInputElement>(null);
  const [currentTitle, setCurrentTitle] = useState("");
  const [needRefocus, setNeedRefocus] = useState(false);
  const teamScopeState = useTeamScopeState();
  const checkTitleLock = useUILock();
  const { isHeld: isCheckTitleLockHeld } = checkTitleLock;
  const confirmedTitle = puz105State?.confirmedTitles[puzName];
  const answer = teamScopeState?.puzzles[puzName]?.answer;
  const isThrottled =
    useIsNowBeforeTimestamp(puz105State?.checkTitleThrottledTime ?? null) ??
    false;
  const checkTitleRateLimitedMessage = `You've been rate limited for making too many mistakes! Please try again after ${PUZZLE_105_CONFIG.checkTitleRateLimitIntervalMinutes} minutes.`;
  const customTitles =
    useScopeStateResolvable(
      ScopeType.TEAM_TITLES,
      teamId !== null ? { teamId } : null
    )?.titles ?? null;
  const syncedTitle = customTitles?.[puzName] ?? null;

  useEffect(() => {
    if (syncedTitle !== null) setCurrentTitle(syncedTitle);
  }, [syncedTitle]);

  useEffect(() => {
    if (isThrottled) setCurrentTitle("");
  }, [isThrottled]);

  useEffect(() => {
    if (!needRefocus) return;
    if (titleInputRef.current === null) return;
    if (isCheckTitleLockHeld) return;
    if (confirmedTitle !== undefined) return;
    if (currentTitle !== "") return;
    titleInputRef.current.focus();
    setNeedRefocus(false);
  }, [
    needRefocus,
    titleInputRef,
    isCheckTitleLockHeld,
    confirmedTitle,
    currentTitle,
  ]);

  if (
    teamId === null ||
    sockClient === null ||
    puz105State === null ||
    teamScopeState === null ||
    customTitles === null
  )
    return <Spinner inline={true} />;

  const scope: Scope<ScopeType.TEAM_PUZZLE_105> = {
    type: ScopeType.TEAM_PUZZLE_105,
    teamId,
  };

  const checkTitle = () => {
    if (titleInputRef.current === null) return;
    if (isThrottled) return;
    const title = titleInputRef.current.value;
    if (title.trim() === "") return;
    checkTitleLock.acquireAndRun(async (getIsCanceled) => {
      const payload = await sockClient.sendScopeStepAndWaitAsync(scope, {
        checkTitle: { puzName, title },
      });
      if (getIsCanceled() || payload === null) return;
      const { checkTitleResp } = payload;
      if (checkTitleResp === undefined)
        throw new Error(`received invalid check title response ${payload}`);
      const normalizedTitle = normalizeAnswer(title);
      // Make a return value to have typescript help check
      // that this is exhaustive.
      ((): true => {
        switch (checkTitleResp) {
          case Puzzle105CheckTitleResponse.CORRECT:
            toastr.success(`${normalizedTitle} is an appropriate title!`);
            return true;
          case Puzzle105CheckTitleResponse.WRONG:
            toastr.error(`${normalizedTitle} is not an appropriate title.`);
            return true;
          case Puzzle105CheckTitleResponse.RATE_LIMITED:
            toastr.warning(checkTitleRateLimitedMessage);
            return true;
          case Puzzle105CheckTitleResponse.ALREADY_SOLVED:
            // No need a notification as this just indicates
            // a race condition.
            return true;
        }
      })();
      if (titleInputRef.current !== null) {
        setNeedRefocus(true);
        setCurrentTitle("");
      }
    });
  };

  const moveButtonClass = `puzzle-105-move-button ${
    isLocked ? "disabled" : ""
  }`;

  return (
    <div className="puzzle-105-supporting-document">
      <div className="puzzle-105-move-buttons">
        <div
          className={moveButtonClass}
          onClick={() => {
            if (isLocked) return;
            sockClient.sendTeamPuzzle105ScopeStep(
              {
                movePuz: { puzName, diff: -1 },
              },
              teamId
            );
          }}
        >
          <Twemoji>⬆️</Twemoji>
        </div>
        <div
          className={moveButtonClass}
          onClick={() => {
            if (isLocked) return;
            sockClient.sendTeamPuzzle105ScopeStep(
              {
                movePuz: { puzName, diff: 1 },
              },
              teamId
            );
          }}
        >
          <Twemoji>⬇️</Twemoji>
        </div>
      </div>
      <div className="puzzle-105-supporting-document-middle">
        <div>
          Title:{" "}
          <input
            ref={titleInputRef}
            maxLength={PUZZLE_105_CONFIG.titleMaxLength}
            placeholder={
              syncedTitle ?? undefined
              // Enumerations are disabled for this version.
              // "?".repeat(puz105State.enums[puzName])
            }
            value={confirmedTitle ?? currentTitle}
            disabled={isCheckTitleLockHeld || isThrottled}
            readOnly={isLocked || confirmedTitle !== undefined}
            onChange={(e) => {
              setCurrentTitle(e.target.value);
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                checkTitle();
              }
            }}
          />{" "}
          <span className="puzzle-105-supporting-document-title-check-wrapper">
            {confirmedTitle !== undefined ? (
              <Twemoji>✅</Twemoji>
            ) : isThrottled ? (
              <Tooltip text={checkTitleRateLimitedMessage}>
                <Twemoji>⏳⚠️</Twemoji>
              </Tooltip>
            ) : (
              <button
                onClick={() => {
                  checkTitle();
                }}
              >
                Check
              </button>
            )}
          </span>
        </div>
        <div>
          Answer: {answer === undefined ? "(not yet solved)" : <b>{answer}</b>}
        </div>
      </div>
      <PuzzleContentPreviewWithLink puzName={puzName} />
    </div>
  );
}

export function Puzzle105Form(props: {
  teamId: string;
  isLocked?: boolean;
  hideAnswer?: boolean;
}) {
  const { teamId, isLocked = false, hideAnswer = false } = props;
  const sockClient = useServerInteractionStore(
    (state) => state.getSockClient
  )();
  const puz105State = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_105,
    teamId === null ? null : { teamId }
  );
  const [displayedDate, setDisplayedDate] = useState<number | null>(null);

  useEffect(() => {
    if (puz105State === null) return;
    const { status: submitStatus } = puz105State;
    setDisplayedDate(
      submitStatus !== undefined && !isTeamPuzzle105Editable(puz105State)
        ? submitStatus.submitTime
        : Date.now()
    );
  }, [puz105State, setDisplayedDate]);

  if (puz105State === null || sockClient === null || displayedDate === null)
    return <Spinner />;

  const makeFormFieldUpdate = (
    makeUpd: (val: string) => Puzzle105FormFieldsUpdate
  ) => {
    return (val: string) => {
      sockClient.sendTeamPuzzle105ScopeStep(
        {
          formFields: makeUpd(val),
        },
        teamId
      );
    };
  };

  const makeOneLineFormField = (left: ReactNode, right: ReactNode) => {
    return (
      <div className="puzzle-105-form-field">
        <div className="puzzle-105-form-field-left">{left}</div>
        <div className="puzzle-105-form-field-right">{right}</div>
      </div>
    );
  };

  const { difficulty, sharePermission } = puz105State.formFields;
  const onSelectDifficulty = (newVal: number) => {
    sockClient.sendTeamPuzzle105ScopeStep(
      {
        formFields: { difficulty: newVal },
      },
      teamId
    );
  };
  const makeDifficultyRadioButton = (val: number) => {
    return (
      <label className="puzzle-105-radio-button-label">
        <input
          type="radio"
          disabled={isLocked}
          checked={difficulty !== null && difficulty === val}
          onChange={() => onSelectDifficulty(val)}
        />
        {val}
      </label>
    );
  };
  const onSelectSharePermission = (newVal: Puzzle105SharePermission) => {
    sockClient.sendTeamPuzzle105ScopeStep(
      {
        formFields: { sharePermission: newVal },
      },
      teamId
    );
  };
  const makeSharePermissionRadioButton = (
    val: Puzzle105SharePermission,
    text: string
  ) => {
    return (
      <label className="puzzle-105-radio-button-label">
        <input
          type="radio"
          disabled={isLocked}
          checked={sharePermission !== null && sharePermission === val}
          onChange={() => onSelectSharePermission(val)}
        />
        {text}
      </label>
    );
  };

  const {
    formLimits: { shortInputMaxLength, longInputMaxLength },
  } = PUZZLE_105_CONFIG;

  const makeTextAreaFormField = (
    instructions: string,
    syncedVal: string,
    onUpdate: (val: string) => void,
    props?: ComponentPropsWithoutRef<"textarea">
  ) => {
    return (
      <div className="puzzle-105-textarea-field">
        <div>{instructions}</div>
        <SyncedTextArea
          disabled={isLocked}
          maxLength={longInputMaxLength}
          syncedVal={syncedVal}
          onUpdate={onUpdate}
          {...props}
        />
      </div>
    );
  };

  return (
    <div className="puzzle-105-form">
      <h1>Free Puzzle Request Form</h1>
      {makeOneLineFormField(
        `Record the title of your Free Puzzle (optional, max ${shortInputMaxLength} chars):`,
        <SyncedTextInput
          disabled={isLocked}
          maxLength={shortInputMaxLength}
          syncedVal={puz105State.formFields.title}
          onUpdate={makeFormFieldUpdate((val) => ({ title: val.trim() }))}
        />
      )}
      {makeOneLineFormField(
        `Enter the answer to your Free Puzzle (max ${shortInputMaxLength} chars):`,
        <SyncedTextInput
          disabled={isLocked}
          maxLength={shortInputMaxLength}
          syncedVal={puz105State.formFields.answer}
          className={`puzzle-105-answer-input ${hideAnswer ? "hidden" : ""}`}
          onUpdate={makeFormFieldUpdate((val) => ({
            answer: val
              .split("/")
              .map((subval) => normalizeAnswer(subval))
              .join(" / "),
          }))}
        />
      )}
      {makeOneLineFormField(
        "Date:",
        <input
          type="text"
          disabled
          value={new Date(displayedDate).toLocaleDateString()}
        />
      )}
      {makeOneLineFormField(
        "Hex color (6 digits) associated with your Free Puzzle:",
        <>
          #
          <SyncedTextInput
            disabled={isLocked}
            maxLength={6}
            syncedVal={puz105State.formFields.hexColor}
            onUpdate={makeFormFieldUpdate((val) => ({
              hexColor: normalizeHexColor(val),
            }))}
          />
        </>
      )}
      {makeOneLineFormField(
        "Estimate the difficulty of your Free Puzzle:",
        <div className="puzzle-105-form-field-radio-buttons">
          {makeDifficultyRadioButton(1)}
          {makeDifficultyRadioButton(2)}
          {makeDifficultyRadioButton(3)}
          {makeDifficultyRadioButton(4)}
          {makeDifficultyRadioButton(5)}
        </div>
      )}
      {makeTextAreaFormField(
        `Record the flavortext for your Free Puzzle (optional, max ${longInputMaxLength} chars):`,
        puz105State.formFields.flavortext,
        makeFormFieldUpdate((val) => ({ flavortext: val.trim() }))
      )}
      {makeTextAreaFormField(
        `Record a brief solution to your Free Puzzle (max ${longInputMaxLength} chars):`,
        puz105State.formFields.solution,
        makeFormFieldUpdate((val) => ({ solution: val.trim() }))
      )}
      {makeTextAreaFormField(
        `Instructions to solvers to be appended to your Free Puzzle (optional, max ${longInputMaxLength} chars):`,
        puz105State.formFields.instructions,
        makeFormFieldUpdate((val) => ({ instructions: val.trim() }))
      )}
      {makeTextAreaFormField(
        `Notes (optional, max ${longInputMaxLength} chars):`,
        puz105State.formFields.notes,
        makeFormFieldUpdate((val) => ({ notes: val.trim() }))
      )}
      <div>
        <div>Grant permission to share your Free Puzzle with other teams?</div>
        <div>
          <div className="puzzle-105-form-field-radio-buttons">
            {makeSharePermissionRadioButton(
              Puzzle105SharePermission.FULL,
              "Yes, including through wishes"
            )}
            {makeSharePermissionRadioButton(
              Puzzle105SharePermission.WRAPUP,
              "Yes, but only in wrap-up"
            )}
            {makeSharePermissionRadioButton(
              Puzzle105SharePermission.NONE,
              "No"
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function Puzzle105Diagram(props: { isLocked?: boolean }) {
  const { isLocked = false } = props;
  const teamId = useTeamId();
  const sockClient = useServerInteractionStore(
    (state) => state.getSockClient
  )();
  const [fileErr, setFileErr] = useState<string | null>(null);
  const puz105State = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_105,
    teamId === null ? null : { teamId }
  );

  if (teamId === null || sockClient === null || puz105State === null)
    return <Spinner />;
  const { diagramUrl } = puz105State;
  const scope: Scope<ScopeType.TEAM_PUZZLE_105> = {
    type: ScopeType.TEAM_PUZZLE_105,
    teamId,
  };

  return (
    <div className="puzzle-105-diagram">
      <div>
        <h4>
          Upload a Diagram of your Free Puzzle (only PNG/JPG supported, max 1MB)
        </h4>
      </div>
      <ImageSubmission
        isLocked={isLocked}
        slot={SubmitImageSlot.PUZZLE_105}
        supportedMimeTypes={["image/png", "image/jpeg"]}
        maxFileSize={1e6}
        onSubmitSuccess={async () => {
          await sockClient.sendScopeStepAndWaitAsync(scope, {
            downloadDiagramUrl: true,
          });
        }}
      />
      {diagramUrl === undefined ? null : (
        <img src={makeSubmittedImageUrl(diagramUrl)} />
      )}
    </div>
  );
}

