function Puzzle105Submit() {
  const teamId = useTeamId();
  const sockClient = useServerInteractionStore(
    (state) => state.getSockClient
  )();
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const puz105State = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_105,
    teamId === null ? null : { teamId }
  );
  const isSolved = useIsPuzzleSolved(PUZZLE_105_CONFIG.puzName);
  const isHuntOver = useIsHuntOver();

  const submitLock = useUILock();
  const { isHeld: isSubmitLockHeld } = submitLock;
  const reopenTime =
    puz105State === null ? null : getTeamPuzzle105ReopenTime(puz105State);
  const isThrottled = useIsNowBeforeTimestamp(reopenTime) ?? false;

  if (
    teamId === null ||
    puz105State === null ||
    sockClient === null ||
    isSolved === null
  )
    return <Spinner />;
  const { status: submitStatus = null } = puz105State;
  const isEditable = isTeamPuzzle105Editable(puz105State);
  const isAccepted =
    submitStatus !== null && submitStatus.type === Puzzle105StatusType.ACCEPTED;
  const isReviewPending =
    submitStatus !== null && submitStatus.type === Puzzle105StatusType.PENDING;
  const errs = validateTeamPuzzle105(puz105State);

  const scope: Scope<ScopeType.TEAM_PUZZLE_105> = {
    type: ScopeType.TEAM_PUZZLE_105,
    teamId,
  };

  return (
    <div>
      <div>
        <div>Form</div>
        {puz105State.order.map((puzName, i) => {
          const title = puz105State.confirmedTitles[puzName];
          return (
            <div key={puzName}>
              Supporting Document {i + 1}: {title ?? "(untitled)"}
            </div>
          );
        })}
        <div>Diagram</div>
      </div>
      <hr />
      {isAccepted ? (
        <div className="puzzle-105-submit-success">
          Congratulations! Your Application has passed review. Please submit
          your Application to the nearest cavern.
        </div>
      ) : isReviewPending ? (
        <div>
          Congratulations! Your Application passed the baseline requirements and
          has been submitted to our staff for review. Please wait up to 300000
          business seconds for your Application to be processed.
        </div>
      ) : reopenTime !== null && isThrottled ? (
        <div className="puzzle-105-submit-error">
          Your Application has been rejected for the following reason: Wrongly
          ordered documentation. Please try again at or after{" "}
          {new Date(reopenTime).toLocaleString()}.
        </div>
      ) : submitStatus !== null &&
        submitStatus.type === Puzzle105StatusType.REJECTED ? (
        <div className="puzzle-105-submit-error">
          Your Application has been rejected for the following reason:{" "}
          {submitStatus.reason}
          {".!?".includes(submitStatus.reason[submitStatus.reason.length - 1])
            ? ""
            : "."}{" "}
          Please resubmit your Application after making the necessary
          modifications.
        </div>
      ) : null}
      {isEditable && !isThrottled ? (
        <>
          <div className="puzzle-105-submit-warning">
            WARNING: Submitting a wrongly ordered application may result in
            rejection of your application and delay your Free Puzzle.
          </div>
          {errs.length > 0 ? (
            <div className="puzzle-105-validation-errors">
              <div className="puzzle-105-validation-errors-explanation">
                Please correct the following issues to proceed with your
                Application:
              </div>
              <div>
                <ul>
                  {errs.map((errMsg, i) => (
                    <li key={i}>{errMsg}</li>
                  ))}
                </ul>
              </div>
            </div>
          ) : null}
          <div className="puzzle-105-posthunt-submission-infobox">
            {isHuntOver ? <SubmissionsClosedInfobox /> : null}
          </div>
          <div>
            <button
              disabled={isSubmitLockHeld || errs.length > 0}
              onClick={() => {
                submitLock.acquireAndRun(async (getIsCanceled) => {
                  await sockClient.sendScopeStepAndWaitAsync(scope, {
                    submit: true,
                  });
                });
              }}
            >
              Submit
            </button>
          </div>
        </>
      ) : null}
      {shouldDisplayAdmin && isEditable && !isSolved ? (
        <button
          disabled={isSubmitLockHeld}
          onClick={() => {
            submitLock.acquireAndRun(async (getIsCanceled) => {
              await sockClient.sendScopeStepAndWaitAsync(scope, {
                submit: true,
                ignoreSubmitErrors: true,
              });
            });
          }}
        >
          Submit unchecked (admin only)
        </button>
      ) : null}
    </div>
  );
}

function Puzzle105SupportingDocumentReorderItem(props: {
  isLocked: boolean;
  puzName: string;
}) {
  const { isLocked, puzName } = props;
  // TODO: hook up drag with server sync. For now drag is disabled.
  const dragControls = useDragControls();

  return (
    <Reorder.Item
      as="div"
      value={puzName}
      dragListener={false}
      dragControls={dragControls}
    >
      <Puzzle105SupportingDocument isLocked={isLocked} puzName={puzName} />
    </Reorder.Item>
  );
}

export function Puzzle105() {
  const teamId = useTeamId();
  const puz105State = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_105,
    teamId === null ? null : { teamId }
  );
  const syncedOrder = puz105State?.order ?? null;
  const [displayedOrder, setDisplayedOrder] = useState<string[] | null>(null);

  useEffect(() => {
    if (syncedOrder === null) return;
    setDisplayedOrder(syncedOrder);
  }, [syncedOrder]);

  if (teamId === null || puz105State === null || displayedOrder === null)
    return <Spinner />;
  const isLocked = !isTeamPuzzle105Editable(puz105State);

  return (
    <div>
      <div className="puzzle-105-header">
        <h1>Application for Free Puzzle Redemption</h1>
      </div>
      <Puzzle105Form teamId={teamId} isLocked={isLocked} />
      <div className="puzzle-105-supporting-documents">
        <Reorder.Group
          as="div"
          axis="y"
          values={displayedOrder}
          onReorder={() => {
            return;
          }}
        >
          {displayedOrder.map((puzName) => (
            <Puzzle105SupportingDocumentReorderItem
              isLocked={isLocked}
              puzName={puzName}
              key={puzName}
            />
          ))}
        </Reorder.Group>
      </div>
      <Puzzle105Diagram isLocked={isLocked} />
      <div className="puzzle-105-header">
        <h1>Preview your Free Puzzle</h1>
      </div>
      <Puzzle105Preview teamId={teamId} />
      <div className="puzzle-105-header">
        <h1>Review and Submit</h1>
      </div>
      <Puzzle105Submit />
    </div>
  );
}
