import { useRef } from "react";
import Twemoji from "react-twemoji";

import { ScopeType } from "sockapi/scope-types";
import { Scope } from "sockapi/scopes";
import { useSockClient } from "stores/ServerInteractionStore";
import { useScopeStateResolvable } from "stores/ScopeStateStore";
import { useNavStore } from "stores/NavStore";

import PuzzleContentDisplay from "components/PuzzleContent/PuzzleContentDisplay";
import TeamDisplayNameDisplay from "components/TeamDisplayNameDisplay";
import { CollapsibleContent } from "components/AdminQueue/admin-queue-hint";
import { Spinner } from "components/Loading";
import { PuzzleContentType } from "sockapi/scope-specs/puzzle-content-spec";

export function Puzzle144AdminQueueTaskSummaryDisplay(props: {
  teamId: string;
}) {
  const { teamId: displayedTeamId } = props;
  const teamPuzzle144ScopeState = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_144,
    { teamId: displayedTeamId }
  );

  if (teamPuzzle144ScopeState === null) return <Spinner inline={true} />;
  const { req } = teamPuzzle144ScopeState;
  if (req === undefined) return <div>No submission found.</div>;

  return (
    <div>
      <h4>Musical Intuition Submission</h4>
      <div>
        Team: <TeamDisplayNameDisplay teamId={displayedTeamId} />
      </div>
      <div>
        <p>{req.text}</p>
      </div>
    </div>
  );
}

export function Puzzle144AdminQueueTaskDisplay(props: {
  teamId: string;
  isClaimedBySelf: boolean;
}) {
  const { teamId: displayedTeamId, isClaimedBySelf } = props;
  const teamPuzzle144ScopeState = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_144,
    { teamId: displayedTeamId }
  );
  const numPointsInputRef = useRef<HTMLInputElement>(null);
  const textInputRef = useRef<HTMLTextAreaElement>(null);
  const sockClient = useSockClient();
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);

  if (teamPuzzle144ScopeState === null) return <Spinner inline={true} />;

  const { req, resp } = teamPuzzle144ScopeState;
  if (req === undefined) return <div>No submission found.</div>;

  return (
    <div className="admin-queue-task-puzzle-144">
      <h2>Musical Intuition Submission</h2>
      <div>
        Team: <TeamDisplayNameDisplay teamId={displayedTeamId} />
      </div>
      <CollapsibleContent headerContent="Solution (contains rubric)">
        <div>
          <PuzzleContentDisplay
            puzName="puz144"
            contentType={PuzzleContentType.SOLUTION}
          />
        </div>
      </CollapsibleContent>
      <hr />
      <div>
        <pre>{req.text}</pre>
      </div>
      <hr />
      {!isClaimedBySelf ? (
        <div className="admin-queue-claim-this-task-notice">
          Claim this task to respond to it.
        </div>
      ) : null}
      <div>
        <textarea
          disabled={!isClaimedBySelf}
          defaultValue={resp?.text ?? ""}
          ref={textInputRef}
        />
      </div>
      <div>
        Points out of 10 (round to nearest .5):{" "}
        <input
          type="number"
          defaultValue={resp?.numPoints ?? 5}
          min={0}
          max={11}
          step={0.5}
          ref={numPointsInputRef}
        />
      </div>
      <div>
        Feel free to add adjustments and deviate from the rubric. It is only
        there for convenience.
        <br />
        <Twemoji tag="span">⚠️ Warning ⚠️</Twemoji>: Check that the score here
        is correct. <b>The score from the rubric is not synced to this one.</b>
      </div>
      <div>
        <button
          onClick={() => {
            (async () => {
              if (textInputRef.current === null) return;
              if (numPointsInputRef.current === null) return;
              if (textInputRef.current.value === "") {
                toastr.warning("Response required.");
                return;
              }
              const numPointsVal = parseFloat(numPointsInputRef.current.value);
              if (
                isNaN(numPointsVal) ||
                numPointsVal < 0 ||
                numPointsVal > 11
              ) {
                toastr.warning("Invalid points count.");
                return;
              }
              const scope: Scope<ScopeType.TEAM_PUZZLE_144> = {
                type: ScopeType.TEAM_PUZZLE_144,
                teamId: displayedTeamId,
              };
              await sockClient.sendScopeStepAndWaitAsync(scope, {
                setResp: {
                  text: textInputRef.current.value,
                  numPoints: numPointsVal,
                },
              });
              toastr.success("Response submitted.");
              setRedirectCommand({ path: "/admin-queue" });
            })().catch(console.error);
          }}
        >
          Submit
        </button>
      </div>
    </div>
  );
}
