import { useState, useRef, useEffect } from "react";

import { ScopeType } from "sockapi/scope-types";
import { Scope } from "sockapi/scopes";

import { SubmitImageSlot } from "sockapi/direct-backend";
import {
  Puzzle139SharePermission,
  Puzzle139StatusType,
  Puzzle139Status,
  PUZZLE_139_CONFIG,
} from "sockapi/scope-specs/team-puzzle-139-spec";

import { useTeamId, useSockClient } from "stores/ServerInteractionStore";
import { useScopeStateResolvable, useIsHuntOver } from "stores/ScopeStateStore";
import { toastr } from "Globals";
import { useUILock } from "ui-locks";
import { makeSubmittedImageUrl } from "client-util";
import { Spinner } from "components/Loading";
import { ImageSubmission } from "components/PuzzleContent/puzzle-components";
import { SubmissionsClosedInfobox } from "components/PuzzleContent/puzzle-infoboxes";
import "./Puzzle139.css";

export function Puzzle139ResponseDisplay(props: { status?: Puzzle139Status }) {
  const { status } = props;
  if (status === undefined) return null;
  switch (status.type) {
    case Puzzle139StatusType.ACCEPTED:
      return (
        <div className="puzzle-139-accepted">
          <p>
            <b>Your submission was accepted!</b>
          </p>
          <p>{status.comment}</p>
        </div>
      );
    case Puzzle139StatusType.REJECTED:
      return (
        <div className="puzzle-139-rejected">
          <div>
            <p>
              <b>Your submission was rejected with the following response:</b>
            </p>
            <p>{status.reason}</p>
            <p>
              <b>Please make the necessary corrections and try again.</b>
            </p>
          </div>
        </div>
      );
  }
  return null;
}

export function Puzzle139() {
  const teamId = useTeamId();
  const sockClient = useSockClient();
  const puz139State = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_139,
    teamId === null ? null : { teamId }
  );
  const isHuntOver = useIsHuntOver();
  const textInputRef = useRef<HTMLTextAreaElement>(null);
  const [sharePermission, setSharePermission] =
    useState<Puzzle139SharePermission>(Puzzle139SharePermission.NONE);
  const submitLock = useUILock();
  const { isHeld: isSubmitLockHeld } = submitLock;

  useEffect(() => {
    if (puz139State === null) return;
    if (textInputRef.current === null) return;
    const { submissionText, sharePermission } = puz139State;
    if (submissionText !== undefined)
      textInputRef.current.value = submissionText;
    if (sharePermission !== undefined) setSharePermission(sharePermission);
  }, [puz139State]);

  if (teamId === null || puz139State === null) return <Spinner />;
  const { diagramUrl, status } = puz139State;
  const isLocked =
    status !== undefined && status.type !== Puzzle139StatusType.REJECTED;
  const scope: Scope<ScopeType.TEAM_PUZZLE_139> = {
    type: ScopeType.TEAM_PUZZLE_139,
    teamId,
  };
  const sharePermissionRadioButtons: [Puzzle139SharePermission, string][] = [
    [Puzzle139SharePermission.BOTH, "Yes, both picture and fun fact"],
    [Puzzle139SharePermission.FACT, "Yes, only the fun fact"],
    [Puzzle139SharePermission.NONE, "No"],
  ];

  return (
    <div className="puzzle-139">
      <h4>Upload a picture (only JPG supported, max 5MB)</h4>
      <ImageSubmission
        isLocked={isLocked}
        slot={SubmitImageSlot.PUZZLE_139}
        supportedMimeTypes={["image/jpeg"]}
        maxFileSize={5e6}
        onSubmitSuccess={async () => {
          await sockClient.sendScopeStepAndWaitAsync(scope, {
            downloadDiagramUrl: true,
          });
        }}
      />
      {diagramUrl === undefined ? null : (
        <img
          className="puzzle-139-preview-image"
          src={makeSubmittedImageUrl(diagramUrl)}
        />
      )}
      <h4>Write a fun fact</h4>
      <textarea
        disabled={isLocked}
        maxLength={PUZZLE_139_CONFIG.maxLength}
        ref={textInputRef}
      />
      <h4>Grant permission to share your submission in wrap-up?</h4>
      <form className="form-field-radio-buttons">
        {sharePermissionRadioButtons.map(([value, label]) => (
          <label key={value}>
            <input
              type="radio"
              checked={sharePermission === value}
              disabled={isLocked}
              onChange={() => setSharePermission(value)}
            />
            {label}
          </label>
        ))}
      </form>
      {!isLocked ? (
        <>
          {isHuntOver ? <SubmissionsClosedInfobox /> : null}
          <div>
            <button
              disabled={isSubmitLockHeld}
              onClick={() => {
                submitLock.acquireAndRun(async (getIsCanceled) => {
                  if (textInputRef.current === null) return;
                  if (diagramUrl === undefined) {
                    toastr.warning("Please upload a picture.");
                    return;
                  }
                  if (textInputRef.current.value.trim() === "") {
                    toastr.warning("Please enter a fun fact.");
                    return;
                  }
                  await sockClient.sendScopeStepAndWaitAsync(scope, {
                    submit: {
                      submissionText: textInputRef.current.value,
                      sharePermission,
                    },
                  });
                });
              }}
            >
              Submit
            </button>
          </div>
        </>
      ) : null}
      {status !== undefined && status.type === Puzzle139StatusType.PENDING ? (
        <>Thank you for your submission. We will evaluate it shortly.</>
      ) : null}
      <Puzzle139ResponseDisplay status={status} />
    </div>
  );
}
