import { useState, useEffect } from "react";
import * as runtime from "react/jsx-runtime";
import Twemoji from "react-twemoji";
import { MDXContent, MDXComponents } from "mdx/types";
import { EvaluateOptions, evaluate } from "@mdx-js/mdx";
import {
  PuzzleContentType,
  getPuzzleContentStaticDir,
} from "sockapi/scope-specs/puzzle-content-spec";
import { ScopeType } from "sockapi/scope-types";
import { PUZZLE_105_CONFIG } from "sockapi/scope-specs/team-puzzle-105-spec";
import { PUZZLE_144_CONFIG } from "sockapi/scope-specs/team-puzzle-144-spec";
import { HOPE_POOL_CONFIG } from "sockapi/scope-specs/hope-pool-spec";
import { useScopeStateResolvable } from "stores/ScopeStateStore";
import {
  Blanks,
  Flavor,
  PuzzleImage,
  PuzzleGallery,
  PuzzleAudio,
  Table,
  SpoilerText,
  AuthorsNotes,
} from "components/PuzzleContent/puzzle-components";
import { PuzzleGrid } from "components/PuzzleContent/puzzle-grid";
import TeamDisplayNameDisplay from "components/TeamDisplayNameDisplay";
import { Cutscene } from "components/PuzzleContent/Cutscene";
import { PuzzleContentPreviewWithLink } from "components/PuzzleContent/PuzzleContentPreview";
import {
  Puzzle105Content,
  Puzzle105,
} from "components/PuzzleContent/Puzzle105";
import { Puzzle139 } from "components/PuzzleContent/Puzzle139";
import { Puzzle144, Puzzle144Rubric } from "components/PuzzleContent/Puzzle144";
import { Berry } from "components/PuzzleContent/Puzzle192";
import { Puzzle205 } from "components/PuzzleContent/Puzzle205";
import { Puzzle207 } from "components/PuzzleContent/Puzzle207";
import HopePool from "components/PuzzleContent/HopePool";
import { Puzzle329Card } from "components/PuzzleContent/Puzzle329";
import { FaviconChanger } from "components/PuzzleContent/Puzzle214";
import { Hopeless } from "components/PuzzleContent/Puzzle264";
import {
  BlocksPuzzle,
  BlocksPuzzleBoard,
} from "components/PuzzleContent/BlocksPuzzle";
import { ExchangePuzzle } from "components/PuzzleContent/ExchangePuzzle";
import { OlivePuzzle } from "components/PuzzleContent/OlivePuzzle";
import { FarmerPuzzle } from "components/PuzzleContent/FarmerPuzzle";
import { BranchChecker } from "components/PuzzleContent/BranchChecker";

type PuzzleContentProps = {
  puzName: string;
  staticPuzDir: string;
  firstKeyframeId?: string;
  answer?: string;
  PUZZLE_144_CONFIG: typeof PUZZLE_144_CONFIG;
  HOPE_POOL_CONFIG: typeof HOPE_POOL_CONFIG;
  isPreview: boolean;
};

const makePuzzleContentComponents = (
  props: PuzzleContentProps
): MDXComponents => {
  const { puzName, staticPuzDir, firstKeyframeId, answer, isPreview } = props;
  return {
    pre: (props) => (
      <pre
        {...{
          "data-skip-inline-styles": "true",
        }}
      >
        {props.children}
      </pre>
    ),
    code: (props) => (
      <code
        {...{
          "data-skip-inline-styles": "true",
        }}
      >
        {props.children}
      </code>
    ),
    Flavor,
    Image: (props) => <PuzzleImage staticPuzDir={staticPuzDir} {...props} />,
    Gallery: (props) => (
      <PuzzleGallery staticPuzDir={staticPuzDir} {...props} />
    ),
    Audio: (props) => (
      <PuzzleAudio
        staticPuzDir={staticPuzDir}
        isPreview={isPreview}
        {...props}
      />
    ),
    PuzzleGrid,
    Table,
    Blanks,
    Answer: (props: { index?: number }) => {
      const { index } = props;
      if (answer === undefined)
        throw new Error(`no answer found for ${puzName}`);
      if (index !== undefined) {
        return <SpoilerText>{answer.split(" / ")[index]}</SpoilerText>;
      }
      return <SpoilerText>{answer}</SpoilerText>;
    },
    AuthorsNotes,
    TeamDisplayNameDisplay,
    Cutscene: () => {
      if (firstKeyframeId === undefined)
        throw new Error(`no firstKeyframeId found for ${puzName}`);
      return <Cutscene puzName={puzName} firstKeyframeId={firstKeyframeId} />;
    },
    PuzzleContentPreviewWithLink,
    Puzzle105Content,
    Puzzle105,
    Puzzle105CheckTitleRateLimitMinutes: () => (
      <>{PUZZLE_105_CONFIG.checkTitleRateLimitIntervalMinutes}</>
    ),
    Puzzle139,
    Puzzle144,
    Puzzle144Rubric,
    Berry,
    Puzzle205,
    Puzzle207,
    HopePool,
    Puzzle329Card: (props) => (
      <Puzzle329Card staticPuzDir={staticPuzDir} {...props} />
    ),
    FaviconChanger,
    Hopeless,
    BlocksPuzzle,
    BlocksPuzzleBoard,
    ExchangePuzzle,
    OlivePuzzle,
    FarmerPuzzle,
    BranchChecker,
    Twemoji,
  };
};

export type PuzzleContentRenderContext = {
  elem: MDXContent;
  puzName: string;
  components: MDXComponents;
  props: PuzzleContentProps;
};

export const usePuzzleContent = (
  puzName: string,
  contentType: PuzzleContentType,
  isPreview?: boolean
) => {
  const scopeType: ScopeType = (() => {
    switch (contentType) {
      case PuzzleContentType.PUZZLE:
        return ScopeType.PUZZLE_CONTENT;
      case PuzzleContentType.SOLUTION:
        return ScopeType.SOLUTION_CONTENT;
    }
  })();
  const puzzleContent = useScopeStateResolvable(scopeType, {
    puzName,
  });

  // Track all dependencies of the puzzle content element in the
  // same state to ensure that they all update together.
  const [renderCtx, setRenderCtx] = useState<PuzzleContentRenderContext | null>(
    null
  );

  useEffect(() => {
    if (puzzleContent === null) {
      setRenderCtx(null);
      return;
    }

    const { content, firstKeyframeId, answer } = puzzleContent;
    const staticPuzDir = getPuzzleContentStaticDir(puzzleContent);
    const props: PuzzleContentProps = {
      puzName,
      staticPuzDir,
      firstKeyframeId,
      answer: answer ?? undefined,
      PUZZLE_144_CONFIG,
      HOPE_POOL_CONFIG,
      isPreview: isPreview ?? false,
    };
    const components = makePuzzleContentComponents(props);

    let isCanceled = false;
    // There seems to be an incompatibility with MDX and our React
    // version's JSX runtime type, but explicitly casting seems to
    // be fine.
    evaluate(content, runtime as EvaluateOptions)
      .then((module) => {
        if (isCanceled) return;
        setRenderCtx({
          elem: module.default,
          puzName,
          components,
          props,
        });
      })
      .catch((err) => {
        console.error(err);

        if (isCanceled) return;
        setRenderCtx(null);
      });

    return () => {
      isCanceled = true;
    };
  }, [puzzleContent, puzName, isPreview]);

  return {
    puzzleContent,
    renderCtx:
      renderCtx !== null && renderCtx.puzName === puzName ? renderCtx : null,
  };
};
