import { useEffect, useRef, memo, useState } from "react";
import Twemoji from "react-twemoji";
import { ScopeType } from "sockapi/scope-types";
import { useTeamId, useSockClient } from "stores/ServerInteractionStore";
import {
  useTeamScopeState,
  usePuzzleData,
  useLeaderboardNumSolves,
} from "stores/ScopeStateStore";
import { useNavStore } from "stores/NavStore";
import {
  useUpdateBrowserWidePersistentState,
  makeDefaultCutsceneState,
} from "stores/BrowserWidePersistentState";
import { CompletionIcon } from "components/Icon";
import { RoutedLink } from "components/Link";
import { LargeSpinner, Spinner } from "components/Loading";
import { useEvent } from "client-util";
import Globals from "Globals";
import "./SunrisePage.css";

const clamp = (min: number, value: number, max: number) =>
  value < min ? min : value > max ? max : value;

function EndContent() {
  const teamScopeState = useTeamScopeState();
  const numSolves = useLeaderboardNumSolves();

  if (teamScopeState === null || numSolves === null)
    return <Spinner inline={true} />;

  const { finishedData } = teamScopeState;
  const numSolveCountPuzzles = finishedData?.numSolveCountPuzzles;

  return (
    <>
      <div className="sunrise-text">
        <div className="sunrise-text-inner">
          <h1>Congratulations on finishing Galactic Puzzle Hunt 2024!</h1>
          <div>
            You will receive more information shortly via email.
            <br />
            In the meantime,{" "}
            <a href="https://docs.google.com/forms/d/e/1FAIpQLSdaia1TWjVDAb9Bq91XvT_kbJCmJW86sYpdE_IvBf3QMjZp7A/viewform?usp=sf_link">
              let us know your feedback
            </a>
            !
          </div>
          <div className="sunrise-text-completion">
            {numSolveCountPuzzles !== undefined ? (
              <>
                <span className="sunrise-text-completion-percent">
                  {Math.floor((numSolves / numSolveCountPuzzles) * 100)}%
                </span>{" "}
                stars restored{" "}
                <span className="sunrise-text-completion-percent">
                  <CompletionIcon
                    numSolves={numSolves}
                    numSolveCountPuzzles={numSolveCountPuzzles}
                  />
                </span>
              </>
            ) : null}
          </div>
          <div className="sunrise-text-back-button">
            <RoutedLink path="/camp" button={true}>
              Back
            </RoutedLink>
          </div>
        </div>
      </div>
      {numSolveCountPuzzles !== undefined &&
      numSolves !== null &&
      numSolves >= numSolveCountPuzzles ? (
        <Twemoji
          className="sunrise-thing"
          options={{ folder: "svg", ext: ".svg" }}
        >
          🕶️
        </Twemoji>
      ) : null}
    </>
  );
}

const Sunrise = memo(function Sunrise(props: { onDone: () => void }) {
  const { onDone } = props;
  const [showHint, setShowHint] = useState(false);

  const onDoneEvent = useEvent(onDone);
  const isDisabled = useRef(false);
  const isAutoscrollTriggered = useRef(false);

  const mainWrapper = useRef<HTMLDivElement>(null);
  const circles1 = useRef<HTMLImageElement>(null);
  const circles2 = useRef<HTMLImageElement>(null);
  const stars = useRef<HTMLDivElement>(null);
  const sun = useRef<HTMLImageElement>(null);
  const sunset = useRef<HTMLDivElement>(null);
  const overlay = useRef<HTMLDivElement>(null);
  const grassContainer = useRef<HTMLDivElement>(null);
  const scrollHint = useRef<HTMLDivElement>(null);

  const setAnimateStyles = useEvent((progress: number) => {
    const Color = Globals.Color;

    const sky00 = new Color("#0f89ff").range("#6e40a6");
    const sky01 = new Color("#6e40a6").range("#34378b");
    const sky10 = new Color("#40c8ff").range("#5256ff");
    const sky11 = new Color("#5256ff").range("#34378b");

    const sunset0 = new Color("#0f89ff00").range("#5a66d200");
    const sunset1 = new Color("#0f89ff").range("#9d74d9");
    const sunset2 = new Color("#33a8ff").range("#f586b1");
    const sunset3 = new Color("#40c8ff").range("#ff9898");

    if (
      mainWrapper.current === null ||
      circles1.current === null ||
      circles2.current === null ||
      stars.current === null ||
      sun.current === null ||
      sunset.current === null ||
      overlay.current === null ||
      grassContainer.current === null
    )
      return;

    mainWrapper.current.style.background =
      progress < 1
        ? `linear-gradient(${sky00(progress)}, ${sky10(progress)})`
        : progress < 2
        ? `linear-gradient(${sky01(progress - 1)}, ${sky11(progress - 1)})`
        : "#34378b";

    sunset.current.style.background =
      progress < 0.66
        ? `linear-gradient(${[
            `${sunset0(progress * 1.5)} 0%`,
            `${sunset1(progress * 1.5)} 19%`,
            `${sunset2(progress * 1.5)} 37%`,
            `${sunset3(progress * 1.5)} 56%`,
            "#e0e3ad 75%",
          ].join(", ")})`
        : "linear-gradient(#5a66d200 0%, #9d74d9 19%, #f586b1 37%, #ff9898 56%, #e0e3ad 75%)";
    sunset.current.style.transform = `translate(0, ${45 * progress - 33}vh)`;

    sun.current.style.transform = `translate(0, ${60 * progress}%)`;
    overlay.current.style.opacity = clamp(
      0,
      1 - Math.abs(progress - 0.6),
      1
    ).toString();
    stars.current.style.opacity = clamp(0, progress * 2 - 1, 1).toString();
    circles1.current.style.opacity = circles2.current.style.opacity = clamp(
      0,
      progress * 3 - 2,
      0.3
    ).toString();

    grassContainer.current.style.filter = `brightness(${clamp(
      0,
      1 - progress / 2,
      1
    )})`;

    if (showHint && scrollHint.current !== null) {
      scrollHint.current.style.opacity = clamp(
        0,
        2 * progress - 5,
        1
      ).toString();
      scrollHint.current.style.transition = "none";
    }

    const slideNavElem = document.getElementById("slide-nav");
    if (slideNavElem !== null) {
      slideNavElem.style.display = progress > 1 ? "none" : "";
      slideNavElem.style.opacity = `${(1 - progress) * 100}%`;
    }
  });

  useEffect(() => {
    const animate = () => {
      if (isDisabled.current ?? false) return;
      const progress = window.scrollY / window.innerHeight;
      if (progress < 0.1) {
        isDisabled.current = true;
        setAnimateStyles(0);
        const sunriseElem = document.getElementById("sunrise");
        if (sunriseElem !== null) sunriseElem.style.height = "100vh";
        onDoneEvent();
        return;
      } else if (progress < 0.6 && !isAutoscrollTriggered.current) {
        window.scrollTo({ top: 0, behavior: "smooth" });
        isAutoscrollTriggered.current = true;
      }
      setAnimateStyles(progress);
    };

    const scale = () => {
      if (
        mainWrapper.current === null ||
        circles1.current === null ||
        circles2.current === null ||
        stars.current === null ||
        sun.current === null ||
        sunset.current === null ||
        overlay.current === null ||
        grassContainer.current === null
      )
        return;

      const width = window.innerWidth;

      grassContainer.current.style.transform = `scale(${width / 790})`;
    };

    const onScroll = () => {
      window.requestAnimationFrame(animate);
    };

    const onResize = () => {
      window.requestAnimationFrame(scale);
    };

    if (mainWrapper.current !== null) {
      window.scrollTo(0, mainWrapper.current.scrollHeight);
      setTimeout(() => {
        const progress = window.scrollY / window.innerHeight;
        if (progress > 2.9) {
          setShowHint(true);
        }
      }, 4000);
    }

    window.requestAnimationFrame(scale);
    window.requestAnimationFrame(animate);
    window.addEventListener("scroll", onScroll);
    window.addEventListener("resize", onResize);

    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onResize);

      const slideNavElem = document.getElementById("slide-nav");
      if (slideNavElem !== null) {
        slideNavElem.style.display = "";
        slideNavElem.style.opacity = "";
      }
    };
  }, [onDoneEvent, setAnimateStyles]);

  return (
    <div className="sunrise" id="sunrise" ref={mainWrapper}>
      <EndContent />
      <img
        className="circles"
        id="circles1"
        ref={circles1}
        src="/static/images/bg/circles.png"
      />
      <img
        className="circles"
        id="circles2"
        ref={circles2}
        src="/static/images/bg/circles.png"
      />
      <div id="stars" ref={stars}></div>
      <div id="sunset" ref={sunset}></div>
      <img id="sun" ref={sun} src="/static/images/bg/sun.svg" />
      <div id="grass-wrapper">
        <div id="grass-container" ref={grassContainer}>
          <div className="grass" id="flowers1">
            <img
              className="grass-anim-3 blur1"
              src="/static/images/bg/flower.png"
            />
          </div>
          <div className="grass" id="flowers2">
            <img
              className="grass-anim-2 blur2"
              src="/static/images/bg/flowers.png"
            />
          </div>
          <div className="grass" id="grass4">
            <img className="grass-anim-2" src="/static/images/bg/grass2.png" />
          </div>
          <div className="grass" id="grass7">
            <img className="grass-anim-1" src="/static/images/bg/grass3.png" />
          </div>
          <div className="grass" id="grass2">
            <img className="grass-anim-1" src="/static/images/bg/grass2.png" />
          </div>
          <div className="grass" id="grass8">
            <img className="grass-anim-2" src="/static/images/bg/grass2.png" />
          </div>
          <div className="grass" id="grass3">
            <img
              className="grass-anim-1 blur1"
              src="/static/images/bg/grass1.png"
            />
          </div>
          <div className="grass" id="grass5">
            <img
              className="grass-anim-1 blur2"
              src="/static/images/bg/grass3.png"
            />
          </div>
          <div className="grass" id="grass6">
            <img className="grass-anim-2" src="/static/images/bg/grass1.png" />
          </div>
          <div className="grass" id="grass1">
            <img
              className="grass-anim-1 blur2"
              src="/static/images/bg/grass3.png"
            />
          </div>
          <div className="grass" id="base">
            <img src="/static/images/bg/base.png" />
          </div>
          <div id="overlay" ref={overlay}>
            <img src="/static/images/bg/overlay.png" />
          </div>
        </div>
      </div>
      <div
        id="scroll-hint"
        ref={scrollHint}
        style={{ opacity: showHint ? 1 : 0 }}
      >
        ⇡
      </div>
    </div>
  );
});

function SunrisePage() {
  const teamId = useTeamId();
  const sockClient = useSockClient();
  const teamScopeState = useTeamScopeState();
  const finalCutscenePuzName =
    Object.values(teamScopeState?.puzzles ?? {}).find(
      ({ isFinalCutscene = false }) => isFinalCutscene
    )?.puzName ?? null;
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);
  const puzData = usePuzzleData(finalCutscenePuzName);
  const updateBrowserWidePersistentState =
    useUpdateBrowserWidePersistentState();

  useEffect(() => {
    if (teamScopeState === null) return;
    // If the final cutscene is not unlocked, then the user should
    // not have access to this page.
    if (finalCutscenePuzName === null) setRedirectCommand({ path: "/puzzles" });
  }, [teamScopeState, finalCutscenePuzName, setRedirectCommand]);

  if (teamId === null || finalCutscenePuzName === null || puzData === null)
    return <LargeSpinner />;

  return (
    <Sunrise
      onDone={() => {
        (async () => {
          const puzName = finalCutscenePuzName;
          updateBrowserWidePersistentState({
            cutscenesState: {
              [puzName]: makeDefaultCutsceneState(),
            },
            completedStoryBeats: { [puzName]: true },
          });
          if (puzData.solveTime === undefined)
            await sockClient.sendScopeStepAndWaitAsync(
              {
                type: ScopeType.TEAM_CUTSCENES,
                teamId,
              },
              {
                setCutsceneComplete: puzName,
              }
            );
        })().catch(console.error);
      }}
    />
  );
}

export default SunrisePage;
