import { useState, useEffect, useMemo } from "react";
import { AnimatePresence, motion } from "framer-motion";
import "overlayscrollbars/overlayscrollbars.css";
import { autohideOverlayScrollbarsOptions } from "HuntLib";

import { sleepAsync } from "util/timers";
import {
  GachaPull,
  PULL_ANIMATION_TIME_MS,
  PULL_ANIMATION_EXPIRY_TIME_MS,
} from "sockapi/gacha/pulls";
import { useTeamId } from "stores/ServerInteractionStore";
import { useCampLayout } from "stores/NavStore";
import { useTeamGachaScopeState } from "stores/ScopeStateStore";
import {
  useGachaStore,
  usePullLock,
  GachaActivePullAnimation,
} from "stores/GachaStore";
import { ShortDate } from "components/dates";
import { PrizeIcon } from "components/Icon";
import { LargeSpinner } from "components/Loading";
import Tooltip from "components/Tooltip";
import StarMap from "components/Gacha/StarMap";
import WishResultDisplay from "components/Gacha/WishResultDisplay";
import WishAnimation from "components/Gacha/WishAnimation";
import { useEvent, clsObj } from "client-util";

import "./CampPage.css";
import HorizontalScrollbar from "components/HorizontalScrollbar";

export function QueuedWishAnimations(props: {
  onPullStart?: () => void;
  onPullEnd?: (pull: GachaActivePullAnimation) => void;
}) {
  const { onPullStart, onPullEnd } = props;
  const pullLock = usePullLock();
  const activePullAnimation = useGachaStore(
    (state) => state.activePullAnimation
  );
  const setActivePullAnimation = useGachaStore(
    (state) => state.setActivePullAnimation
  );
  const pendingPull = useGachaStore((state) => state.pendingPull);
  const setPendingPull = useGachaStore((state) => state.setPendingPull);
  const pullsQueue = useGachaStore((state) => state.pullsQueue);
  const shiftPullsQueue = useGachaStore((state) => state.shiftPullsQueue);
  const teamId = useTeamId();

  const handleWishAnimationEnd = useEvent((pullId?: string) => {
    if (activePullAnimation === null) return;
    if (pullId !== undefined && activePullAnimation.pullId !== pullId) return;
    shiftPullsQueue(activePullAnimation.pullId);
    onPullEnd?.(activePullAnimation);
    setPendingPull(null);
    setActivePullAnimation(null);
  });

  useEffect(() => {
    if (pullLock.isHeld) return;
    if (activePullAnimation !== null) return;
    if (pullsQueue.length <= 0) return;
    const nextActivePullIndex = pullsQueue.findIndex(
      ({ pullId, pull: { timestamp } }) =>
        (pendingPull !== null && pullId === pendingPull.pullId) ||
        Date.now() - timestamp < PULL_ANIMATION_EXPIRY_TIME_MS
    );
    if (nextActivePullIndex === -1) {
      shiftPullsQueue();
      return;
    }
    const { pullId, pull } = pullsQueue[nextActivePullIndex];
    onPullStart?.();
    setActivePullAnimation({
      pullId,
      pull,
    });
    let isCanceled = false;
    // Complete the wish after a while in case there is an
    // issue with the video load.
    sleepAsync(PULL_ANIMATION_TIME_MS + 1000)
      .then(() => {
        if (isCanceled) return;
        handleWishAnimationEnd(pullId);
      })
      .catch(() => console.error);
    return () => {
      isCanceled = true;
    };
  }, [
    pullLock,
    activePullAnimation,
    setActivePullAnimation,
    pullsQueue,
    shiftPullsQueue,
    pendingPull,
    handleWishAnimationEnd,
    onPullStart,
  ]);

  useEffect(() => {
    return () => {
      setActivePullAnimation(null);
    };
  }, [setActivePullAnimation]);

  if (teamId === null) return null;
  if (activePullAnimation === null) return null;

  return (
    <div className="camp-page-animation">
      <WishAnimation
        teamId={teamId}
        pull={activePullAnimation.pull}
        onJustBeforeEnd={handleWishAnimationEnd}
      />
    </div>
  );
}

function CampPage() {
  const teamId = useTeamId();
  const [shownPull, setShownPull] = useState<{
    pullId: string;
    pull: GachaPull;
    isLatest: boolean;
  } | null>(null);
  const handleWishStart = useEvent(() => {
    setShownPull(null);
  });
  const handleWishEnd = useEvent((pull: GachaActivePullAnimation) => {
    setShownPull({ ...pull, isLatest: true });
  });
  const teamGachaScopeState = useTeamGachaScopeState(teamId);
  const serverPullLocksHeld = useGachaStore(
    (state) => state.serverPullLocksHeld
  );
  const pullsQueue = useGachaStore((state) => state.pullsQueue);
  const pulls = teamGachaScopeState === null ? null : teamGachaScopeState.pulls;
  const activePullAnimation = useGachaStore(
    (state) => state.activePullAnimation
  );
  const campLayout = useCampLayout();

  const pastWishes = useMemo(
    () =>
      pulls !== null
        ? Object.entries(pulls).sort(
            ([aId, a], [bId, b]) => b.timestamp - a.timestamp
          )
        : null,
    [pulls]
  );
  useEffect(() => {
    // super hack: scroll to carousel start whenever we get a new pull
    setTimeout(() => {
      document.querySelector(".wish-carousel-entry")?.scrollIntoView({
        behavior: "smooth",
        inline: "center",
      });
    }, 10);
  }, [pulls]);

  const lockedPullIds: { [pullId: string]: true } = useMemo(() => {
    const lockedPullIds = { ...serverPullLocksHeld };
    for (const { pullId } of pullsQueue) {
      lockedPullIds[pullId] = true;
    }
    if (activePullAnimation !== null)
      lockedPullIds[activePullAnimation.pullId] = true;
    return lockedPullIds;
  }, [serverPullLocksHeld, pullsQueue, activePullAnimation]);

  if (teamId === null || pastWishes === null || campLayout === null)
    return <LargeSpinner />;
  const { isBeforeFirstWish } = campLayout;

  // Motion elements must be the direct child of an AnimatePresence in order
  // to animate on exit, hence the weird nesting here.
  return (
    <div
      className={`camp-page-root ${
        shownPull !== null ? "camp-page-wish-modal-shown" : ""
      }`}
    >
      <StarMap />
      <AnimatePresence>
        <QueuedWishAnimations
          key="camp-page-wish-animations"
          onPullStart={handleWishStart}
          onPullEnd={handleWishEnd}
        />
        {isBeforeFirstWish ? (
          <div className="camp-page-gather-team-notice-wrapper">
            <div className="camp-page-gather-team-notice">
              <h1>Gather your team!</h1>
              <div>
                When everyone&rsquo;s done talking to Stelle, gather on this
                page, and wish.
              </div>
            </div>
          </div>
        ) : null}
        {shownPull !== null ? (
          <motion.div
            className="camp-page-wish-modal-wrapper"
            key="camp-page-wish-modal-wrapper"
            initial={{
              backgroundColor: "#00000000",
              opacity: shownPull.isLatest ? 1 : 0,
            }}
            animate={{ backgroundColor: "#00000080", opacity: 1 }}
            exit={{ backgroundColor: "#00000000", opacity: 0 }}
            transition={{ duration: shownPull.isLatest ? 0.3 : 0.15 }}
            onClick={(e) => {
              setShownPull(null);
              e.stopPropagation();
            }}
          >
            <motion.div
              className="camp-page-wish-modal"
              key="camp-page-wish-modal"
              initial={{
                filter: "blur(2px) brightness(2)",
                transform: "scale(1.02)",
                opacity: 0.2,
              }}
              animate={{
                filter: "blur(0) brightness(1)",
                transform: "scale(1)",
                opacity: 1,
              }}
              transition={{ duration: shownPull.isLatest ? 1 : 0 }}
              onClick={(e) => e.stopPropagation()}
            >
              <WishResultDisplay
                teamId={teamId}
                pull={shownPull.pull}
                isLatest={shownPull.isLatest}
              />
            </motion.div>
          </motion.div>
        ) : null}
      </AnimatePresence>
      <div className="wish-carousel">
        <HorizontalScrollbar options={autohideOverlayScrollbarsOptions} defer>
          <div
            className="wish-carousel-inner"
            onClick={(e) => {
              setShownPull(null);
              e.stopPropagation();
            }}
          >
            <AnimatePresence>
              {pastWishes.map(([pullId, pull]) =>
                lockedPullIds[pullId] ?? false ? null : (
                  <motion.div
                    layout
                    key={pull.timestamp}
                    initial={{ opacity: 0, scale: 0.8 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ type: "spring" }}
                  >
                    <Tooltip
                      className={clsObj({
                        "wish-carousel-entry": true,
                        active: pullId === shownPull?.pullId,
                      })}
                      text={<ShortDate timestamp={pull.timestamp} />}
                      onClick={(e) => {
                        setShownPull({ pullId, pull, isLatest: false });
                        e.stopPropagation();
                        (e.target as HTMLElement).scrollIntoView({
                          behavior: "smooth",
                          inline: "center",
                        });
                      }}
                    >
                      <PrizeIcon teamId={teamId} prize={pull} />
                    </Tooltip>
                  </motion.div>
                )
              )}
            </AnimatePresence>
          </div>
        </HorizontalScrollbar>
      </div>
    </div>
  );
}

export default CampPage;
