function WrapupNavLink({
  path,
  children,
}: {
  path: string;
  children: ReactNode;
}) {
  const inPath = useMatch(path);
  return inPath ? (
    <b style={{ color: "var(--link-text-color)" }}>{children}</b>
  ) : (
    <RoutedLink path={path}>{children}</RoutedLink>
  );
}

export function WrapupWrapper({ children }: { children: ReactNode }) {
  const contentRef = useRef<HTMLDivElement>(null);
  const [heads, setHeads] = useState<Element[]>([]);

  useEffect(() => {
    if (heads.length > 0 || !contentRef.current) return;
    setHeads([
      ...contentRef.current.querySelectorAll(
        "h1,h2,h3:not(.puzzle-header-elem),h4,h5"
      ),
    ]);
  }, [heads.length]);

  useEffect(() => {
    const links = document.querySelectorAll(".wrapup-page aside div");
    const highlight = () => {
      const rects = heads.map((head) => head.getBoundingClientRect());
      heads.forEach((_, i) =>
        links[i].classList.toggle(
          "highlight",
          (!rects[i + 1] || rects[i + 1].top > 0) && rects[i].top < innerHeight
        )
      );
    };
    document.addEventListener("scroll", highlight, { passive: true });
    highlight();
    return () => document.removeEventListener("scroll", highlight);
  }, [heads]);

  return (
    <div className="below-nav centered-page wrapup-page">
      <aside>
        {heads.map((head, i) => (
          <div
            key={i}
            style={{ paddingLeft: `${head.tagName.slice(1)}ch` }}
            onClick={() => head.scrollIntoView()}
          >
            {head.textContent}
          </div>
        ))}
      </aside>
      <div className="wrapup-page-links">
        <WrapupNavLink path="/wrapup">Wrap-Up</WrapupNavLink>
        <StarIcon rarity={Rarity.COMMON} />
        <WrapupNavLink path="/wrapup/stats">Statistics</WrapupNavLink>
        <WrapupNavLink path="/wrapup/submissions">Submissions</WrapupNavLink>
        <WrapupNavLink path="/wrapup/ama">Ask Us Anything</WrapupNavLink>
        <WrapupNavLink path="/wrapup/gacha">Gacha Mechanics</WrapupNavLink>
        <WrapupNavLink path="/wrapup/fluidity">On Fluidity</WrapupNavLink>
      </div>
      <div className="wrapup-page-content" ref={contentRef}>
        {children}
      </div>
    </div>
  );
}

