function CustomPuzzleSubmissionSlide(props: {
  teamId: string;
  displayName: string;
}) {
  const { teamId, displayName } = props;
  const puz105StateResult = useScopeStateResolvablePosthuntable(
    ScopeType.TEAM_PUZZLE_105,
    { teamId },
    { forcePosthuntIfNotAdmin: true }
  );
  const [message, setMessage] = useState("");

  if (puz105StateResult === null) return <Spinner inline />;
  if (!puz105StateResult.success)
    return <DownloadFailedDisplay {...puz105StateResult} />;

  const puz105State = puz105StateResult.state;
  const isAvailableInGacha =
    puz105State.status !== undefined &&
    puz105State.status.type === Puzzle105StatusType.ACCEPTED &&
    (puz105State.status.isAvailableInGacha ?? false);
  const puzName = `${PUZZLE_105_CONFIG.customPuzzlePuzNamePrefix}${teamId}`;

  // Static answer checker for non-wishable custom puzzles.
  // This only works for puzzles with only one answer possibility,
  // which should be true for all non-wishable custom puzzles.
  const submit = (
    event:
      | React.FormEvent<HTMLFormElement>
      | React.MouseEvent<HTMLAnchorElement>
  ) => {
    event.preventDefault();

    const formData = new FormData(event.target as HTMLFormElement);
    const answer = formData.get("answer") as string | null;
    if (!answer) return;

    const normalized = normalizeAnswer(answer);
    const correctAnswer = normalizeAnswer(puz105State.formFields.answer);

    setMessage(`${normalized}: ${normalized === correctAnswer ? "✅" : "❌"}`);
  };

  return (
    <div className="custom-puzzle-slide">
      <div className="puzzle-header">
        <h3 className="puzzle-header-elem">
          <Twemoji tag="span">{displayName}</Twemoji>
        </h3>
      </div>
      <PuzzleContentDisplay puzName={puzName} />
      <div className="note">
        {isAvailableInGacha ? (
          <>
            This puzzle is available via wishing.{" "}
            <PuzzleLink puzName={puzName}>View its puzzle page.</PuzzleLink>
          </>
        ) : (
          <>
            This puzzle is not available via wishing. You can check your answer
            here:
            <form className="submit-answer-form" onSubmit={submit}>
              <div className="input-group">
                <input
                  type="text"
                  name="answer"
                  autoComplete="off"
                  required={true}
                />
                <a className="delete-row" href="#" onClick={submit}>
                  →
                </a>
              </div>
            </form>
            {message && <p>{message}</p>}
            <details>
              <summary>View solution</summary>
              <div className="solution-answer">
                <b>Answer:</b>{" "}
                <div className="solved-title-answer spoiler">
                  {puz105State.formFields.answer}
                </div>
              </div>
              <PuzzleContentDisplay
                puzName={puzName}
                contentType={PuzzleContentType.SOLUTION}
              />
            </details>
          </>
        )}
      </div>
    </div>
  );
}

function SubmissionsCarousel({ kind }: { kind: "free" | "tree" }) {
  const publicSubmissionsStateResult = useGlobalScopeStatePosthuntable(
    ScopeType.PUBLIC_SUBMISSIONS,
    true,
    { hasPosthunt: true }
  );
  const teamListResult = useGlobalScopeStatePosthuntable(
    ScopeType.TEAM_LIST,
    true,
    { hasPosthunt: true }
  );
  const wrapupCustomPuzzleRedirectCommand = useNavStore(
    (store) => store.wrapupCustomPuzzleRedirectCommand
  );
  const setWrapupCustomPuzzleRedirectCommand = useNavStore(
    (store) => store.setWrapupCustomPuzzleRedirectCommand
  );
  const carouselRef = useRef<HTMLDivElement>(null);

  const defaultTypeFilter = useMemo(
    () => ({
      [PublicSubmissionType.PUBLIC_CUSTOM_PUZZLE]: kind === "free",
      [PublicSubmissionType.PRIVATE_CUSTOM_PUZZLE]: kind === "free",
      [PublicSubmissionType.HUG_A_TREE]: kind === "tree",
      [PublicSubmissionType.HUG_A_TREE_FACT_ONLY]: kind === "tree",
    }),
    [kind]
  );
  const [typeFilter, setTypeFilter] = useState(defaultTypeFilter);
  const [teamNameFilter, setTeamNameFilter] = useState("");
  const [displayNameFilter, setDisplayNameFilter] = useState("");
  const [selectedSubmissionId, setSelectedSubmissionId] = useState("");

  const isDisplayNameFilterEnabled = kind === "free";

  const taskFilter = useCallback(
    (taskSummary: PublicSubmissionSummary) => {
      const { teamId, displayName, type } = taskSummary;
      if (teamListResult === null) return false;
      if (!teamListResult.success) return false;
      return (
        teamListResult.state[teamId].displayName
          .toLowerCase()
          .trim()
          .includes(teamNameFilter.toLowerCase().trim()) &&
        (!isDisplayNameFilterEnabled ||
          (displayName ?? UNTITLED_PUZZLE_DISPLAY_NAME)
            .toLowerCase()
            .trim()
            .includes(displayNameFilter.toLowerCase().trim())) &&
        (typeFilter[type] ?? true)
      );
    },
    [
      teamListResult,
      teamNameFilter,
      displayNameFilter,
      typeFilter,
      isDisplayNameFilterEnabled,
    ]
  );

  const submissions = useMemo(() => {
    if (!publicSubmissionsStateResult?.success) return [];
    const typeOrder = {
      [PublicSubmissionType.PUBLIC_CUSTOM_PUZZLE]: 0,
      [PublicSubmissionType.PRIVATE_CUSTOM_PUZZLE]: 1,
      [PublicSubmissionType.HUG_A_TREE]: 2,
      [PublicSubmissionType.HUG_A_TREE_FACT_ONLY]: 3,
    };
    return Object.entries(publicSubmissionsStateResult.state.submissions)
      .filter(([submissionId, submission]) => taskFilter(submission))
      .sort(([submissionId1, submission1], [submissionId2, submission2]) => {
        const typeOrder1 = typeOrder[submission1.type];
        const typeOrder2 = typeOrder[submission2.type];
        const diffTypeOrder = typeOrder1 - typeOrder2;
        if (diffTypeOrder !== 0) return diffTypeOrder;
        return submission1.respondTime - submission2.respondTime;
      });
  }, [publicSubmissionsStateResult, taskFilter]);

  const numPerType = useMemo(() => {
    const numPerType: {
      [type in PublicSubmissionType]?: number;
    } = {};
    for (const [_, taskSummary] of submissions) {
      numPerType[taskSummary.type] = (numPerType[taskSummary.type] ?? 0) + 1;
    }
    return numPerType;
  }, [submissions]);

  useEffect(() => {
    if (kind !== "free") return;
    if (carouselRef.current === null) return;
    if (wrapupCustomPuzzleRedirectCommand === null) return;
    setTypeFilter(defaultTypeFilter);
    setTeamNameFilter("");
    setDisplayNameFilter("");
    setSelectedSubmissionId(wrapupCustomPuzzleRedirectCommand);
    carouselRef.current.scrollIntoView();
    setWrapupCustomPuzzleRedirectCommand(null);
  }, [
    wrapupCustomPuzzleRedirectCommand,
    setWrapupCustomPuzzleRedirectCommand,
    kind,
    defaultTypeFilter,
  ]);

  if (teamListResult === null) return <Spinner inline />;
  if (!teamListResult.success)
    return <DownloadFailedDisplay {...teamListResult} />;
  if (publicSubmissionsStateResult === null) return <Spinner inline />;
  if (!publicSubmissionsStateResult.success)
    return <DownloadFailedDisplay {...publicSubmissionsStateResult} />;

  const selectedSubmissionIndex = (() => {
    const index = submissions.findIndex(
      ([submissionId]) => submissionId === selectedSubmissionId
    );
    if (index === -1) return 0;
    return index;
  })();
  const selectedSubmissionEntry = submissions[selectedSubmissionIndex];

  return (
    <div className="wrapup-carousel" ref={carouselRef}>
      <div className="admin-queue-header">
        <div className="admin-queue-header-actions">
          <div className="admin-queue-team-name-filter">
            <Twemoji tag="span">🔍</Twemoji>{" "}
            <input
              type="text"
              placeholder="Filter by team name"
              value={teamNameFilter}
              onChange={(e) => {
                setTeamNameFilter(e.target.value);
              }}
            />
          </div>
          {isDisplayNameFilterEnabled ? (
            <div className="admin-queue-team-name-filter">
              <Twemoji tag="span">🔍</Twemoji>{" "}
              <input
                type="text"
                placeholder="Filter by title"
                value={displayNameFilter}
                onChange={(e) => {
                  setDisplayNameFilter(e.target.value);
                }}
              />
            </div>
          ) : null}
        </div>
      </div>
      <div className="admin-queue-header admin-queue-type-filter">
        {SUBMISSIONS_CAROUSEL_FILTERS.filter(
          (filter) => filter.kind === kind
        ).map(({ type, text }) => (
          <button
            key={type}
            className={clsObj({ active: typeFilter[type] ?? true })}
            onClick={() => {
              setTypeFilter({
                ...typeFilter,
                [type]: !(typeFilter[type] ?? true),
              });
            }}
          >
            {text}{" "}
            {typeFilter[type] ?? true ? <>({numPerType[type] ?? 0})</> : null}
          </button>
        ))}
      </div>
      {selectedSubmissionEntry !== undefined ? (
        <div className="wrapup-carousel-selector">
          <div
            className="control-prev control-arrow"
            onClick={() => {
              const newIndex = Math.max(selectedSubmissionIndex - 1, 0);
              setSelectedSubmissionId(submissions[newIndex][0]);
            }}
          />
          <ul className="control-dots">
            {submissions.map(([submissionId, _]) => (
              <li
                key={submissionId}
                className={clsObj({
                  dot: true,
                  selected:
                    selectedSubmissionEntry !== undefined &&
                    selectedSubmissionEntry[0] === submissionId,
                })}
                onClick={() => {
                  setSelectedSubmissionId(submissionId);
                }}
              ></li>
            ))}
          </ul>
          <div
            className="control-next control-arrow"
            onClick={() => {
              const newIndex = Math.min(
                selectedSubmissionIndex + 1,
                submissions.length - 1
              );
              setSelectedSubmissionId(submissions[newIndex][0]);
            }}
          />
        </div>
      ) : null}
      <div className="admin-queue-list">
        {selectedSubmissionEntry !== undefined ? (
          <>
            {(([_, submission]) => {
              switch (submission.type) {
                case PublicSubmissionType.PUBLIC_CUSTOM_PUZZLE:
                case PublicSubmissionType.PRIVATE_CUSTOM_PUZZLE: {
                  return (
                    <CustomPuzzleSubmissionSlide
                      key={submission.teamId}
                      teamId={submission.teamId}
                      displayName={
                        submission.displayName ?? UNTITLED_PUZZLE_DISPLAY_NAME
                      }
                    />
                  );
                }
                case PublicSubmissionType.HUG_A_TREE:
                case PublicSubmissionType.HUG_A_TREE_FACT_ONLY: {
                  const { teamId } = submission;
                  return (
                    <Puzzle139AdminQueueTaskSummaryDisplay
                      teamId={teamId}
                      omitTitle
                    />
                  );
                }
              }
            })(selectedSubmissionEntry)}
          </>
        ) : null}
      </div>
    </div>
  );
}

function WrapupPrivateCustomPuzzleLink({ teamId }: { teamId: string }) {
  const publicSubmissionsStateResult = useGlobalScopeStatePosthuntable(
    ScopeType.PUBLIC_SUBMISSIONS,
    true,
    { hasPosthunt: true }
  );
  const setWrapupCustomPuzzleRedirectCommand = useNavStore(
    (store) => store.setWrapupCustomPuzzleRedirectCommand
  );

  if (publicSubmissionsStateResult === null) return <Spinner inline />;
  if (!publicSubmissionsStateResult.success)
    return <DownloadFailedDisplay {...publicSubmissionsStateResult} />;

  const submissionEntry = Object.entries(
    publicSubmissionsStateResult.state.submissions
  ).find(
    ([submissionId, submission]) =>
      submission.type === PublicSubmissionType.PRIVATE_CUSTOM_PUZZLE &&
      submission.teamId === teamId
  );

  if (submissionEntry === undefined) {
    console.error(`could not find custom puzzle for team ${teamId}`);
    return (
      <a
        href="#"
        onClick={(event) => {
          event.preventDefault();
        }}
      >
        ???
      </a>
    );
  }

  const [submissionId, { displayName = UNTITLED_PUZZLE_DISPLAY_NAME }] =
    submissionEntry;

  return (
    <a
      href="#"
      onClick={(event) => {
        event.preventDefault();
        setWrapupCustomPuzzleRedirectCommand(submissionId);
      }}
    >
      {displayName}
    </a>
  );
}

function Credits({ credits }: { credits: string }) {
  const lines = credits
    .trim()
    .split("\n")
    .map((line, i) => {
      if (line === "") {
        return <div key={i} className="credits-break" />;
      }

      if (!line.includes(":")) {
        return (
          <div key={i} className="credits-header">
            <StarIcon rarity={Rarity.UNCOMMON} />
            {line}
            <StarIcon rarity={Rarity.UNCOMMON} />
          </div>
        );
      }

      const [title, people] = line.split(": ");
      const peopleList = people
        .split(", ")
        .map((person, i) => <li key={i}>{person}</li>);

      const cols = (() => {
        switch (peopleList.length) {
          case 1:
            return 1;
          case 2:
          case 4:
            return 2;
          default:
            return 3;
        }
      })();
      const remainder = peopleList.length % cols;

      return (
        <div key={i} className="credit">
          <div className="credit-title">{title}</div>
          <ul className={`credit-people col-${cols} remainder-${remainder}`}>
            {peopleList}
          </ul>
        </div>
      );
    });

  return <div className="credits">{lines}</div>;
}

