function SFXTester() {
  const sfxPlayer = useRef(new SFXPlayer());

  useEffect(() => {
    sfxPlayer.current = new SFXPlayer();

    return () => {
      sfxPlayer.current.teardown();
    };
  }, []);

  return (
    <div>
      <div className="sfx-tester">
        {MAPPED_SFX_NAME.map(([sfx, name]) => (
          <button
            key={name}
            onClick={() => sfxPlayer.current.stopAndPlay(SFX[sfx])}
          >
            {name}
          </button>
        ))}
      </div>
      <div className="sfx-tester-volume-control">
        <VolumeControl />
      </div>
    </div>
  );
}

