import { useRef, useState } from "react";
import { ScopeType } from "sockapi/scope-types";
import { normalizeAnswer } from "sockapi/answers";
import { BIG_BRANCH_CONFIG } from "sockapi/scope-specs/team-big-branch-spec";
import { useUILock } from "ui-locks";
import { useTeamId, useSockClient } from "stores/ServerInteractionStore";
import { Spinner } from "components/Loading";
import "./BranchChecker.css";

export function BranchChecker() {
  const inputRef = useRef<HTMLInputElement>(null);
  const [result, setResult] = useState<{
    val: string;
    isCorrect: boolean;
  } | null>(null);
  const checkAnswerLock = useUILock();
  const sockClient = useSockClient();
  const teamId = useTeamId();

  if (teamId === null) return <Spinner inline={true} />;

  const checkAnswer = () => {
    checkAnswerLock.acquireAndRun(async (getIsCanceled) => {
      if (inputRef.current === null) return;
      const val = normalizeAnswer(inputRef.current.value);

      const resp = await sockClient.sendScopeStepAndWaitAsync(
        { type: ScopeType.TEAM_BIG_BRANCH, teamId },
        { checkAnswer: val }
      );
      if (getIsCanceled()) return;
      if (resp === null) return;
      const { checkAnswerResp } = resp;
      if (checkAnswerResp === undefined) return;
      const { isRateLimited = false, isCorrect } = checkAnswerResp;
      if (isRateLimited) {
        toastr.warning(
          `Please limit your guesses to ${
            BIG_BRANCH_CONFIG.rateLimit.num
          } per ${BIG_BRANCH_CONFIG.rateLimit.intervalMs / 1000} seconds.`,
          "Rate limited"
        );
        return;
      }
      if (isCorrect === undefined)
        throw new Error("no response received for big branch checker");
      setResult({ val, isCorrect });
      inputRef.current.value = "";
    });
  };

  return (
    <div className="branch-checker">
      <input
        type="text"
        ref={inputRef}
        onKeyDown={(e) => {
          if (e.key === "Enter") checkAnswer();
        }}
        disabled={checkAnswerLock.isHeld}
      />{" "}
      <button
        onClick={() => {
          checkAnswer();
        }}
        disabled={checkAnswerLock.isHeld}
      >
        Check
      </button>
      {result === null ? null : result.isCorrect ? (
        <div className="branch-checker-result-correct">
          {result.val} is a correct answer!
        </div>
      ) : (
        <div className="branch-checker-result-incorrect">
          {result.val} is not a correct answer.
        </div>
      )}
    </div>
  );
}
