type FarmerSimulationNodeDatum = d3.SimulationNodeDatum & {
  node: FarmerGraphNode;
  highlight?: true;
  isLastNode?: true;
};
type FarmerSimulationLinkDatum =
  d3.SimulationLinkDatum<FarmerSimulationNodeDatum> & {
    source: FarmerSimulationNodeDatum;
    target: FarmerSimulationNodeDatum;
    isExtra?: true;
  };

function FarmerD3Graph(props: {
  graph: FarmerGraph;
  lastNodeId?: string;
  highlightNodes?: string[];
  extraEdges?: FarmerGraphEdge[];
}) {
  const { graph, lastNodeId, highlightNodes, extraEdges } = props;

  const d3StateRef = useRef<{
    simulation: d3.Simulation<
      FarmerSimulationNodeDatum,
      FarmerSimulationLinkDatum
    >;
    nodeSel: d3.Selection<
      SVGGElement,
      FarmerSimulationNodeDatum,
      SVGGElement,
      undefined
    >;
    linkSel: d3.Selection<
      SVGLineElement,
      FarmerSimulationLinkDatum,
      SVGGElement,
      undefined
    >;
    nodesDict: { [nodeId: string]: FarmerSimulationNodeDatum };
  } | null>(null);
  const graphRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (graph === null) return;
    if (graphRef.current === null) return;

    const origNodesDict = d3StateRef.current?.nodesDict ?? {};
    const d3NodesDict: {
      [nodeId: string]: FarmerSimulationNodeDatum;
    } = Object.fromEntries(
      graph.nodes.map((node) => [
        node.nodeId,
        origNodesDict[node.nodeId] ?? { node },
      ])
    );
    const didNodesChange = !(
      Object.keys(origNodesDict).length === Object.keys(d3NodesDict).length &&
      Object.keys(origNodesDict).every(
        (nodeId) => d3NodesDict[nodeId] !== undefined
      )
    );
    const d3Nodes = Object.values(d3NodesDict);
    const d3Links = [
      ...graph.edges
        .filter(
          ({ nodeId1, nodeId2 }) =>
            d3NodesDict[nodeId1] !== undefined &&
            d3NodesDict[nodeId2] !== undefined
        )
        .map(({ nodeId1, nodeId2 }) => ({
          source: d3NodesDict[nodeId1],
          target: d3NodesDict[nodeId2],
        })),
      ...(extraEdges ?? []).map(({ nodeId1, nodeId2 }) => ({
        source: d3NodesDict[nodeId1],
        target: d3NodesDict[nodeId2],
        isExtra: true,
      })),
    ];
    const didNumLinksChange =
      d3Links.length !== (d3StateRef.current?.linkSel.size() ?? 0);

    // Recompute highlighted nodes.
    for (const node of d3Nodes) {
      delete node.highlight;
      delete node.isLastNode;
    }
    for (const nodeId of highlightNodes ?? []) {
      d3NodesDict[nodeId].highlight = true;
    }
    if (lastNodeId !== undefined) d3NodesDict[lastNodeId].isLastNode = true;

    const drag = d3
      .drag<SVGGElement, FarmerSimulationNodeDatum>()
      .on(
        "start",
        (
          event: d3.D3DragEvent<
            SVGGElement,
            FarmerSimulationNodeDatum,
            FarmerSimulationNodeDatum
          >
        ) => {
          // Reheat the simulation when drag starts, and fix the subject position.
          if (!event.active) simulation.alphaTarget(0.3).restart();
          event.subject.fx = event.subject.x;
          event.subject.fy = event.subject.y;
        }
      )
      .on(
        "drag",
        (
          event: d3.D3DragEvent<
            SVGGElement,
            FarmerSimulationNodeDatum,
            FarmerSimulationNodeDatum
          >
        ) => {
          // Update the subject (dragged node) position during drag.
          event.subject.fx = event.x;
          event.subject.fy = event.y;
        }
      )
      .on(
        "end",
        (
          event: d3.D3DragEvent<
            SVGGElement,
            FarmerSimulationNodeDatum,
            FarmerSimulationNodeDatum
          >
        ) => {
          // Restore the target alpha so the simulation cools after dragging ends.
          // Unfix the subject position now that it’s no longer being dragged.
          if (!event.active) simulation.alphaTarget(0);
          event.subject.fx = null;
          event.subject.fy = null;
        }
      );

    if (d3StateRef.current === null) {
      const width = 800;
      const height = 600;

      const simulation = d3
        .forceSimulation(d3Nodes)
        .force(
          "link",
          d3
            .forceLink<FarmerSimulationNodeDatum, FarmerSimulationLinkDatum>(
              d3Links
            )
            .id(({ node }) => node.nodeId)
        )
        .force("charge", d3.forceManyBody().strength(-500))
        .force("x", d3.forceX())
        .force("y", d3.forceY());

      const svg = d3
        .create("svg")
        .attr("width", width)
        .attr("height", height)
        .attr("viewBox", [-width / 2, -height / 2, width, height])
        .attr("style", "max-width: 100%; height: auto;");

      const linkSel = svg
        .append("g")
        .selectAll<SVGLineElement, FarmerSimulationLinkDatum>("line");

      const nodeSel = svg
        .append("g")
        .attr("stroke", "#fff")
        .attr("stroke-width", 1.5)
        .selectAll<SVGGElement, FarmerSimulationNodeDatum>("g");

      // Set the position attributes of links and nodes each time the simulation ticks.
      simulation.on("tick", () => {
        if (d3StateRef.current === null) return;
        const { nodeSel, linkSel } = d3StateRef.current;

        linkSel
          .attr("x1", (d) => d.source.x?.toString() ?? null)
          .attr("y1", (d) => d.source.y?.toString() ?? null)
          .attr("x2", (d) => d.target.x?.toString() ?? null)
          .attr("y2", (d) => d.target.y?.toString() ?? null);

        nodeSel.attr("transform", (d) => `translate(${d.x}, ${d.y})`);
      });

      const svgNode = svg.node();
      if (svgNode !== null) graphRef.current.append(svgNode);

      d3StateRef.current = {
        simulation,
        nodeSel,
        linkSel,
        nodesDict: d3NodesDict,
      };
    }

    d3StateRef.current.nodeSel = d3StateRef.current.nodeSel
      .data(d3Nodes)
      .join(
        (enter) =>
          enter
            .append("g")
            .call((g) =>
              g
                .append("circle")
                .attr("r", 5)
                .attr("fill", (d) =>
                  d.highlight ?? false
                    ? "#ea2"
                    : d.isLastNode ?? false
                    ? "#5bb"
                    : "#26b"
                )
            )
            .call((g) =>
              g
                .append("text")
                .text((d) => d.node.content)
                .attr("stroke", "none")
                .attr("fill", (d) =>
                  d.highlight ?? false
                    ? "#fc6"
                    : d.isLastNode ?? false
                    ? "#bfc"
                    : "#adf"
                )
                .attr("dominant-baseline", "middle")
                .attr("transform", "translate(7, 0)")
                .attr("style", "user-select: none;")
            ),
        (update) =>
          update
            .call((g) =>
              (
                g.selectAll("circle") as d3.Selection<
                  SVGGElement,
                  FarmerSimulationNodeDatum,
                  SVGGElement,
                  FarmerSimulationNodeDatum
                >
              ).attr("fill", (d) =>
                d.highlight ?? false
                  ? "#ea2"
                  : d.isLastNode ?? false
                  ? "#5bb"
                  : "#26b"
              )
            )
            .call((g) =>
              (
                g.selectAll("text") as d3.Selection<
                  SVGGElement,
                  FarmerSimulationNodeDatum,
                  SVGGElement,
                  FarmerSimulationNodeDatum
                >
              ).attr("fill", (d) =>
                d.highlight ?? false
                  ? "#fc6"
                  : d.isLastNode ?? false
                  ? "#bfc"
                  : "#adf"
              )
            )
      )
      .call(drag);
    d3StateRef.current.linkSel = d3StateRef.current.linkSel
      .data(d3Links)
      .join("line");
    d3StateRef.current.nodesDict = d3NodesDict;
    const { simulation, nodeSel, linkSel } = d3StateRef.current;

    nodeSel.attr("style", (d) =>
      d.isLastNode ?? false ? "filter: drop-shadow(0 0 5px #befb)" : "none"
    );
    linkSel
      .attr("stroke", (d) => (d.isExtra ?? false ? "#865" : "#999"))
      .attr("stroke-width", (d) => (d.isExtra ?? false ? 1 : 3))
      .attr("stroke-opacity", (d) => (d.isExtra ?? false ? 0.8 : 0.8));

    // update d3 nodes
    simulation.nodes(d3Nodes).force(
      "link",
      d3
        .forceLink<FarmerSimulationNodeDatum, FarmerSimulationLinkDatum>(
          d3Links
        )
        .id(({ node }) => node.nodeId)
    );

    if (didNodesChange || didNumLinksChange) simulation.alpha(1).restart();
  }, [graph, highlightNodes, extraEdges, lastNodeId]);

  if (graph === null) return <Spinner inline={true} />;

  return <div ref={graphRef} />;
}

function FarmerPuzzleStageDisplay(props: {
  graphId: string;
  stage: SockAPIFarmerStage;
}) {
  const { graphId, stage } = props;
  const teamId = useTeamId();
  const teamFarmerState = useScopeStateResolvable(
    ScopeType.TEAM_FARMER,
    teamId === null ? null : { teamId }
  );
  const puzzleContent = useScopeStateResolvable(ScopeType.PUZZLE_CONTENT, {
    puzName: PUZNAME_FARMER,
  });
  const sockClient = useSockClient();
  const actionLock = useUILock();
  const addNodeInputRef = useRef<HTMLInputElement>(null);
  const graph = teamFarmerState?.stages[graphId]?.graph ?? null;
  const evaluation = teamFarmerState?.stages[graphId]?.graph.evaluation ?? null;
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const isSpectating = useIsAdminEnabledStore((state) => state.isSpectating);

  useEffect(() => {
    if (actionLock.isHeld) return;
    if (addNodeInputRef.current === null) return;
    addNodeInputRef.current.focus();
  }, [actionLock.isHeld]);

  if (graph === null || teamId === null || puzzleContent === null)
    return <Spinner inline={true} />;
  const { nodes } = graph;
  const {
    metadata: { instruction, targetImgName, targetNumNodes },
    isSolved = false,
  } = stage;
  const numNodes = nodes.length;
  const isFarmFull =
    targetNumNodes !== undefined &&
    numNodes >= targetNumNodes &&
    !settings.workshopMode;
  const staticPuzDir = getPuzzleContentStaticDir(puzzleContent);

  const evaluationMessage = (() => {
    if (evaluation === null) return null;
    if (!evaluation.success)
      return "Nice work! But the shape of the farm looks off, somehow.";
    if (evaluation.highlightNodes === undefined)
      return "You completed the farm! But there are more farms to build.";
    if (evaluation.highlightNodes.length === 0)
      return "You completed the farm! None of the patches are productive, but that’s okay.";
    return "You completed the farm! I’ve highlighted the productive patches in yellow.";
  })();

  const scope: Scope<ScopeType.TEAM_FARMER> = {
    type: ScopeType.TEAM_FARMER,
    teamId,
  };

  const addNode = () => {
    if (addNodeInputRef.current === null) return;
    if (addNodeInputRef.current.value.trim() === "") return;
    const content = addNodeInputRef.current.value;

    actionLock.acquireAndRun(async (getIsCanceled) => {
      const respPayload = await sockClient.sendScopeStepAndWaitAsync(scope, {
        isWorkshop: settings.workshopMode ? true : undefined,
        addNode: {
          graphId,
          content,
        },
      });
      if (
        getIsCanceled() ||
        respPayload === null ||
        addNodeInputRef.current === null
      )
        return;
      const { addNodeResp } = respPayload;
      if (addNodeResp === undefined)
        throw new Error(
          `expect addNodeResp in response ${JSON.stringify(respPayload)}`
        );

      // Return something to make typescript check for exhaustiveness.
      ((): true => {
        switch (addNodeResp.type) {
          case FarmerAddNodeResponseType.SUCCESS:
            return true;
          case FarmerAddNodeResponseType.SERVER_ERROR:
            toastr.error(
              "The server encountered an error processing your request."
            );
            return true;
          case FarmerAddNodeResponseType.INVALID_WORD:
            toastr.error(`"${content}" was not found in our dictionary.`);
            return true;
          case FarmerAddNodeResponseType.INVALID_NODE:
          case FarmerAddNodeResponseType.NO_EDGE:
          case FarmerAddNodeResponseType.NOT_IN_CATEGORY:
            toastr.error(`"${content}" could not be added to the farm.`);
            return true;
          case FarmerAddNodeResponseType.DUPLICATE:
            toastr.error(`"${content}" already exists in the farm.`);
            return true;
          case FarmerAddNodeResponseType.TOO_MANY_NODES:
            toastr.error("The farm is full!");
            return true;
        }
      })();
      addNodeInputRef.current.value = "";
    });
  };

  return (
    <>
      {shouldDisplayAdmin && !isSpectating ? (
        <>
          <hr />
          <button
            onClick={() => {
              sockClient.sendScopeStep(scope, {
                adminSetGraphSolved: graphId,
              });
            }}
            disabled={isSolved}
          >
            Set solved (admin only)
          </button>
          <hr />
        </>
      ) : null}
      {targetImgName !== undefined ? (
        <div className="farmer-target">
          <h5>Target</h5>
          <PuzzleImage
            center
            staticPuzDir={staticPuzDir}
            name={targetImgName}
          />
        </div>
      ) : null}
      {instruction !== undefined ? <div>{instruction}</div> : null}
      <div>
        <input
          type="text"
          ref={addNodeInputRef}
          disabled={actionLock.isHeld || isFarmFull}
          onKeyDown={(e) => {
            if (e.key === "Enter") addNode();
          }}
          className="farmer-input"
        />
        <span className="farmer-graph-buttons">
          <button
            onClick={() => addNode()}
            disabled={isSpectating || actionLock.isHeld || isFarmFull}
          >
            Add
          </button>
          <button
            onClick={() => {
              actionLock.acquireAndRun(async (getIsCanceled) => {
                await sockClient.sendScopeStepAndWaitAsync(scope, {
                  undoGraph: graphId,
                });
              });
            }}
            disabled={
              isSpectating || actionLock.isHeld || !isFarmerStageUndoable(stage)
            }
          >
            ↶
          </button>
          <button
            onClick={() => {
              actionLock.acquireAndRun(async (getIsCanceled) => {
                await sockClient.sendScopeStepAndWaitAsync(scope, {
                  isWorkshop: settings.workshopMode ? true : undefined,
                  redoGraph: graphId,
                });
              });
            }}
            disabled={
              isSpectating || actionLock.isHeld || !isFarmerStageRedoable(stage)
            }
          >
            ↷
          </button>
          <button
            onClick={() => {
              actionLock.acquireAndRun(async (getIsCanceled) => {
                await sockClient.sendScopeStepAndWaitAsync(scope, {
                  resetGraph: graphId,
                });
              });
            }}
            disabled={
              isSpectating || actionLock.isHeld || graph.nodes.length <= 0
            }
          >
            Reset
          </button>
        </span>
        {targetNumNodes !== undefined ? (
          <span>
            {numNodes} / {targetNumNodes}
          </span>
        ) : null}
      </div>
      {evaluationMessage !== null ? (
        <div className="farmer-evaluation">
          <b>{evaluationMessage}</b>
        </div>
      ) : null}
      <FarmerD3Graph
        graph={graph}
        highlightNodes={evaluation?.highlightNodes}
        lastNodeId={
          evaluation?.success ?? false
            ? undefined
            : graph.nodes[graph.nodes.length - 1]?.nodeId
        }
      />
      {graph.nodes.length > 0 ? (
        <div>
          Patches added: {graph.nodes.map(({ content }) => content).join(", ")}
        </div>
      ) : null}
    </>
  );
}

function FarmerMapDisplay() {
  const teamId = useTeamId();
  const teamFarmerState = useScopeStateResolvable(
    ScopeType.TEAM_FARMER,
    teamId === null ? null : { teamId }
  );

  if (teamFarmerState === null) return <Spinner inline={true} />;
  const { stages, mapEdges, mapExtraEdges } = teamFarmerState;

  const nodes = Object.entries(stages).map(
    ([
      graphId,
      {
        metadata: { displayName },
      },
    ]) => ({
      nodeId: graphId,
      content: displayName.toUpperCase(),
    })
  );
  const graph = {
    nodes,
    edges: mapEdges,
    redoNodes: [],
  };
  const solves = Object.entries(stages)
    .filter(([graphId, { isSolved }]) => isSolved)
    .map(([graphId]) => graphId);

  return (
    <FarmerD3Graph
      graph={graph}
      highlightNodes={solves}
      extraEdges={mapExtraEdges}
    />
  );
}

export function FarmerPuzzle() {
  const teamId = useTeamId();
  const teamFarmerState = useScopeStateResolvable(
    ScopeType.TEAM_FARMER,
    teamId === null ? null : { teamId }
  );
  const [activeGraphId, setActiveGraphId] = useState<string | null>(null);
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const isSpectating = useIsAdminEnabledStore((state) => state.isSpectating);
  const sockClient = useSockClient();

  if (teamId === null || teamFarmerState === null)
    return <Spinner inline={true} />;
  const scope: Scope<ScopeType.TEAM_FARMER> = {
    type: ScopeType.TEAM_FARMER,
    teamId,
  };
  const stage =
    activeGraphId !== null
      ? teamFarmerState.stages[activeGraphId] ?? null
      : null;
  const sortedStages = Object.entries(teamFarmerState.stages).sort(
    ([graphId1, stage1], [graphId2, stage2]) =>
      stage1.metadata.displayName.localeCompare(stage2.metadata.displayName)
  );

  return (
    <>
      {shouldDisplayAdmin && !isSpectating ? (
        <div style={{ textAlign: "center" }}>
          <button
            onClick={() => {
              sockClient.sendScopeStep(scope, {
                adminResetProgress: true,
              });
            }}
          >
            Reset all progress (admin only)
          </button>
          <hr />
        </div>
      ) : null}
      <div>
        {stage === null || activeGraphId === null ? (
          <>
            <div>
              {sortedStages.map(
                ([
                  graphId,
                  {
                    metadata: { displayName },
                    isSolved,
                  },
                ]) => (
                  <button
                    key={graphId}
                    onClick={() => setActiveGraphId(graphId)}
                    className={
                      isSolved ? "farmer-stage-button-solved" : undefined
                    }
                  >
                    {displayName.toUpperCase()}
                  </button>
                )
              )}
            </div>
            <FarmerMapDisplay />
          </>
        ) : (
          <>
            <div className="farmer-stage-header">
              <h4>
                Currently building farm:{" "}
                {stage.metadata.displayName.toUpperCase()}{" "}
              </h4>
              <button onClick={() => setActiveGraphId(null)}>
                Back to map
              </button>
            </div>
            <FarmerPuzzleStageDisplay graphId={activeGraphId} stage={stage} />
            <p>
              For your convenience, you may drag patches around to reposition
              them on your screen.
            </p>
          </>
        )}
      </div>
    </>
  );
}
