import { useEffect, useRef, useState } from "react";

import { ScopeType } from "sockapi/scope-types";
import { Scope } from "sockapi/scopes";
import {
  Puzzle105StatusType,
  Puzzle105SharePermission,
} from "sockapi/scope-specs/team-puzzle-105-spec";

import { useSockClient } from "stores/ServerInteractionStore";
import { useScopeStateResolvable } from "stores/ScopeStateStore";
import { useNavStore } from "stores/NavStore";

import { Spinner } from "components/Loading";
import TeamDisplayNameDisplay from "components/TeamDisplayNameDisplay";
import { ButtonTabs } from "components/ButtonTabs";
import {
  Puzzle105Form,
  Puzzle105Preview,
} from "components/PuzzleContent/Puzzle105";
import { Rarity } from "sockapi/gacha/pulls";

export function Puzzle105AdminQueueTaskSummaryDisplay(props: {
  teamId: string;
}) {
  const { teamId: displayedTeamId } = props;
  const teamPuzzle105ScopeState = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_105,
    { teamId: displayedTeamId }
  );

  if (teamPuzzle105ScopeState === null) return <Spinner inline={true} />;
  const { status: submitStatus } = teamPuzzle105ScopeState;

  return (
    <div>
      <h4>Free Puzzle Submission</h4>
      <div>
        Team: <TeamDisplayNameDisplay teamId={displayedTeamId} />
      </div>
      <Puzzle105Preview teamId={displayedTeamId} />
      {!(
        submitStatus !== undefined &&
        submitStatus.type === Puzzle105StatusType.ACCEPTED &&
        submitStatus.isAvailableInGacha
      ) ? (
        <div>
          This puzzle is <b>not</b> available for wishing.
        </div>
      ) : null}
    </div>
  );
}

export function Puzzle105AdminQueueTaskDisplay(props: {
  teamId: string;
  isClaimedBySelf: boolean;
}) {
  const { teamId: displayedTeamId, isClaimedBySelf } = props;
  const teamPuzzle105ScopeState = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_105,
    { teamId: displayedTeamId }
  );
  const [isAccepted, setIsAccepted] = useState<boolean | null>(null);
  const reasonInputRef = useRef<HTMLTextAreaElement>(null);
  const moonickDialogueInputRef = useRef<HTMLTextAreaElement>(null);
  const isAvailableInGachaInputRef = useRef<HTMLInputElement>(null);
  const rarityInputRef = useRef<HTMLSelectElement>(null);
  const cannedHintInputRef = useRef<HTMLTextAreaElement>(null);
  const unlockInEdgesInputRef = useRef<HTMLTextAreaElement>(null);
  const unlockOutEdgesInputRef = useRef<HTMLTextAreaElement>(null);
  const [reasonInput, setReasonInput] = useState("");
  const [moonickDialogueInput, setMoonickDialogueInput] = useState("");
  const [cannedHintInput, setCannedHintInput] = useState("");
  const [unlockInEdgesInput, setUnlockInEdgesInput] = useState("");
  const [unlockOutEdgesInput, setUnlockOutEdgesInput] = useState("");
  const [isAvailableInGacha, setIsAvailableInGacha] = useState(false);
  const sockClient = useSockClient();
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);
  const submitStatus = teamPuzzle105ScopeState?.status;

  useEffect(() => {
    if (submitStatus === undefined) return;
    switch (submitStatus.type) {
      case Puzzle105StatusType.ACCEPTED:
        setIsAccepted(true);
        setIsAvailableInGacha(submitStatus.isAvailableInGacha ?? false);
        setMoonickDialogueInput(submitStatus.moonickDialogue);
        setCannedHintInput(submitStatus.cannedHint ?? "");
        setUnlockInEdgesInput(JSON.stringify(submitStatus.unlockInEdges) ?? "");
        setUnlockOutEdgesInput(
          JSON.stringify(submitStatus.unlockOutEdges) ?? ""
        );
        break;
      case Puzzle105StatusType.REJECTED:
        setIsAccepted(false);
        setReasonInput(submitStatus.reason);
        break;
    }
  }, [submitStatus, setMoonickDialogueInput, setReasonInput]);

  if (teamPuzzle105ScopeState === null) return <Spinner inline={true} />;

  const {
    formFields: { sharePermission },
  } = teamPuzzle105ScopeState;
  if (submitStatus === undefined) return <div>No submission found.</div>;
  const { submitTime } = submitStatus;
  const canAddToGacha =
    sharePermission !== null &&
    sharePermission === Puzzle105SharePermission.FULL;

  return (
    <div className="admin-queue-task-puzzle-105">
      <h2>Free Puzzle Submission</h2>
      <div>
        Team: <TeamDisplayNameDisplay teamId={displayedTeamId} />
      </div>
      {/* Admin can update the form here at any time. */}
      <Puzzle105Form teamId={displayedTeamId} hideAnswer={true} />
      <h1>Puzzle Preview</h1>
      <Puzzle105Preview teamId={displayedTeamId} />
      <hr />
      {!isClaimedBySelf ? (
        <div className="admin-queue-claim-this-task-notice">
          Claim this task to respond to it.
        </div>
      ) : null}
      <div>
        Set status:{" "}
        <div className="admin-queue-task-status-tabs">
          <ButtonTabs
            tabs={[
              { value: null, content: "Pending", disabled: true },
              { value: true, content: "Accepted" },
              {
                value: false,
                content: "Rejected",
                disabled: submitStatus.type === Puzzle105StatusType.ACCEPTED,
              },
            ]}
            selected={isAccepted}
            setSelected={setIsAccepted}
            disabled={!isClaimedBySelf}
          />
        </div>
      </div>
      {isAccepted === null ? null : isAccepted ? (
        <>
          <div>
            Enter some personalized Moonick dialogue, or use one of these
            templates:
          </div>
          <div>
            <ul>
              <li>I guess this does technically count as a puzzle...</li>
              <li>
                I&rsquo;m not sure I understand what&rsquo;s going on here, but
                I guess it works...
              </li>
              <li>...Eh, whatever. Good enough.</li>
              <li>Oh, this is a rather interesting puzzle.</li>
              <li>Wow. Mindblown. What a great puzzle.</li>
            </ul>
          </div>
          <div>
            Dialogue before: <i>An Application? Let me take a look.</i>
          </div>
          <div>
            <textarea
              disabled={!isClaimedBySelf}
              ref={moonickDialogueInputRef}
              value={moonickDialogueInput}
              onChange={(e) => setMoonickDialogueInput(e.target.value)}
            />
          </div>
          <div>
            Dialogue after: <i>Please wait while I prepare the paperwork.</i>
          </div>
          <div>
            Make available in gacha:{" "}
            <input
              type="checkbox"
              ref={isAvailableInGachaInputRef}
              checked={isAvailableInGacha}
              disabled={!canAddToGacha || !isClaimedBySelf}
              onChange={(e) => setIsAvailableInGacha(e.target.checked)}
            />{" "}
            {!canAddToGacha ? (
              <div className="admin-queue-puzzle-105-share-permission-error">
                (The team did not give us permission to share this puzzle.)
              </div>
            ) : null}
          </div>
          {isAvailableInGacha && (
            <>
              <div>
                Set rarity:
                <select
                  ref={rarityInputRef}
                  defaultValue={
                    submitStatus.type === Puzzle105StatusType.ACCEPTED
                      ? submitStatus.rarity
                      : Rarity.COMMON
                  }
                  disabled={!isClaimedBySelf}
                >
                  <option value={Rarity.COMMON}>Common</option>
                  <option value={Rarity.UNCOMMON}>Uncommon</option>
                  <option value={Rarity.RARE}>Rare</option>
                  <option value={Rarity.EPIC}>Epic</option>
                  <option value={Rarity.LEGENDARY}>Legendary</option>
                </select>
              </div>
              <div>
                Add up to one canned hint:
                <textarea
                  disabled={!isClaimedBySelf}
                  ref={cannedHintInputRef}
                  value={cannedHintInput}
                  onChange={(e) => setCannedHintInput(e.target.value)}
                />
              </div>
              <div>
                Set unlock in edges (e.g.{" "}
                {
                  '[{ "unlockGroupId": "fifty", "val": 1, "isUnlockOnly": true }]'
                }
                ):
                <textarea
                  disabled={!isClaimedBySelf}
                  ref={unlockInEdgesInputRef}
                  value={unlockInEdgesInput}
                  onChange={(e) => setUnlockInEdgesInput(e.target.value)}
                />
              </div>
              <div>
                Set unlock out edges (e.g.{" "}
                {'[{ "unlockGroupId": "fifty", "val": 1 }]'}):
                <textarea
                  disabled={!isClaimedBySelf}
                  ref={unlockOutEdgesInputRef}
                  value={unlockOutEdgesInput}
                  onChange={(e) => setUnlockOutEdgesInput(e.target.value)}
                />
              </div>
            </>
          )}
        </>
      ) : (
        <>
          <div>Enter reason below (will be displayed inline):</div>
          <div>
            Your application has been rejected for the following reason:{" "}
            <textarea
              disabled={!isClaimedBySelf}
              ref={reasonInputRef}
              value={reasonInput}
              onChange={(e) => setReasonInput(e.target.value)}
            />{" "}
            Please resubmit your Application after making the necessary
            modifications.
          </div>
        </>
      )}
      {isAccepted !== null ? (
        <div>
          <button
            onClick={() => {
              (async () => {
                if (isAccepted === null) return;
                const scope: Scope<ScopeType.TEAM_PUZZLE_105> = {
                  type: ScopeType.TEAM_PUZZLE_105,
                  teamId: displayedTeamId,
                };
                if (isAccepted) {
                  if (moonickDialogueInputRef.current === null) return;
                  if (isAvailableInGachaInputRef.current === null) return;
                  if (moonickDialogueInputRef.current.value === "") {
                    toastr.warning("Moonick dialogue required.");
                    return;
                  }
                  const cannedHintInputVal =
                    cannedHintInputRef.current?.value.trim() ?? "";
                  const unlockInEdgesInputVal =
                    unlockInEdgesInputRef.current?.value.trim() ?? "";
                  const unlockOutEdgesInputVal =
                    unlockOutEdgesInputRef.current?.value.trim() ?? "";
                  await sockClient.sendScopeStepAndWaitAsync(scope, {
                    setStatus: {
                      type: Puzzle105StatusType.ACCEPTED,
                      moonickDialogue: moonickDialogueInputRef.current.value,
                      isAvailableInGacha: isAvailableInGachaInputRef.current
                        .checked
                        ? true
                        : undefined,
                      submitTime,
                      rarity: rarityInputRef.current?.value as Rarity,
                      cannedHint:
                        cannedHintInputVal === ""
                          ? undefined
                          : cannedHintInputVal,
                      unlockInEdges:
                        unlockInEdgesInputVal === ""
                          ? undefined
                          : JSON.parse(unlockInEdgesInputVal),
                      unlockOutEdges:
                        unlockOutEdgesInputVal === ""
                          ? undefined
                          : JSON.parse(unlockOutEdgesInputVal),
                    },
                  });
                } else {
                  if (reasonInputRef.current === null) return;
                  if (reasonInputRef.current.value === "") {
                    toastr.warning("Reason required.");
                    return;
                  }
                  await sockClient.sendScopeStepAndWaitAsync(scope, {
                    setStatus: {
                      type: Puzzle105StatusType.REJECTED,
                      reason: reasonInputRef.current.value,
                      submitTime,
                    },
                  });
                }
                toastr.success("Response submitted.");
                setRedirectCommand({ path: "/admin-queue" });
              })().catch(console.error);
            }}
          >
            Submit
          </button>
        </div>
      ) : null}
    </div>
  );
}
