import { useEffect, useState } from "react";

import { ScopeType } from "sockapi/scope-types";
import { AdminQueueTaskSummary } from "sockapi/scope-specs/admin-queue-spec";
import { SockClient } from "sockapi/client/SockClient";
import { useSockClient } from "stores/ServerInteractionStore";
import { useScopeStateResolvable } from "stores/ScopeStateStore";
import { useNavStore } from "stores/NavStore";
import { useAdminPreferencesStore } from "stores/UserPreferencesStore";
import { Spinner } from "components/Loading";
import { RoutedLink } from "components/Link";
import { LongDate } from "components/dates";
import Modal from "components/Modal";

/** Returns whether the claim was successful. */
export const sendAdminQueueClaimStepAsync = async (
  sockClient: SockClient,
  taskId: string,
  staffId: string
): Promise<boolean> => {
  const isSuccessful = await sockClient.sendScopeStepAndWaitAsync(
    {
      type: ScopeType.ADMIN_QUEUE_TASK,
      taskId,
    },
    {
      claim: { staffId },
    }
  );
  if (isSuccessful === null) return false;
  if (!isSuccessful) toastr.error("Someone claimed before you!");
  return isSuccessful;
};

function ClaimedByDisplay(props: {
  taskId: string;
  taskSummary: AdminQueueTaskSummary;
  useClaimLink?: true;
}) {
  const { taskId, taskSummary, useClaimLink } = props;
  const adminQueueTaskScopeState = useScopeStateResolvable(
    ScopeType.ADMIN_QUEUE_TASK,
    {
      taskId,
    }
  );
  const staffId = useAdminPreferencesStore((state) => state.staffId);
  const sockClient = useSockClient();
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);
  const [showModal, setShowModal] = useState(false);

  useEffect(() => {
    if (staffId === null)
      setRedirectCommand({ path: "/admin-queue", replace: true });
  }, [staffId, setRedirectCommand]);

  if (adminQueueTaskScopeState === null || staffId === null)
    return <Spinner inline={true} />;
  const { claim } = adminQueueTaskScopeState;
  const isClaimedBySelf = claim !== undefined && claim.staffId === staffId;

  const onUnclaim = async () => {
    await sockClient.sendScopeStepAndWaitAsync(
      {
        type: ScopeType.ADMIN_QUEUE_TASK,
        taskId,
      },
      {
        unclaim: true,
      }
    );
    if (isClaimedBySelf) setRedirectCommand({ path: "/admin-queue" });
  };

  return (
    <div className="admin-queue-claimed-by">
      {claim === undefined ? (
        <div className="admin-queue-claim-button">
          {useClaimLink ?? false ? (
            <RoutedLink
              path={`/admin-queue/task/${taskId}/claim`}
              button={true}
            >
              Claim
            </RoutedLink>
          ) : (
            <button
              onClick={() => {
                (async () => {
                  await sendAdminQueueClaimStepAsync(
                    sockClient,
                    taskId,
                    staffId
                  );
                })().catch(console.error);
              }}
            >
              Claim
            </button>
          )}
        </div>
      ) : (
        <>
          <div className="admin-queue-claim-button">
            <button
              onClick={() => {
                if (isClaimedBySelf) {
                  onUnclaim().catch(console.error);
                } else {
                  setShowModal(true);
                }
              }}
            >
              {isClaimedBySelf ? "Unclaim" : "Kick"}
            </button>
          </div>
          <div className="admin-queue-task-metadata">
            <div>Claimed by: {claim.staffId}</div>
            <div>
              at <LongDate timestamp={claim.claimTime} />
            </div>
          </div>
        </>
      )}
      <div>
        <div className="admin-queue-task-metadata">
          Opened: <LongDate timestamp={taskSummary.requestTime} />
        </div>
        {taskSummary.respondTime !== undefined ? (
          <div className="admin-queue-task-metadata">
            Closed: <LongDate timestamp={taskSummary.respondTime} />
          </div>
        ) : null}
      </div>
      <Modal
        isOpen={showModal}
        title={`Are you sure you want to kick ${claim?.staffId} from this task?`}
        footerChildren={
          <>
            <button onClick={() => setShowModal(false)}>Cancel</button>
            <button
              onClick={() => {
                onUnclaim()
                  .then(() => setShowModal(false))
                  .catch(console.error);
              }}
            >
              Kick
            </button>
          </>
        }
      />
    </div>
  );
}

export default ClaimedByDisplay;
