import { useCallback } from "react";

import { ScopeType } from "sockapi/scope-types";
import { PullAckType, PULL_COST } from "sockapi/gacha/pulls";
import { useCurrentHope } from "stores/ScopeStateStore";
import { useNavStore, useInPuzzlePage } from "stores/NavStore";
import {
  useGachaStore,
  usePullLock,
  useIsPullInProgress,
} from "stores/GachaStore";
import { useTeamId, useSockClient } from "stores/ServerInteractionStore";
import { useIsAdminEnabledStore } from "stores/UserPreferencesStore";
import settings from "settings";
import "./GachaButton.css";

function GachaButton() {
  const teamId = useTeamId();
  const sockClient = useSockClient();
  const isSpectating = useIsAdminEnabledStore((state) => state.isSpectating);
  const setPendingPull = useGachaStore((state) => state.setPendingPull);
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);
  const currentHope = useCurrentHope();
  const { ignoreHopeLimit } = settings;
  const canPull =
    ignoreHopeLimit || (currentHope !== null && currentHope >= PULL_COST);
  const pullLock = usePullLock();
  const isPullInProgress = useIsPullInProgress();
  const { inCamp } = useInPuzzlePage();

  const spinGacha = useCallback(() => {
    if (isSpectating) return;
    if (teamId === null) return;
    if (pullLock.isHeld) return;

    pullLock.acquireAndRun(async (getIsCanceled) => {
      const payload = await sockClient.sendScopeStepAndWaitAsync(
        {
          type: ScopeType.TEAM_GACHA,
          teamId,
        },
        {
          ignoreHopeLimit: ignoreHopeLimit ? true : undefined,
        }
      );
      if (payload === null) return;
      switch (payload.type) {
        case PullAckType.NOT_ENOUGH_HOPE: {
          toastr.error("You don't have enough hope! 😔");
          break;
        }
        case PullAckType.SUCCESS: {
          const { pullId, pull } = payload;
          setPendingPull({ pullId, pull });
          if (!inCamp) setRedirectCommand({ path: "/camp" });
          break;
        }
        case PullAckType.TOO_SOON: {
          // Ignore race conditions.
          break;
        }
      }
    });
  }, [
    pullLock,
    setPendingPull,
    isSpectating,
    teamId,
    sockClient,
    setRedirectCommand,
    ignoreHopeLimit,
    inCamp,
  ]);
  const isDisabled = isSpectating || isPullInProgress || !canPull;

  return (
    <>
      <button
        className="gacha-button"
        disabled={isDisabled}
        onClick={spinGacha}
      >
        Wish
      </button>
    </>
  );
}

export default GachaButton;
