import { ReactNode } from "react";

import { ScopeType } from "sockapi/scope-types";
import { AdminQueueTaskSummary } from "sockapi/scope-specs/admin-queue-spec";
import {
  PuzzleSubmissionType,
  AdminQueueTaskType,
} from "sockapi/scope-specs/admin-queue-task-spec";
import { useScopeStateResolvable } from "stores/ScopeStateStore";
import { useAdminPreferencesStore } from "stores/UserPreferencesStore";
import { Spinner } from "components/Loading";
import { RoutedLink } from "components/Link";

import ClaimedByDisplay from "components/AdminQueue/ClaimedByDisplay";
import { Puzzle105AdminQueueTaskSummaryDisplay } from "components/AdminQueue/admin-queue-puzzle-105";
import { Puzzle139AdminQueueTaskSummaryDisplay } from "components/AdminQueue/admin-queue-puzzle-139";
import { Puzzle144AdminQueueTaskSummaryDisplay } from "components/AdminQueue/admin-queue-puzzle-144";
import { HintAdminQueueTaskSummaryDisplay } from "components/AdminQueue/admin-queue-hint";

export function AdminQueueTaskSummaryDisplay(props: {
  taskId: string;
  taskSummary: AdminQueueTaskSummary;
}) {
  const { taskId, taskSummary } = props;
  const adminQueueTaskScopeState = useScopeStateResolvable(
    ScopeType.ADMIN_QUEUE_TASK,
    {
      taskId,
    }
  );
  const staffId = useAdminPreferencesStore((state) => state.staffId);

  if (adminQueueTaskScopeState === null) return <Spinner inline={true} />;
  const { task, claim } = adminQueueTaskScopeState;
  const isClaimedBySelf = claim !== undefined && claim.staffId === staffId;

  return (
    <div>
      <div className="admin-queue-task-claim-control">
        <ClaimedByDisplay
          taskId={taskId}
          taskSummary={taskSummary}
          useClaimLink={true}
        />
        <div>
          <RoutedLink path={`/admin-queue/task/${taskId}`}>
            {isClaimedBySelf ? "View" : "View without claiming"}
          </RoutedLink>
        </div>
      </div>
      <div className="admin-queue-task-summary-content">
        {((): NonNullable<ReactNode> => {
          switch (task.type) {
            case AdminQueueTaskType.HINT:
              return <HintAdminQueueTaskSummaryDisplay hintId={task.hintId} />;
            case AdminQueueTaskType.PUZZLE_SUBMISSION:
              switch (task.submissionType) {
                case PuzzleSubmissionType.PUZZLE_105:
                  return (
                    <Puzzle105AdminQueueTaskSummaryDisplay
                      teamId={task.teamId}
                    />
                  );
                case PuzzleSubmissionType.PUZZLE_139:
                  return (
                    <Puzzle139AdminQueueTaskSummaryDisplay
                      teamId={task.teamId}
                    />
                  );
                case PuzzleSubmissionType.PUZZLE_144:
                  return (
                    <Puzzle144AdminQueueTaskSummaryDisplay
                      teamId={task.teamId}
                    />
                  );
              }
          }
        })()}
      </div>
    </div>
  );
}
