import Twemoji from "react-twemoji";
import { addFlushSockAPIMessagesEffect } from "client-util";
import Certificate from "components/Certificate";
import { LargeSpinner } from "components/Loading";
import Globals from "Globals";
import { useEffect, useRef } from "react";
import { useParams } from "react-router-dom";
import { ScopeType } from "sockapi/scope-types";
import { useNavStore, useRedirectIfNonAdmin } from "stores/NavStore";
import {
  useGlobalScopeState,
  useScopeStateResolvable,
  useTeamMembersScopeState,
  useTeamScopeState,
} from "stores/ScopeStateStore";
import { useSockClient } from "stores/ServerInteractionStore";
import settings from "settings";

import "./CertificatePage.css";

function CertificatePage() {
  useRedirectIfNonAdmin();

  const teams = useGlobalScopeState(ScopeType.TEAM_LIST) ?? {};
  const { teamId } = useParams();
  if (teamId === undefined) throw new Error("expect teamId to be defined");
  const team = teams[teamId] ?? null;

  const teamMembersScopeState = useTeamMembersScopeState(teamId);
  const areTeamsLoaded = Object.keys(teams).length > 0;
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);
  const sockClient = useSockClient();

  useEffect(() => {
    if (!areTeamsLoaded) return;
    if (team !== null) return;

    return addFlushSockAPIMessagesEffect(sockClient, () => {
      Globals.toastr.error(`Team “${teamId}” not found.`);
      setRedirectCommand({ path: "/teams" });
    });
  }, [areTeamsLoaded, team, teamId, setRedirectCommand, sockClient]);

  // const teamMembersScopeState = useTeamMembersScopeState(teamId);
  const teamScopeState = useTeamScopeState(teamId);

  // collectibles
  const teamCollectiblesScopeState = useScopeStateResolvable(
    ScopeType.TEAM_COLLECTIBLES,
    teamId === null ? null : { teamId }
  );

  useEffect(() => {
    // this is kinda bad but enh, App should reset the title when it needs to?
    if (teamScopeState === null) return;
    document.title = teamScopeState.displayName;
    return () => {
      document.title = settings.documentTitle;
    };
  }, [teamScopeState]);

  const SVG_WIDTH = 400;
  const teamnameSize = useRef(0.66); // default size: 0.7rem
  const membersSize = useRef(0.4); // default size: 0.4rem
  const teamnameOffset = useRef(25); // default offset: 25% (center anchor)
  const membersOffset = useRef(6); // default offset: 6% (left-align anchor)
  const teamnameRadius = useRef(35); // default radius: 35
  const membersRadius = useRef(45); // default radius: 45
  const collectiblesSize = useRef(0.5); // default size: 0.5rem
  const showTwemoji = useRef(false);

  const splitEmoji = (text: string) =>
    text.match(/.(?:\u200d.|[\ufe00-\ufe0f])*/gu) ?? [];
  const emojifyPath = (text: string) =>
    splitEmoji(text).map((char, i) => <tspan key={i}>{char}</tspan>);
  const emojifyDiv = (text: string) =>
    splitEmoji(text).map((char, i) => <Twemoji key={i}>{char}</Twemoji>);
  const twemojiCheckboxRef = useRef<HTMLInputElement | null>(null);
  const teamNameRef = useRef<SVGTextPathElement | null>(null);
  const teamNameEmojiRef = useRef<HTMLDivElement | null>(null);
  const teamMembersRef = useRef<SVGTextPathElement | null>(null);
  const teamMembersEmojiRef = useRef<HTMLDivElement | null>(null);
  const teamCollectiblesRef = useRef<SVGTextPathElement | null>(null);
  const teamCollectiblesEmojiRef = useRef<HTMLDivElement | null>(null);
  const updateTwemoji = (
    pathRef: SVGTextPathElement | null,
    divRef: HTMLDivElement | null,
    size: number
  ) => {
    if (pathRef === null || divRef === null) return;
    const chars = [...pathRef.children] as SVGTSpanElement[];
    const emoji = [...divRef.children] as HTMLDivElement[];
    for (let i = 0; i < chars.length && i < emoji.length; ++i) {
      const img = emoji[i].querySelector("img");
      const show = img !== null && showTwemoji.current;
      emoji[i].style.display = show ? "" : "none";
      chars[i].style.opacity = show ? "0" : "1";
      if (!img) continue;
      const { x, y, width, height } = chars[i].getExtentOfChar(0);
      const theta = chars[i].getRotationOfChar(0);
      if (x === 0 && y === 0) {
        emoji[i].style.display = "none";
        continue;
      }
      emoji[i].style.fontSize = `${(920 * size) / SVG_WIDTH}vh`;
      emoji[i].style.position = "absolute";
      emoji[i].style.left = "50%";
      emoji[i].style.top = "50%";
      emoji[i].style.translate = `
        calc(-50% + ${92 * ((x + width / 2) / SVG_WIDTH - 0.5)}vh)
        calc(-50% + ${92 * ((y + height / 2) / SVG_WIDTH - 0.5)}vh)
      `;
      emoji[i].style.rotate = `${theta}deg`;
    }
  };
  const updateTwemojiTeamname = () =>
    updateTwemoji(
      teamNameRef.current,
      teamNameEmojiRef.current,
      teamnameSize.current
    );
  const updateTwemojiMembers = () =>
    updateTwemoji(
      teamMembersRef.current,
      teamMembersEmojiRef.current,
      membersSize.current
    );
  const updateTwemojiCollectibles = () =>
    updateTwemoji(
      teamCollectiblesRef.current,
      teamCollectiblesEmojiRef.current,
      collectiblesSize.current
    );
  const updateTwemojiAll = () => {
    updateTwemojiTeamname();
    updateTwemojiMembers();
    updateTwemojiCollectibles();
  };
  useEffect(() => {
    if (twemojiCheckboxRef.current === null) return;
    twemojiCheckboxRef.current.checked = true;
    showTwemoji.current = true;
    updateTwemojiAll();
  });

  if (
    !areTeamsLoaded ||
    teamId === null ||
    teamMembersScopeState === null ||
    teamScopeState === null ||
    teamCollectiblesScopeState === null
  )
    return <LargeSpinner />;

  const collectibles = Object.values(teamCollectiblesScopeState.collectibles)
    .filter((collectible) => collectible.isHiddenFromTeamName === undefined)
    .map((collectible) => collectible.icon)
    .join("");

  // launch print dialog
  const print = () => window.print();

  const shrinkTeamname = (factor: number) => {
    teamnameSize.current *= factor;
    const teamnameElement = document.getElementById("certificate-subtitle");
    if (teamnameElement)
      teamnameElement.style.fontSize = `${teamnameSize.current}rem`;
    updateTwemojiTeamname();
  };

  const shrinkMembers = (factor: number) => {
    membersSize.current *= factor;
    const membersElement = document.getElementById("certificate-subsubtitle");
    if (membersElement)
      membersElement.style.fontSize = `${membersSize.current}rem`;
    updateTwemojiMembers();
  };

  const rotateTeamname = (shift: number) => {
    teamnameOffset.current += shift;
    const teamnameTextPathElement = document.getElementById(
      "certificate-subtitle"
    )?.firstElementChild;
    if (teamnameTextPathElement)
      teamnameTextPathElement.setAttribute(
        "startOffset",
        `${teamnameOffset.current}%`
      );
    updateTwemojiTeamname();
  };

  const rotateMembers = (shift: number) => {
    membersOffset.current += shift;
    const membersTextPathElement = document.getElementById(
      "certificate-subsubtitle"
    )?.firstElementChild;
    if (membersTextPathElement)
      membersTextPathElement.setAttribute(
        "startOffset",
        `${membersOffset.current}%`
      );
    updateTwemojiMembers();
  };

  const outwardsTeamname = (shift: number) => {
    teamnameRadius.current += shift;
    const teamnamePathElement = document.getElementById("subtitlePath");
    if (teamnamePathElement)
      teamnamePathElement.setAttribute("d", circlePath(teamnameRadius.current));
    updateTwemojiTeamname();
  };

  const outwardsMembers = (shift: number) => {
    membersRadius.current += shift;
    const membersPathElement = document.getElementById("subsubtitlePath");
    if (membersPathElement)
      membersPathElement.setAttribute("d", circlePath(membersRadius.current));
    updateTwemojiMembers();
  };

  const circlePath = (radius: number, flip = false): string => {
    if (flip) {
      return `M ${SVG_WIDTH / 2},${
        SVG_WIDTH / 2
      } m ${radius},0 a ${radius},${radius} 0 1,0 -${
        radius * 2
      },0 a ${radius},${radius} 0 1,0 ${radius * 2},0`;
    }
    return `M ${SVG_WIDTH / 2},${
      SVG_WIDTH / 2
    } m -${radius},0 a ${radius},${radius} 0 1,1 ${
      radius * 2
    },0 a ${radius},${radius} 0 1,1 -${radius * 2},0`;
  };

  return (
    <div className="certificate-page-root">
      <svg
        className="certificate-svg"
        viewBox={`0 0 ${SVG_WIDTH} ${SVG_WIDTH}`}
      >
        <defs>
          <radialGradient id="skyGradient">
            <stop offset="10%" stopColor="#2a4470" stopOpacity="0.6" />
            <stop offset="75%" stopColor="#2a4470" stopOpacity="0.7" />
            <stop offset="85%" stopColor="#34378b" stopOpacity="0.5" />
            <stop offset="100%" stopColor="#62348b" stopOpacity="0.2" />
            {/* <stop offset="10%" stopColor="#34378b" stopOpacity="0.9" />
            <stop offset="75%" stopColor="#34378b" stopOpacity="0.6" />
            <stop offset="100%" stopColor="#7b348b" stopOpacity="0.1" /> */}
          </radialGradient>
          <filter id="wavyFilter">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.01"
              numOctaves="3"
              result="noise"
            />
            <feDisplacementMap in="SourceGraphic" in2="noise" scale="100" />
          </filter>
          <radialGradient
            id="backgroundGradient1"
            cx="100%"
            cy="0%"
            r="100%"
            fx="100%"
            fy="0%"
          >
            <stop
              offset="0%"
              style={{ stopColor: "#09438d80", stopOpacity: 1 }}
            />
            <stop
              offset="100%"
              style={{ stopColor: "#09438d00", stopOpacity: 0 }}
            />
          </radialGradient>
          <linearGradient
            id="backgroundGradient2"
            x1="0%"
            y1="100%"
            x2="100%"
            y2="0%"
          >
            <stop
              offset="0%"
              style={{ stopColor: "#30160080", stopOpacity: 1 }}
            />
            <stop
              offset="100%"
              style={{ stopColor: "#30160000", stopOpacity: 0 }}
            />
          </linearGradient>
          <mask id="circleMask">
            <rect width="100%" height="100%" fill="black" />
            <circle
              cx={SVG_WIDTH / 2}
              cy={SVG_WIDTH / 2}
              r="192"
              fill="white"
            />
          </mask>
        </defs>
        <g id="certificate-background">
          <rect
            width="100%"
            height="100%"
            fill="#111318"
            mask="url(#circleMask)"
          />
          <rect
            width="100%"
            height="100%"
            fill="url(#backgroundGradient1)"
            mask="url(#circleMask)"
          />
          <rect
            width="100%"
            height="100%"
            fill="url(#backgroundGradient2)"
            mask="url(#circleMask)"
          />
        </g>
        <circle
          cx={SVG_WIDTH / 2}
          cy={SVG_WIDTH / 2}
          r="192"
          fill="url(#skyGradient)"
          stroke="#030d0e"
          strokeWidth="15px"
        />
        {/* circle crosshair for testing */}
        {/* <circle cx={SVG_WIDTH / 2} cy={SVG_WIDTH / 2} r="5" fill="red" /> */}
      </svg>
      <Certificate teamId={teamId} />

      <svg
        className="certificate-svg"
        viewBox={`0 0 ${SVG_WIDTH} ${SVG_WIDTH}`}
      >
        <defs>
          <path id="titlePath" d={circlePath(45, true)} />
          <path id="subtitlePath" d={circlePath(teamnameRadius.current)} />
          <path id="subsubtitlePath" d={circlePath(membersRadius.current)} />
          <path id="collectiblesPath" d={circlePath(SVG_WIDTH / 2 - 5, true)} />
        </defs>
        <text id="certificate-title" fill="#e1e2e9">
          <textPath href="#titlePath" textAnchor="middle" startOffset="75%">
            galactic puzzle hunt 2024
          </textPath>
        </text>
        <text
          id="certificate-subtitle"
          fill="#e1e2e9"
          style={{ fontSize: `${teamnameSize.current}rem` }}
        >
          <textPath
            href="#subtitlePath"
            textAnchor="middle"
            startOffset={teamnameOffset.current + "%"}
            ref={teamNameRef}
          >
            {emojifyPath(teamScopeState.displayName)}
          </textPath>
        </text>
        <text
          id="certificate-subsubtitle"
          fill="#ffb77b"
          style={{ fontSize: `${membersSize.current}rem` }}
        >
          <textPath
            href="#subsubtitlePath"
            startOffset={membersOffset.current + "%"}
            ref={teamMembersRef}
          >
            {emojifyPath(teamMembersScopeState.members.join(", "))}
          </textPath>
        </text>
        <text id="certificate-collectibles" fill="#163b2a" wordSpacing="4rem">
          <textPath
            href="#collectiblesPath"
            textAnchor="middle"
            startOffset="75%"
            ref={teamCollectiblesRef}
          >
            {emojifyPath(collectibles).flatMap((c, i) => (i ? [" ", c] : [c]))}
          </textPath>
        </text>
      </svg>
      <div ref={teamNameEmojiRef}>{emojifyDiv(teamScopeState.displayName)}</div>
      <div ref={teamMembersEmojiRef}>
        {emojifyDiv(teamMembersScopeState.members.join(", "))}
      </div>
      <div id="certificate-collectibles-emoji" ref={teamCollectiblesEmojiRef}>
        {emojifyDiv(collectibles)}
      </div>
      <div className="certificate-tools">
        <div>
          IMPORTANT IMPORTANT: Use Chromium zoom 125% to preview, print Save as
          PDF, landscape letter, scale 83. <br />
          Map rotation is set randomly per team, adjust by dragging/arrow keys.{" "}
          <br />
          Refresh page to reset adjustments.
        </div>
        <div>
          <button className="certificate-btn" onClick={print}>
            Print to PDF
          </button>
        </div>
        <div>
          <label>
            experimental twemoji{" "}
            <input
              ref={twemojiCheckboxRef}
              type="checkbox"
              onChange={(evt) => {
                showTwemoji.current = (evt.target as HTMLInputElement).checked;
                updateTwemojiAll();
              }}
            />
          </label>
        </div>
        <div>
          adjust teamname:
          <div style={{ marginLeft: "1rem" }}>
            size
            <button
              className="certificate-btn"
              onClick={() => shrinkTeamname(0.95)}
            >
              📉
            </button>
            <button
              className="certificate-btn"
              onClick={() => shrinkTeamname(1 / 0.95)}
            >
              📈
            </button>
          </div>
          <div style={{ marginLeft: "1rem" }}>
            rotation
            <button
              className="certificate-btn"
              onClick={() => rotateTeamname(1)}
            >
              🔁
            </button>
            <button
              className="certificate-btn"
              onClick={() => rotateTeamname(-1)}
            >
              🔄
            </button>
          </div>
          <div style={{ marginLeft: "1rem" }}>
            radius
            <button
              className="certificate-btn"
              onClick={() => outwardsTeamname(1)}
            >
              📤
            </button>
            <button
              className="certificate-btn"
              onClick={() => outwardsTeamname(-1)}
            >
              📥
            </button>
          </div>
        </div>
        <div>
          adjust members:
          <div style={{ marginLeft: "1rem" }}>
            size
            <button
              className="certificate-btn"
              onClick={() => shrinkMembers(0.95)}
            >
              📉
            </button>
            <button
              className="certificate-btn"
              onClick={() => shrinkMembers(1 / 0.95)}
            >
              📈
            </button>
          </div>
          <div style={{ marginLeft: "1rem" }}>
            rotation
            <button
              className="certificate-btn"
              onClick={() => rotateMembers(1)}
            >
              🔁
            </button>
            <button
              className="certificate-btn"
              onClick={() => rotateMembers(-1)}
            >
              🔄
            </button>
          </div>
          <div style={{ marginLeft: "1rem" }}>
            radius
            <button
              className="certificate-btn"
              onClick={() => outwardsMembers(1)}
            >
              📤
            </button>
            <button
              className="certificate-btn"
              onClick={() => outwardsMembers(-1)}
            >
              📥
            </button>
          </div>
        </div>
        <p
          id="pdf-container"
          style={{ width: "100%", height: "720px", display: "none" }}
        >
          <iframe
            id="pdf-iframe"
            style={{ width: "100%", height: "100%", border: "none" }}
          ></iframe>
        </p>
      </div>
    </div>
  );
}

export default CertificatePage;
