import Twemoji from "react-twemoji";
import { UNTITLED_PUZZLE_DISPLAY_NAME } from "sockapi/puzzle-data";
import { TeamPuzzleSockAPIScopeState } from "sockapi/scope-specs/team-spec";
import { PuzzleLink } from "components/Link";
import { IconType, Icon, PuzzleIcon } from "components/Icon";
import Tooltip from "components/Tooltip";
import { clsObj } from "client-util";
import { PuzzleContentPreview } from "components/PuzzleContent/PuzzleContentPreview";
import { useSeparatelyPersistedState } from "stores/UserPreferencesStore";
import { usePinnedPuzzles } from "stores/BrowserWidePersistentState";
import "./PuzzleCard.css";

export type PuzzleCardProps = {
  preview?: boolean;
  answer?: string;
  isSolved: boolean;
  puzData: TeamPuzzleSockAPIScopeState;
  displayName: string;
  hasCannedHints: boolean;
  hasOpenedCannedHints: boolean;
  hasUnopenedCannedHints: boolean;
  hasHints: boolean;
  isActive: boolean;
  isNew: boolean;
  isRejected: boolean;
};

function PuzzleCard({
  preview,
  answer,
  isSolved,
  puzData,
  displayName,
  hasUnopenedCannedHints,
  isActive,
  isNew,
  isRejected,
}: PuzzleCardProps) {
  const { puzName, slug, isStory } = puzData;
  const displayDisplayName = (() => {
    if (!displayName.includes(UNTITLED_PUZZLE_DISPLAY_NAME)) return displayName;
    const [before, after] = displayName.split(UNTITLED_PUZZLE_DISPLAY_NAME);
    return (
      <>
        {before}
        <span className="puzzle-card-untitled">
          {UNTITLED_PUZZLE_DISPLAY_NAME}
        </span>
        {after}
      </>
    );
  })();
  const lastSeenPuzSlug = useSeparatelyPersistedState(
    (state) => state.lastSeenNonNullPuzSlug
  );
  const pinnedPuzzles = usePinnedPuzzles();
  const isPinned = pinnedPuzzles.includes(puzName);

  return (
    <PuzzleLink
      puzName={puzName}
      className={clsObj({
        "puzzle-card": true,
        solved: isSolved,
        unsolved: !isSolved,
        active: isActive,
        last: slug === lastSeenPuzSlug,
      })}
    >
      <div className="puzzle-card-decoration" />
      <div
        className={`puzzle-card-title ${displayName === "" ? "centered" : ""} ${
          isSolved && !isStory ? "answered" : ""
        }`}
      >
        <span className="puzzle-card-icons">
          <PuzzleIcon puzData={puzData} />
          {isNew ? <Twemoji>🆕</Twemoji> : null}
          {isPinned ? <Twemoji>📌️</Twemoji> : null}
          {hasUnopenedCannedHints ? (
            <Tooltip text="Canned hint available">
              <Icon icon={IconType.CANNED_HINT} />
            </Tooltip>
          ) : null}
          {isRejected ? (
            <Tooltip text="Your submission was rejected.">
              <Twemoji>❌</Twemoji>
            </Tooltip>
          ) : null}
        </span>
        <h3 title={displayName}>{displayDisplayName}</h3>
        {isSolved && !isStory ? (
          <div className="puzzle-card-answer" title={answer}>
            <Twemoji>{answer ?? "✅"}</Twemoji>
          </div>
        ) : null}
      </div>
      <div className="puzzle-card-preview">
        {preview && (
          <PuzzleContentPreview
            puzName={puzName}
            style={{ border: "none", height: "3.5em" }}
          />
        )}
      </div>
    </PuzzleLink>
  );
}

export default PuzzleCard;
