import { ScopeType } from "sockapi/scope-types";
import { SockAPIScopeState } from "sockapi/scope-state";
import { HintResponseType } from "sockapi/scope-specs/hint-spec";
import { LongDate } from "components/dates";

import "./HintDisplay.css";

function HintDisplay(props: {
  hintId: string;
  hint: SockAPIScopeState<ScopeType.HINT>;
  isAdmin?: boolean;
}) {
  const { hint, isAdmin = false } = props;
  const {
    request: { content, isFollowup, timestamp },
    response,
  } = hint;
  return (
    <div className="hint-content">
      <div>
        <div className="hint-content-row">
          <div className="hint-text-label">Q:</div>
          <pre className="hint-text">{content}</pre>
        </div>
        {!(response !== null && response.type === HintResponseType.OBSOLETE) ? (
          <div className="hint-content-row">
            <div className="hint-text-label">A:</div>
            <pre className="hint-text">
              {response === null ? "(No response yet.)" : response.content}
            </pre>
          </div>
        ) : null}
      </div>
      <div className="hint-metadata">
        <div>
          Asked <LongDate timestamp={timestamp} />
          {response === null ? null : (
            <>
              ; answered <LongDate timestamp={response.timestamp} />
            </>
          )}
        </div>
        {isFollowup ?? false ? <div>This was a follow-up hint.</div> : null}
        {response !== null && response.type === HintResponseType.OBSOLETE ? (
          <div>
            {isAdmin
              ? "This hint was marked as obsolete."
              : "Looks like you solved this puzzle before we could send you a response! Your use of the hint was refunded."}
          </div>
        ) : null}
        {response !== null && response.type === HintResponseType.REFUNDED ? (
          <div>
            {isAdmin
              ? "This hint was refunded."
              : "Your use of the hint was refunded."}
          </div>
        ) : null}
      </div>
    </div>
  );
}

export default HintDisplay;
