import { useEffect, useRef, useState } from "react";
import Twemoji from "react-twemoji";

import { ScopeType } from "sockapi/scope-types";
import { Scope } from "sockapi/scopes";
import {
  Puzzle139SharePermission,
  Puzzle139StatusType,
  PUZZLE_139_CONFIG,
} from "sockapi/scope-specs/team-puzzle-139-spec";
import { useSockClient } from "stores/ServerInteractionStore";
import {
  useScopeStateResolvable,
  useScopeStateResolvablePosthuntable,
} from "stores/ScopeStateStore";
import { useNavStore } from "stores/NavStore";

import { Spinner } from "components/Loading";
import DownloadFailedDisplay from "components/DownloadFailedDisplay";
import TeamDisplayNameDisplay from "components/TeamDisplayNameDisplay";
import { ButtonTabs } from "components/ButtonTabs";
import { Puzzle139ResponseDisplay } from "components/PuzzleContent/Puzzle139";
import PuzzleContentDisplay from "components/PuzzleContent/PuzzleContentDisplay";
import { CollapsibleContent } from "components/AdminQueue/admin-queue-hint";

export function Puzzle139AdminQueueTaskSummaryDisplay(props: {
  teamId: string;
  omitTitle?: boolean;
}) {
  const { teamId: displayedTeamId, omitTitle = false } = props;
  const teamPuzzle139ScopeState = useScopeStateResolvablePosthuntable(
    ScopeType.TEAM_PUZZLE_139,
    { teamId: displayedTeamId },
    { forcePosthuntIfNotAdmin: true }
  );

  if (teamPuzzle139ScopeState === null) return <Spinner inline={true} />;
  if (!teamPuzzle139ScopeState.success)
    return <DownloadFailedDisplay {...teamPuzzle139ScopeState} />;
  const { diagramUrl, submissionText, sharePermission } =
    teamPuzzle139ScopeState.state;

  return (
    <div className="puzzle-139-task">
      {!omitTitle ? <h3>Hug a Tree Submission</h3> : null}
      <p>
        <b>Team:</b> <TeamDisplayNameDisplay teamId={displayedTeamId} />
      </p>
      <div className="puzzle-139-preview">
        {sharePermission === Puzzle139SharePermission.BOTH ? (
          <p>{diagramUrl === undefined ? null : <img src={diagramUrl} />}</p>
        ) : (
          <p>
            <Twemoji tag="span">❌</Twemoji> This team <b>does not</b> want to
            share their image.
          </p>
        )}
        <div className="puzzle-139-text">{submissionText}</div>
      </div>
    </div>
  );
}

export function Puzzle139AdminQueueTaskDisplay(props: {
  teamId: string;
  isClaimedBySelf: boolean;
}) {
  const { teamId: displayedTeamId, isClaimedBySelf } = props;
  const teamPuzzle139ScopeState = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_139,
    { teamId: displayedTeamId }
  );
  const [isAccepted, setIsAccepted] = useState<boolean | null>(null);
  const [reasonPreview, setReasonPreview] = useState<string>("");
  const reasonInputRef = useRef<HTMLTextAreaElement>(null);
  const sockClient = useSockClient();
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);
  const submitStatus = teamPuzzle139ScopeState?.status;

  useEffect(() => {
    if (submitStatus === undefined) return;
    switch (submitStatus.type) {
      case Puzzle139StatusType.ACCEPTED:
        setIsAccepted(true);
        break;
      case Puzzle139StatusType.REJECTED:
        setIsAccepted(false);
        break;
    }
  }, [submitStatus]);

  if (teamPuzzle139ScopeState === null) return <Spinner inline={true} />;
  if (submitStatus === undefined) return <div>No submission found.</div>;

  const { submitTime } = submitStatus;
  const { diagramUrl, submissionText, sharePermission } =
    teamPuzzle139ScopeState;

  return (
    <div className="admin-queue-task-puzzle-139">
      <h2>Hug a Tree Submission</h2>
      <div>
        Team: <TeamDisplayNameDisplay teamId={displayedTeamId} />
      </div>
      <CollapsibleContent headerContent="Puzzle Content">
        <div>
          <PuzzleContentDisplay puzName={PUZZLE_139_CONFIG.puzName} />
        </div>
      </CollapsibleContent>
      <div className="puzzle-139-preview">
        <h4>Fun fact</h4>
        <p>{submissionText}</p>
        <h4>Picture</h4>
        <p>{diagramUrl === undefined ? null : <img src={diagramUrl} />}</p>
        <p>
          {(() => {
            switch (sharePermission) {
              case Puzzle139SharePermission.BOTH:
                return (
                  <>
                    The team granted permission to share{" "}
                    <b>both the image and fun fact</b> during wrap-up.
                  </>
                );
              case Puzzle139SharePermission.FACT:
                return (
                  <>
                    The team granted permission to share{" "}
                    <b>only the fun fact</b> during wrap-up.
                  </>
                );
              case Puzzle139SharePermission.NONE:
                return (
                  <>
                    The team <b>did not</b> granted permission to share their
                    submission during wrap-up.
                  </>
                );
            }
          })()}
        </p>
      </div>
      <hr />
      {!isClaimedBySelf ? (
        <div className="admin-queue-claim-this-task-notice">
          Claim this task to respond to it.
        </div>
      ) : null}
      <div>
        Set status:{" "}
        <div className="admin-queue-task-status-tabs">
          <ButtonTabs
            tabs={[
              { value: null, content: "Pending", disabled: true },
              { value: true, content: "Accepted" },
              { value: false, content: "Rejected" },
            ]}
            selected={isAccepted}
            setSelected={setIsAccepted}
            disabled={!isClaimedBySelf}
          />
        </div>
      </div>
      {isAccepted === null ? null : isAccepted ? (
        <>
          <div>Enter a personalized response for the team.</div>
          <div>
            <textarea
              disabled={!isClaimedBySelf}
              defaultValue={
                submitStatus.type === Puzzle139StatusType.ACCEPTED
                  ? submitStatus.comment
                  : ""
              }
              ref={reasonInputRef}
              onChange={(e) => setReasonPreview(e.target.value)}
            />
          </div>
        </>
      ) : (
        <>
          <div>Enter reason below (will be displayed inline):</div>
          <div>
            <textarea
              disabled={!isClaimedBySelf}
              defaultValue={
                submitStatus.type === Puzzle139StatusType.REJECTED
                  ? submitStatus.reason
                  : ""
              }
              ref={reasonInputRef}
              onChange={(e) => setReasonPreview(e.target.value)}
            />
          </div>
        </>
      )}
      {isAccepted !== null ? (
        <>
          <h3>Preview</h3>
          <Puzzle139ResponseDisplay
            status={{
              ...(isAccepted
                ? {
                    type: Puzzle139StatusType.ACCEPTED,
                    comment: reasonPreview,
                  }
                : {
                    type: Puzzle139StatusType.REJECTED,
                    reason: reasonPreview,
                  }),
              submitTime: 0,
              reviewTime: 0,
            }}
          />
        </>
      ) : null}
      {isAccepted !== null ? (
        <div>
          <button
            onClick={() => {
              (async () => {
                if (isAccepted === null) return;
                const scope: Scope<ScopeType.TEAM_PUZZLE_139> = {
                  type: ScopeType.TEAM_PUZZLE_139,
                  teamId: displayedTeamId,
                };
                if (isAccepted) {
                  if (reasonInputRef.current === null) return;
                  if (reasonInputRef.current.value === "") {
                    toastr.warning("Comment required.");
                    return;
                  }
                  await sockClient.sendScopeStepAndWaitAsync(scope, {
                    setStatus: {
                      type: Puzzle139StatusType.ACCEPTED,
                      comment: reasonInputRef.current.value,
                      submitTime,
                    },
                  });
                } else {
                  if (reasonInputRef.current === null) return;
                  if (reasonInputRef.current.value === "") {
                    toastr.warning("Reason required.");
                    return;
                  }
                  await sockClient.sendScopeStepAndWaitAsync(scope, {
                    setStatus: {
                      type: Puzzle139StatusType.REJECTED,
                      reason: reasonInputRef.current.value,
                      submitTime,
                    },
                  });
                }
                toastr.success("Response submitted.");
                setRedirectCommand({ path: "/admin-queue" });
              })().catch(console.error);
            }}
          >
            Submit
          </button>
        </div>
      ) : null}
    </div>
  );
}
