import { ReactNode, useEffect, useState } from "react";
import {
  createBrowserRouter,
  Outlet,
  RouterProvider,
  ScrollRestoration,
  useMatch,
  useParams,
} from "react-router-dom";

import "./App.css";

import { Error } from "components/Error";
import TeamListPage from "pages/TeamListPage";
import TeamPage from "pages/TeamPage";
import Modal from "components/Modal";
import ErrataPage from "pages/ErrataPage";
import AdminPage, { AdminRedirectPage } from "pages/AdminPage";
import AdminQueuePage, {
  AdminQueueTaskPage,
  AdminQueueTaskClaimPage,
} from "pages/AdminQueuePage";
import BigBoardPage from "pages/BigBoardPage";
import ServerHealthPage from "pages/ServerHealthPage";
import CampBase from "pages/CampBase";
import CampPage from "pages/CampPage";
import { useAudioEffect } from "useAudioEffect";
import PuzzlePage, { LastPuzzlePage, NoPuzzlePage } from "pages/PuzzlePage";
import HintsDisplay from "components/PuzzlePage/HintsDisplay";
import PuzzleBodyDisplay from "components/PuzzlePage/PuzzleBodyDisplay";
import SolutionBodyDisplay from "components/PuzzlePage/SolutionBodyDisplay";
import { HuntStatsPage, StatsDisplay } from "pages/StatsPage";
import UnlockPage from "pages/UnlockPage";
import SunrisePage from "pages/SunrisePage";
import WrapupEditPage from "pages/WrapupEditPage";

import settings from "settings";
import { ServerInterfaceType } from "sock-server/server-interface/ServerInterface";
import { SockAPIErrorCode, SockAPIError } from "sockapi/errors";
import { usePuzzleDisplayName } from "stores/ScopeStateStore";
import { useNavStore, usePuzName } from "stores/NavStore";
import { useServerInteractionStore } from "stores/ServerInteractionStore";
import { updateSeparatelyPersistedStateNonReactive } from "stores/UserPreferencesStore";
import { useUserLogStore } from "stores/UserLogStore";
import { useRedirectListener } from "client-util";
import CertificatePage from "pages/CertificatePage";
import WrapupPage, {
  WrapupGachaPage,
  WrapupSubmissionsPage,
  WrapupAmaPage,
  WrapupFluidityPage,
} from "pages/WrapupPage";
import WrapupStatsPage from "pages/WrapupStatsPage";

function PageBase() {
  const [stuckError, setStuckError] = useState<SockAPIError | null>(null);
  const [isDisconnectedModalClosed, setIsDisconnectedModalClosed] =
    useState(false);
  const addToUserLog = useUserLogStore((state) => state.addToUserLog);

  const getSockClient = useServerInteractionStore(
    (state) => state.getSockClient
  );

  const sockClient = getSockClient();
  const isRootPage = useMatch("/");
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);

  useEffect(() => {
    if (sockClient === null) return;

    const cleanupOnError = sockClient.onErrorEvent.addListener((err) => {
      addToUserLog(`Received error "${err.errCode}".`);
    });
    const cleanupAuthEffect = sockClient.addAuthEffect(() => {
      addToUserLog("Connected to server.");
    });
    const cleanupAfterDisconnect = sockClient.serverConnections[
      ServerInterfaceType.MAIN
    ].afterDisconnectEvent.addListener(
      ({ numReconnections, reconnectDelayInSeconds }) => {
        if (numReconnections === 0) {
          addToUserLog("Disconnected from server. Reconnecting...");
        } else if (reconnectDelayInSeconds < 0) {
          setStuckError({ errCode: SockAPIErrorCode.CONNECTION_ERROR });
          addToUserLog("Reconnection failed; giving up.");
        } else {
          addToUserLog(
            `Failed to reconnect. Reconnecting in ${reconnectDelayInSeconds} seconds...`
          );
        }
      }
    );

    return () => {
      cleanupOnError();
      cleanupAuthEffect();
      cleanupAfterDisconnect();
    };
  }, [sockClient, addToUserLog]);

  useEffect(() => {
    if (sockClient === null) return;

    return sockClient.addStuckEffect((err) => {
      setStuckError(err);
    });
  }, [sockClient, setStuckError]);

  useEffect(() => {
    if (isRootPage) setRedirectCommand({ path: "/camp", replace: true });
  }, [isRootPage, setRedirectCommand]);

  return (
    <NavWrapper>
      <Modal
        isOpen={!isDisconnectedModalClosed && stuckError !== null}
        title="Disconnected"
        className="disconnected-modal"
      >
        <div>
          {(() => {
            if (stuckError === null) return null;
            switch (stuckError.errCode) {
              case SockAPIErrorCode.CONNECTION_ERROR:
              case SockAPIErrorCode.AUTH_ERROR:
                return <>Unable to connect to the server.</>;
              case SockAPIErrorCode.TEAM_TEMP_BLOCKED:
                return <>The site is down for maintenance.</>;
              default:
                return <>Sorry, something went wrong.</>;
            }
          })()}
        </div>
        <div>
          You will not be able to receive notifications, submit answers, or load
          new content while disconnected. Please monitor your email for updates,
          and refresh the page at a later time to try reconnecting.
        </div>
        <div>
          <button onClick={() => setIsDisconnectedModalClosed(true)}>OK</button>
        </div>
      </Modal>
      <Outlet />
      <ScrollRestoration getKey={(location) => location.pathname} />
    </NavWrapper>
  );
}

function NavWrapper({ children }: { children: ReactNode }) {
  const setHasRouter = useNavStore((state) => state.setHasRouter);
  const puzName = usePuzName();
  const puzzleDisplayName = usePuzzleDisplayName(puzName);

  useEffect(() => {
    setHasRouter(true);
  }, [setHasRouter]);

  useRedirectListener();

  const { teamName } = useParams();
  useEffect(() => {
    document.title = (() => {
      if (teamName) return decodeURIComponent(teamName);
      if (puzzleDisplayName !== null) return puzzleDisplayName;
      return settings.documentTitle;
    })();
  }, [teamName, puzzleDisplayName]);

  useAudioEffect();

  return <>{children}</>;
}

const router = createBrowserRouter([
  {
    path: "/",
    element: <PageBase />,
    errorElement: <Error />,
    children: [
      {
        element: <CampBase />,
        children: [
          {
            path: "camp",
            element: <CampPage />,
          },
          {
            path: "lastpuzzle",
            element: <LastPuzzlePage />,
          },
          {
            path: "puzzles",
            loader: () => {
              updateSeparatelyPersistedStateNonReactive({
                lastSeenPuzSlug: null,
              });
              return null;
            },
            element: <NoPuzzlePage />,
          },
          {
            path: "puzzle/find_the_answer",
            element: <PuzzlePage puz212={true} />,
          },
          {
            element: <PuzzlePage />,
            children: [
              {
                path: "puzzle/:slug",
                element: <PuzzleBodyDisplay />,
              },
              {
                path: "solution/:slug",
                element: <SolutionBodyDisplay />,
              },
              {
                path: "hints/:slug",
                element: <HintsDisplay />,
              },
              {
                path: "stats/:slug",
                element: <StatsDisplay />,
              },
            ],
          },
          {
            path: "errata",
            element: <ErrataPage />,
          },
          {
            path: "unlock",
            element: <UnlockPage />,
          },
          {
            path: "teams",
            element: <TeamListPage />,
          },
          {
            path: "team/:teamName",
            element: <TeamPage />,
          },
          {
            path: "stats",
            element: <HuntStatsPage />,
          },
        ],
      },
      {
        // This should never be accessible from the production site,
        // but it's shorter to type so just redirect it to the
        // exposed endpoint.
        path: "admin",
        element: <AdminRedirectPage />,
      },
      {
        path: "sock-admin",
        element: <AdminPage />,
      },
      {
        path: "sock-admin/:teamId",
        element: <AdminPage />,
      },
      {
        path: "admin-queue",
        element: <AdminQueuePage />,
      },
      {
        path: "admin-queue/task/:taskId",
        element: <AdminQueueTaskPage />,
      },
      {
        path: "admin-queue/task/:taskId/claim",
        element: <AdminQueueTaskClaimPage />,
      },
      {
        path: "bigboard",
        element: <BigBoardPage />,
      },
      {
        path: "health",
        element: <ServerHealthPage />,
      },
      {
        path: "sunrise",
        element: <SunrisePage />,
      },
      {
        path: "wrapup",
        element: <WrapupPage />,
      },
      {
        path: "wrapup/edit",
        element: <WrapupEditPage />,
      },
      {
        path: "wrapup/gacha",
        element: <WrapupGachaPage />,
      },
      {
        path: "wrapup/stats",
        element: <WrapupStatsPage />,
      },
      {
        path: "wrapup/submissions",
        element: <WrapupSubmissionsPage />,
      },
      {
        path: "wrapup/ama",
        element: <WrapupAmaPage />,
      },
      {
        path: "wrapup/fluidity",
        element: <WrapupFluidityPage />,
      },
      {
        path: "cert/:teamId",
        element: <CertificatePage />,
      },
    ],
  },
]);

function App() {
  useEffect(() => {
    document.documentElement.classList.add("game-base");
    return () => document.documentElement.classList.remove("game-base");
  }, []);

  return <RouterProvider router={router} />;
}

export default App;
