export function AdminHopeControl(props: { teamId?: string }) {
  const { teamId: overrideTeamId } = props;
  const ownTeamId = useTeamId();
  const teamId = overrideTeamId ?? ownTeamId;
  const currentHope = useCurrentHope(teamId);
  const [hopeValue, setHopeValue] = useState("");
  useEffect(() => setHopeValue(""), [teamId]);
  const sockClient = useSockClient();

  if (currentHope === null || teamId === null) return <Spinner inline />;

  return (
    <div className="admin-header">
      <label>
        {formatHope(currentHope)} current hope &rarr;{" "}
        <input
          key={teamId}
          type="number"
          style={{ width: "6em" }}
          onInput={(e) => setHopeValue((e.target as HTMLInputElement).value)}
        />
      </label>
      <button
        onClick={() => {
          const val = parseInt(hopeValue);
          if (isNaN(val)) return;
          sockClient.sendAdminScopeStep({
            teams: {
              [teamId]: {
                overrideHope: val,
              },
            },
          });
        }}
        disabled={!/^\d+$/.test(hopeValue)}
      >
        Override
      </button>
    </div>
  );
}

/** Used for both the admin and unlocks pages. */
export function AdminTopControl(props: { teamId?: string }) {
  const { teamId: overrideTeamId } = props;
  const ownTeamId = useTeamId();
  const teamId = overrideTeamId ?? ownTeamId;
  const sockClient = useSockClient();
  const huntAdminScopeState = useGlobalScopeState(ScopeType.HUNT_ADMIN);
  const teamAdminData = huntAdminScopeState?.teamAdminData ?? null;
  const teamAdminDataForTeam =
    teamId === null ? null : teamAdminData?.[teamId] ?? null;
  const numTotalHintTokens = useNumTotalHintTokens(teamId);
  const numUsedHintTokens = useNumUsedHintTokens(teamId);
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const displayName = teamAdminDataForTeam?.displayName ?? "";
  const [displayNameInput, setDisplayNameInput] = useState("");

  useEffect(() => {
    if (displayName === null) return;
    // Keep the display name input in sync if the display name
    // changes due to external sources.
    setDisplayNameInput(displayName);
  }, [displayName, setDisplayNameInput]);

  if (
    teamId === null ||
    numTotalHintTokens === null ||
    numUsedHintTokens === null ||
    teamAdminDataForTeam === null ||
    // Don't show as ready until we have synced the display name
    // into the input box.
    displayName === null
  )
    return <LargeSpinner />;

  const { userId } = teamAdminDataForTeam;

  const setDisplayNameFromInput = () => {
    if (displayNameInput === displayName) return;
    sockClient.sendAdminScopeStep({
      teams: {
        [teamId]: {
          displayName: displayNameInput,
        },
      },
    });
  };

  return (
    <div className="admin-top">
      <div className="admin-header">
        <label>
          Team name:{" "}
          <input
            type="text"
            style={{ width: "12em" }}
            value={displayNameInput}
            onChange={(e) => {
              setDisplayNameInput(e.target.value);
            }}
            onBlur={() => {
              setDisplayNameFromInput();
            }}
            onKeyPress={(e) => {
              if (e.key === "Enter") {
                setDisplayNameFromInput();
              }
            }}
          />
        </label>
        {shouldDisplayAdmin ? (
          <>
            <DjangoLink href={`impersonate/${userId}`}>
              <Tooltip text="Impersonate">
                <Twemoji tag="span">🕵️</Twemoji>
              </Tooltip>
            </DjangoLink>
            <DjangoLink href={`admin/puzzles/team/${userId}`}>
              <Tooltip text="Django admin [you should not need to use this]">
                <Twemoji tag="span">🐍️</Twemoji>
              </Tooltip>
            </DjangoLink>
            <RoutedLink path={`/cert/${teamId}`}>
              <Tooltip text="Certificate">
                <Twemoji tag="span">🖼️</Twemoji>
              </Tooltip>
            </RoutedLink>
          </>
        ) : null}
      </div>
      <AdminHopeControl teamId={teamId} />
      <div className="admin-header">
        <label>
          <Tooltip text="Hint tokens">
            <Twemoji tag="span">💡 </Twemoji>
            <SyncedNumberInput
              min={0}
              syncedVal={numTotalHintTokens}
              onUpdate={(val) => {
                sockClient.sendAdminScopeStep({
                  teams: {
                    [teamId]: {
                      overrideNumTotalHintTokens: val,
                    },
                  },
                });
              }}
            />{" "}
            total, {numUsedHintTokens} used
          </Tooltip>
        </label>
      </div>
    </div>
  );
}

