export function AdminPuzzleControl(props: {
  teamId?: string;
  puzName: string;
}) {
  const { teamId: overrideTeamId, puzName } = props;
  const ownTeamId = useTeamId();
  const teamId = overrideTeamId ?? ownTeamId;
  const huntAdminScopeState = useGlobalScopeState(ScopeType.HUNT_ADMIN);
  const teamScopeState = useTeamScopeState(teamId);
  const teamCannedHintsScopeState = useScopeStateResolvable(
    ScopeType.TEAM_CANNED_HINTS,
    teamId === null ? null : { teamId }
  );
  const displayName = usePuzzleDisplayName(puzName, teamId);
  const sockClient = useSockClient();

  if (
    teamId === null ||
    huntAdminScopeState === null ||
    teamScopeState === null ||
    teamCannedHintsScopeState === null ||
    displayName === null
  )
    return <Spinner inline />;

  const adminPuzData = huntAdminScopeState.puzzles[puzName];
  const teamPuzData = teamScopeState.puzzles[puzName];
  const isUnlocked = teamPuzData !== undefined;
  const isSolved = teamPuzData?.solveTime !== undefined;
  const { numTotal: numTotalCannedHints } = teamCannedHintsScopeState
    .cannedHints[puzName] ?? { numTotal: 0 };
  const maxNumCannedHints = huntAdminScopeState.numCannedHints[puzName] ?? 0;
  const numExtraGuesses = teamScopeState.extraGuesses?.[puzName] ?? 0;

  return (
    <div className="admin-puz">
      <div className="button-squish-zone secondary">
        <Tooltip text={isUnlocked ? "Set locked" : "Set unlocked"}>
          <button
            onClick={() => {
              sockClient.sendAdminScopeStep({
                teams: {
                  [teamId]: {
                    overrideUnlocked: { [puzName]: !isUnlocked },
                  },
                },
              });
            }}
          >
            <Twemoji tag="span">{isUnlocked ? "🔑" : "🔒"}</Twemoji>
          </button>
        </Tooltip>
        <Tooltip text={isSolved ? "Set unsolved" : "Set solved"}>
          <button
            disabled={!isUnlocked}
            onClick={() => {
              sockClient.sendAdminScopeStep({
                teams: {
                  [teamId]: {
                    overrideSolved: { [puzName]: !isSolved },
                  },
                },
              });
            }}
          >
            <Twemoji tag="span">{isSolved ? "✅️" : "🔲️"}</Twemoji>
          </button>
        </Tooltip>
      </div>
      <label>
        <Tooltip text="Canned hints">
          <Twemoji tag="span">🥫 </Twemoji>
          <SyncedNumberInput
            syncedVal={numTotalCannedHints}
            onUpdate={(val) => {
              sockClient.sendAdminScopeStep({
                teams: {
                  [teamId]: {
                    overridePuzzleNumTotalCannedHints: { [puzName]: val },
                  },
                },
              });
            }}
            min={0}
            max={maxNumCannedHints}
            disabled={maxNumCannedHints <= 0}
          />
        </Tooltip>
      </label>
      {!settings.isPosthunt ? (
        <label>
          <Tooltip text="Extra guesses">
            <Twemoji tag="span">✍️ </Twemoji>
            <SyncedNumberInput
              syncedVal={numExtraGuesses}
              onUpdate={(val) => {
                sockClient.sendAdminScopeStep({
                  teams: {
                    [teamId]: {
                      overridePuzzleNumExtraGuesses: { [puzName]: val },
                    },
                  },
                });
              }}
              min={0}
              disabled={!(teamPuzData ?? adminPuzData).hasAnswer}
            />
          </Tooltip>
        </label>
      ) : null}
      {puzName === OLIVE_CONFIG.puzName ? <AdminOliveWishesControl /> : null}
      {puzName === BLOCKS_CONFIG.puzName ? <AdminBlocksWishesControl /> : null}
      <div>
        <PuzzleIcon puzData={teamPuzData ?? adminPuzData} />{" "}
        <PuzzleLink puzName={puzName}>{displayName}</PuzzleLink>
      </div>
    </div>
  );
}

export const sortAdminPagePuzzles = (puzzles: {
  [puzName: string]: PuzzleData;
}) => {
  return Object.values(puzzles).sort(comparePuzzlesDefaultUnlockOrder);
};

function TeamAdminDisplay(props: { displayedTeamId: string }) {
  const { displayedTeamId } = props;
  const ownTeamId = useTeamId();
  const huntAdminScopeState = useGlobalScopeState(ScopeType.HUNT_ADMIN);
  const teamAdminData = huntAdminScopeState?.teamAdminData ?? null;
  const { puzzles = null, numCannedHints: maxNumCannedHints = {} } =
    huntAdminScopeState ?? {};
  const sockClient = useSockClient();
  const teamAdminDataForTeam =
    displayedTeamId === null ? null : teamAdminData?.[displayedTeamId] ?? null;
  const displayName = teamAdminDataForTeam?.displayName ?? "";

  if (
    displayedTeamId === null ||
    puzzles === null ||
    teamAdminDataForTeam === null ||
    displayName === null
  )
    return <LargeSpinner />;

  const { isHidden, isInactive, isTempBlocked } = teamAdminDataForTeam;
  const puzzlesDom = sortAdminPagePuzzles(puzzles).map(({ puzName }) => {
    return (
      <AdminPuzzleControl
        key={puzName}
        teamId={displayedTeamId}
        puzName={puzName}
      />
    );
  });
  const dangerousConfirm = (): boolean => {
    if (!confirm("Are you sure?")) return false;
    if (ownTeamId === displayedTeamId) return true;
    const userRes = "ok";
    const userReq = `You are updating a different team. This is dangerous. Confirm the team name is ${displayName} and type “${userRes}” to proceed.`;
    if (prompt(userReq) !== userRes) return false;
    return true;
  };
  const bulkUpdate = (
    field: "overrideSolved" | "overrideUnlocked",
    value: boolean
  ) => {
    if (!dangerousConfirm()) return;
    sockClient.sendAdminScopeStep({
      teams: {
        [displayedTeamId]: {
          [field]: Object.fromEntries(
            Object.keys(puzzles).map((key) => [key, value])
          ),
        },
      },
    });
  };
  const updateCannedHints = (get: boolean) => {
    if (!dangerousConfirm()) return;
    sockClient.sendAdminScopeStep({
      teams: {
        [displayedTeamId]: {
          overridePuzzleNumTotalCannedHints: get
            ? maxNumCannedHints
            : Object.fromEntries(
                Object.keys(maxNumCannedHints).map((key) => [key, 0])
              ),
        },
      },
    });
  };
  return (
    <>
      <div className="admin-header">
        Team ID:{" "}
        <RoutedLink path={makeTeamPagePath(displayName)}>
          {displayedTeamId}
        </RoutedLink>
        <label>
          <input
            type="checkbox"
            checked={isHidden}
            onChange={(e) => {
              sockClient.sendAdminScopeStep({
                teams: {
                  [displayedTeamId]: {
                    isHidden: !isHidden,
                  },
                },
              });
            }}
          />{" "}
          <span
            title="Hides the team from the leaderboard. Used for suspected cheaters. They can still progress through the hunt."
            style={{ textDecoration: "underline", cursor: "help" }}
          >
            Hidden
          </span>
        </label>
        <label>
          <input
            type="checkbox"
            checked={isInactive}
            onChange={(e) => {
              sockClient.sendAdminScopeStep({
                teams: {
                  [displayedTeamId]: {
                    isInactive: !isInactive,
                  },
                },
              });
            }}
          />{" "}
          <span
            title="Bans the team. They will be unable to access the hunt."
            style={{ textDecoration: "underline", cursor: "help" }}
          >
            Inactive
          </span>
        </label>
        <label>
          <input
            type="checkbox"
            checked={isTempBlocked}
            onChange={(e) => {
              sockClient.sendAdminScopeStep({
                teams: {
                  [displayedTeamId]: {
                    isTempBlocked: !isTempBlocked,
                  },
                },
              });
            }}
          />{" "}
          <span
            title="Temporarily blocks the team, in case we need to log in and change their state. Uncheck this afterwards."
            style={{ textDecoration: "underline", cursor: "help" }}
          >
            Blocked
          </span>
        </label>
      </div>
      <AdminTopControl teamId={displayedTeamId} />
      <div className="admin-puzzles">{puzzlesDom}</div>
      <div className="admin-header">
        <div className="button-squish-zone">
          <Tooltip text="Lock all">
            <button onClick={() => bulkUpdate("overrideUnlocked", false)}>
              <Twemoji tag="span">🔒</Twemoji>
            </button>
          </Tooltip>
          <Tooltip text="Unlock all">
            <button onClick={() => bulkUpdate("overrideUnlocked", true)}>
              <Twemoji tag="span">🔑</Twemoji>
            </button>
          </Tooltip>
        </div>
        <div className="button-squish-zone">
          <Tooltip text="Unsolve all">
            <button onClick={() => bulkUpdate("overrideSolved", false)}>
              <Twemoji tag="span">🔲️</Twemoji>
            </button>
          </Tooltip>
          <Tooltip text="Solve all">
            <button onClick={() => bulkUpdate("overrideSolved", true)}>
              <Twemoji tag="span">✅️</Twemoji>
            </button>
          </Tooltip>
        </div>
        <div className="button-squish-zone">
          <Tooltip text="Hide all canned hints">
            <button onClick={() => updateCannedHints(false)}>
              <Twemoji tag="span">🗑️</Twemoji>
            </button>
          </Tooltip>
          <Tooltip text="Get all canned hints">
            <button onClick={() => updateCannedHints(true)}>
              <Twemoji tag="span">🥫️</Twemoji>
            </button>
          </Tooltip>
        </div>
        <button
          onClick={() => {
            sockClient
              .sendAdminScopeStepAndWaitAsync({
                reloadPuzzles: true,
              })
              .then((respPayload) => {
                if (respPayload === null) return;
                toastr.success("PuzzlesDB reloaded!");
              })
              .catch((err) => {
                console.error(err);
                toastr.error("Failed to reload PuzzlesDB.");
              });
          }}
        >
          <Twemoji tag="span">♻️ Global PuzzlesDB Refresh</Twemoji>
        </button>
      </div>
    </>
  );
}

function AdminPage() {
  const { teamId: displayedTeamId = null } = useParams<{
    teamId?: string;
  }>();
  const ownTeamId = useTeamId();
  const huntAdminScopeState = useGlobalScopeState(ScopeType.HUNT_ADMIN);
  // Defaulting to your own team always seems more intuitive now.
  // const adminPageLastSeenTeamId = useSeparatelyPersistedState(
  //   (state) => state.adminPageLastSeenTeamId
  // );
  const adminPageLastSeenTeamId = undefined;
  const teamAdminData = huntAdminScopeState?.teamAdminData ?? null;
  const updateSeparatelyPersistedState = useUpdateSeparatelyPersistedState();
  const [searchText, setSearchText] = useState("");
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);
  const teamAdminDataForTeam =
    displayedTeamId === null ? null : teamAdminData?.[displayedTeamId] ?? null;

  useRedirectIfNonAdmin();

  // If the last seen team disappears (such as during dev), reset
  // to the current team.
  useEffect(() => {
    if (displayedTeamId === null) return;
    if (teamAdminData === null) return;
    if (teamAdminDataForTeam !== null) return;
    if (ownTeamId === null) return;
    setRedirectCommand({
      path: `/sock-admin/${ownTeamId}`,
      replace: true,
    });
  }, [
    displayedTeamId,
    teamAdminData,
    teamAdminDataForTeam,
    ownTeamId,
    setRedirectCommand,
  ]);

  // Automatically select the last seen team, otherwise the own team.
  useEffect(() => {
    if (displayedTeamId !== null) return;
    setRedirectCommand({
      path: `/sock-admin/${adminPageLastSeenTeamId ?? ownTeamId}`,
      replace: true,
    });
  }, [displayedTeamId, adminPageLastSeenTeamId, ownTeamId, setRedirectCommand]);

  useEffect(() => {
    if (displayedTeamId === null) return;
    if (teamAdminDataForTeam === null) return;
    updateSeparatelyPersistedState({
      adminPageLastSeenTeamId: displayedTeamId,
    });
  }, [displayedTeamId, teamAdminDataForTeam, updateSeparatelyPersistedState]);

  if (
    teamAdminData === null ||
    teamAdminDataForTeam === null ||
    displayedTeamId === null
  )
    return <LargeSpinner />;

  const teamsDom = Object.keys(teamAdminData)
    .filter((teamId) => {
      const teamData = teamAdminData[teamId];
      return teamData.displayName.toLowerCase().includes(searchText.trim());
    })
    .sort()
    .map((teamId) => {
      const teamData = teamAdminData[teamId];
      const isSelected = displayedTeamId === teamId;
      return (
        <button
          key={teamId}
          className={`admin-team-btn${isSelected ? " highlight" : ""}`}
          title={teamData.displayName}
          onClick={() => {
            setRedirectCommand({
              path: `/sock-admin/${teamId}`,
              replace: true,
            });
          }}
        >
          {teamData.displayName}
        </button>
      );
    });

  return (
    <div className="admin-root">
      <div className="admin-sidebar">
        <h1>
          <Twemoji tag="span">🧦️</Twemoji>Admin
        </h1>
        <input
          type="text"
          onChange={(e) => {
            setSearchText(e.target.value.toLowerCase().trim());
          }}
        />
        <div className="admin-teams">{teamsDom}</div>
      </div>
      <div className="admin-main">
        <TeamAdminDisplay displayedTeamId={displayedTeamId} />
      </div>
    </div>
  );
}

export function AdminRedirectPage() {
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);

  useEffect(() => {
    setRedirectCommand({ path: "/sock-admin", replace: true });
  }, [setRedirectCommand]);

  return <LargeSpinner />;
}

export default AdminPage;
