import { ScopeType } from "sockapi/scope-types";
import { HOPELESS_CONFIG } from "sockapi/scope-specs/team-hopeless-spec";
import { Spinner } from "components/Loading";
import { useTeamId, useSockClient } from "stores/ServerInteractionStore";
import { useIsPuzzleSolved, useCurrentHope } from "stores/ScopeStateStore";
import { useUILock } from "ui-locks";
import { Flavor } from "components/PuzzleContent/puzzle-components";

export function Hopeless() {
  const teamId = useTeamId();
  const sockClient = useSockClient();
  const hope = useCurrentHope();
  const isSolved = useIsPuzzleSolved(HOPELESS_CONFIG.puzName);
  const stepLock = useUILock();

  if (teamId === null || isSolved === null || hope === null)
    return <Spinner inline={true} />;

  return isSolved ? (
    <p>You are filled with hope!</p>
  ) : hope >= HOPELESS_CONFIG.hopeLimit ? (
    <Flavor>You have too much hope...</Flavor>
  ) : (
    <>
      <p>
        A voice rings out: <b>FEAR NOT, HOPE IS HERE!</b>
      </p>
      <p>
        <button
          onClick={() => {
            stepLock.acquireAndRun(async (getIsCanceled) => {
              await sockClient.sendScopeStepAndWaitAsync(
                {
                  type: ScopeType.TEAM_HOPELESS,
                  teamId,
                },
                {
                  solve: true,
                }
              );
            });
          }}
        >
          Get Hope
        </button>
      </p>
    </>
  );
}
