export function BigBoardPageSelection() {
  const numTeamsPerPage = useBigBoardPreferencesStore(
    (state) => state.numTeamsPerPage
  );
  const setNumTeamsPerPage = useBigBoardPreferencesStore(
    (state) => state.setNumTeamsPerPage
  );
  const pageNum = useBigBoardPreferencesStore((state) => state.pageNum);
  const setPageNum = useBigBoardPreferencesStore((state) => state.setPageNum);
  const [numTeamsPerPageInput, setNumTeamsPerPageInput] = useState(
    numTeamsPerPage.toString()
  );
  const [pageNumInput, setPageNumInput] = useState((pageNum + 1).toString());
  const teams = useGlobalScopeState(ScopeType.TEAM_LIST) ?? {};
  const numTeams = Object.keys(teams).length;
  return (
    <PageChanger
      numPerPage={numTeamsPerPage}
      setNumPerPage={setNumTeamsPerPage}
      pageNum={pageNum}
      setPageNum={setPageNum}
      numEntries={numTeams}
    />
  );
}

export function BigBoardHeader({ colData }: { colData: BigBoardColumnData }) {
  const { colKey, puzName, displayName, shortName } = colData;
  const linkChildren = ((): string => {
    if (shortName !== undefined) return shortName;
    if (displayName !== "") return makeShortName(displayName);
    if (puzName === undefined) return "???";
    if (puzName.includes("custom")) return `c_${puzName.split("_").at(-1)}`;
    return puzName;
  })();
  return (
    <th key={colKey}>
      <div className="puzzle-title-header-link">
        {puzName === undefined ? (
          linkChildren
        ) : (
          <Tooltip text={`[${puzName}] ${displayName}`} placement="bottom">
            <PuzzleLink puzName={puzName}>{linkChildren}</PuzzleLink>
          </Tooltip>
        )}
      </div>
    </th>
  );
}

export const useCreateBigBoardPageTeamIds = (showHidden: boolean) => {
  const bigBoardTeamFilter = useNavStore((state) => state.bigBoardTeamFilter);
  const sortedTeams = useSortedTeams(showHidden);
  const numTeamsPerPage = useBigBoardPreferencesStore(
    (state) => state.numTeamsPerPage
  );
  const pageNum = useBigBoardPreferencesStore((state) => state.pageNum);

  if (sortedTeams === null) return null;

  return (sortFunc?: (teamId1: string, teamId2: string) => number) => {
    const teamIds = sortedTeams
      .filter(({ displayName }) =>
        displayName.toLowerCase().includes(bigBoardTeamFilter)
      )
      .map(({ teamId }) => teamId);
    if (sortFunc !== undefined) teamIds.sort(sortFunc);
    return teamIds.slice(
      pageNum * numTeamsPerPage,
      (pageNum + 1) * numTeamsPerPage
    );
  };
};

type BigBoardPuzzleCellContext = {
  teamPuzState?: BigBoardTeamPuzzleState;
  huntEndTime: number;
  rank?: number;
};

function BigBoardPuzzleCellNoMemo({
  teamPuzState,
  huntEndTime,
  rank,
}: BigBoardPuzzleCellContext) {
  const {
    solveTime,
    numHintsUsed = 0,
    numWrongGuesses = 0,
    numMembers = 0,
  } = teamPuzState ?? {};
  const isSolved = solveTime !== undefined;
  const isUnlocked = teamPuzState !== undefined;
  const isPostsolved = solveTime !== undefined && solveTime > huntEndTime;
  // TODO: fill this in once we have a round structure
  const isBacksolved = false;
  const classes = [
    ...(isSolved
      ? ["big-board-solved"]
      : numWrongGuesses > 0
      ? ["big-board-wrong"]
      : isUnlocked
      ? ["big-board-unlocked"]
      : []),
    // Note that this differs from the usual bigboard in that we
    // also count hints that were asked but not answered.
    // I don't think it really makes a big difference since if we
    // don't want a hint to count we'll just refund it soon enough.
    ...(numHintsUsed > 0 ? ["big-board-hinted"] : []),
    ...(isPostsolved ? ["big-board-postsolved"] : []),
    ...(isBacksolved ? ["big-board-backsolved"] : []),
    ...(numMembers > 0 ? ["big-board-active"] : []),
  ];
  const className = classes.join(" ");
  return (
    <td
      className={className === "" ? undefined : className}
      title={
        solveTime === undefined
          ? undefined
          : `${isBacksolved ? "Backsolved" : "Solved"} at ${new Date(
              solveTime
            ).toLocaleString()}`
      }
    >
      {rank === undefined ? null : rank + 1}
      {numWrongGuesses === 0 ? null : <small>&minus;{numWrongGuesses}</small>}
      {numHintsUsed === 0 ? null : <small>+{numHintsUsed}</small>}
    </td>
  );
}
const BigBoardPuzzleCell = memo(BigBoardPuzzleCellNoMemo);

function BigBoardHopeCellNoMemo({
  hopeSnapshot,
}: {
  hopeSnapshot: HopeSnapshot | null;
}) {
  const hope = useCurrentHopeFromHopeSnapshot(hopeSnapshot);
  return (
    <td style={{ textAlign: "right" }}>
      {hope === null ? <Spinner inline /> : formatHope(hope)}
    </td>
  );
}
const BigBoardHopeCell = memo(BigBoardHopeCellNoMemo);

type SolveTimeRecord = {
  teamId: string;
  solveTime: number;
};

const computeBigBoardStats = (
  bigBoard: SockAPIScopeState<ScopeType.BIG_BOARD>,
  teams: SockAPIScopeState<ScopeType.TEAM_LIST>,
  puzzles: { [puzName: string]: PuzzleData }
) => {
  const globalRanks: { [teamId: string]: number } = {};
  const solveTimes: { [puzName: string]: SolveTimeRecord[] } = {};
  const solveTimeRanks: { [teamId: string]: { [puzName: string]: number } } =
    {};
  const puzStats: {
    [puzName: string]: {
      numUnlocks: number;
      numSolves: number;
      numWrongGuesses: number;
      numHintsUsed: number;
    };
  } = {};
  const teamStats: {
    [teamId: string]: {
      lastSolveTime?: number;
      numSolves: number;
      numWrongGuesses: number;
      numHintsUsed: number;
    };
  } = Object.fromEntries(
    Object.keys(bigBoard.teams).map((teamId) => [
      teamId,
      {
        numSolves: 0,
        numWrongGuesses: 0,
        numHintsUsed: 0,
      },
    ])
  );

  for (const [teamId, teamState] of Object.entries(bigBoard.teams)) {
    const { isHidden = false } = teams[teamId];
    const currTeamStats = teamStats[teamId];
    for (const [puzName, puzState] of Object.entries(teamState.unlocks)) {
      const { solveTime, numWrongGuesses = 0, numHintsUsed = 0 } = puzState;
      puzStats[puzName] ??= {
        numUnlocks: 0,
        numSolves: 0,
        numWrongGuesses: 0,
        numHintsUsed: 0,
      };
      const currPuzStats = puzStats[puzName];
      if (solveTime !== undefined) {
        if (!isHidden) {
          currPuzStats.numSolves ??= 0;
          currPuzStats.numSolves++;
          solveTimes[puzName] ??= [];
          solveTimes[puzName].push({ teamId, solveTime });
        }
        if (isUsedForSolveCount(puzzles[puzName])) {
          currTeamStats.lastSolveTime = Math.max(
            currTeamStats.lastSolveTime ?? 0,
            solveTime
          );
          currTeamStats.numSolves++;
        }
      }
      currTeamStats.numWrongGuesses += numWrongGuesses;
      currTeamStats.numHintsUsed += numHintsUsed;
      if (!isHidden) {
        currPuzStats.numUnlocks++;
        currPuzStats.numWrongGuesses += numWrongGuesses;
        currPuzStats.numHintsUsed += numHintsUsed;
      }
    }
  }
  for (const { teamId } of Object.values(teams)) {
    globalRanks[teamId] = Object.keys(globalRanks).length;
  }

  for (const [puzName, puzSolveTimes] of Object.entries(solveTimes)) {
    puzSolveTimes.sort(
      (record1, record2) => record1.solveTime - record2.solveTime
    );
    for (const [i, { teamId }] of puzSolveTimes.entries()) {
      solveTimeRanks[teamId] ??= {};
      solveTimeRanks[teamId][puzName] = i;
    }
  }

  return {
    globalRanks,
    solveTimes,
    solveTimeRanks,
    puzStats,
    teamStats,
  };
};

function BigBoardPage() {
  const showHidden = useBigBoardPreferencesStore((state) => state.showHidden);
  const setShowHidden = useBigBoardPreferencesStore(
    (state) => state.setShowHidden
  );
  const puzzleSortOrder = useBigBoardPreferencesStore(
    (state) => state.puzzleSortOrder
  );
  const setPuzzleSortOrder = useBigBoardPreferencesStore(
    (state) => state.setPuzzleSortOrder
  );
  const teamScopeState = useTeamScopeState();
  const teams = useGlobalScopeState(ScopeType.TEAM_LIST) ?? {};
  const huntAdminState = useGlobalScopeState(ScopeType.HUNT_ADMIN);
  const isAdmin = useIsAdmin() ?? false;
  const bigBoard = useGlobalScopeState(ScopeType.BIG_BOARD);
  const createTeamIds = useCreateBigBoardPageTeamIds(showHidden);
  const bigBoardPuzzleFilter = useNavStore(
    (state) => state.bigBoardPuzzleFilter
  );

  useRedirectIfNonAdmin();

  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const interval = setInterval(() => setNow(Date.now()), 20000);
    return () => clearInterval(interval);
  }, [now, setNow]);

  // Check that the SERVER scope has been synced by checking
  // that puzzles is non-empty.
  if (
    bigBoard === null ||
    teamScopeState === null ||
    huntAdminState === null ||
    createTeamIds === null
  )
    return <LargeSpinner />;
  const { puzzles, teamAdminData } = huntAdminState;
  const teamIds = createTeamIds();

  const { huntEndTime } = teamScopeState;

  const { globalRanks, solveTimeRanks, puzStats, teamStats } =
    computeBigBoardStats(bigBoard, teams, puzzles);

  const puzzleColGroupSpecs: {
    key: string;
    header: string;
    filterFunc: (puz: PuzzleData) => boolean;
  }[] = [
    {
      key: "big-meta",
      header: "",
      filterFunc: (puz) => puz.isBigMeta ?? false,
    },
    {
      key: "celestials",
      header: "Celestials",
      filterFunc: (puz) => puz.isCelestial ?? false,
    },
    {
      key: "micropuzzles",
      header: "Micropuzzles",
      filterFunc: (puz) =>
        isPuzzleMicropuzzle(puz) &&
        puz.customPuzzleData === undefined &&
        normalizeForSearch(
          puz.displayName !== "" ? puz.displayName : puz.puzName
        ).includes(normalizeForSearch(bigBoardPuzzleFilter)),
    },
    {
      key: "custom",
      header: "Custom",
      filterFunc: (puz) => puz.customPuzzleData !== undefined,
    },
    {
      key: "story",
      header: "Story beats",
      filterFunc: (puz) => puz.isStory ?? false,
    },
  ];
  const sortedPuzzleGroups = puzzleColGroupSpecs.map(({ key, filterFunc }) =>
    Object.values(puzzles)
      .filter(filterFunc)
      .sort((puz1, puz2) => {
        switch (
          ["story"].includes(key)
            ? BigBoardPuzzleSortOrder.CANONICAL
            : puzzleSortOrder
        ) {
          case BigBoardPuzzleSortOrder.CANONICAL: {
            return puz1.order - puz2.order;
          }
          case BigBoardPuzzleSortOrder.SOLVES: {
            const { numUnlocks: numUnlocks1 = 0, numSolves: numSolves1 = 0 } =
              puzStats[puz1.puzName] ?? {};
            const { numUnlocks: numUnlocks2 = 0, numSolves: numSolves2 = 0 } =
              puzStats[puz2.puzName] ?? {};

            const diffNumSolves = numSolves2 - numSolves1;
            if (diffNumSolves !== 0) return diffNumSolves;
            const diffNumUnlocks = numUnlocks2 - numUnlocks1;
            if (diffNumUnlocks !== 0) return diffNumUnlocks;
            return puz1.order - puz2.order;
          }
        }
      })
  );
  const sortedPuzzles = sortedPuzzleGroups.flat();

  const puzzleGroupCols = sortedPuzzleGroups.map((puzzleGroup) =>
    makePuzListColData(puzzleGroup)
  );
  const cols: BigBoardColumnData[] = puzzleGroupCols.flat();

  const rowsDom = teamIds.map((teamId) => {
    const {
      numHintsTotal = 0,
      unlocks = {},
      hope,
    } = bigBoard.teams[teamId] ?? {};
    const {
      lastSolveTime = 0,
      numSolves = 0,
      numWrongGuesses = 0,
      numHintsUsed = 0,
    } = teamStats[teamId] ?? {};
    const globalRank = globalRanks[teamId];
    const adminData =
      !isAdmin || settings.isImpersonate ? null : teamAdminData[teamId] ?? null;
    return (
      <tr key={teamId}>
        <td>
          <TeamListTeamName teamId={teamId} />
        </td>
        <td>
          {adminData === null ? null : (
            <span style={{ display: "flex" }}>
              <DjangoLink href={`impersonate/${adminData.userId}`}>
                <Tooltip text="Impersonate">
                  <Twemoji>🕵️</Twemoji>
                </Tooltip>
              </DjangoLink>
              <RoutedLink path={`/sock-admin/${teamId}`}>
                <Tooltip text="Sock Admin">
                  <Twemoji>🧦️</Twemoji>
                </Tooltip>
              </RoutedLink>
            </span>
          )}
        </td>
        <td>{globalRank !== undefined ? globalRank + 1 : null}</td>
        <td>
          {numSolves <= 0 ? null : numSolves}
          {numWrongGuesses <= 0 ? null : (
            <small>&minus;{numWrongGuesses}</small>
          )}
        </td>
        <td>
          {numHintsUsed <= 0 && numHintsTotal <= 0
            ? null
            : `${numHintsUsed} / ${numHintsTotal}`}
        </td>
        <BigBoardHopeCell hopeSnapshot={hope} />
        <td>
          {lastSolveTime ? <ShortDate timestamp={lastSolveTime} /> : null}
        </td>
        {sortedPuzzles.map(({ puzName }) => {
          return (
            <BigBoardPuzzleCell
              key={puzName}
              teamPuzState={unlocks[puzName]}
              huntEndTime={huntEndTime}
              rank={solveTimeRanks[teamId]?.[puzName]}
            />
          );
        })}
      </tr>
    );
  });

  const leftCols = [
    <th key="team">Team</th>,
    <th key="impersonate"></th>,
    <th key="rank">#</th>,
    <th key="num-solves">
      <Tooltip text="Solves">
        <Twemoji>✅</Twemoji>
      </Tooltip>
    </th>,
    <th key="num-hints">
      <Tooltip text="Hints">
        <Twemoji>💡</Twemoji>
      </Tooltip>
    </th>,
    <th key="hope">
      <Tooltip text="Hope">
        <Twemoji>✨</Twemoji>
      </Tooltip>
    </th>,
    <th key="last-solve">Last solve</th>,
  ];

  const makePuzStatsRow = (
    rowName: string,
    makeElem: (puzName: string) => ReactNode
  ) => {
    return (
      <tr style={{ fontSize: "80%" }}>
        <td>{rowName}</td>
        <td colSpan={leftCols.length - 1} />
        {sortedPuzzles.map(({ puzName }) => makeElem(puzName))}
      </tr>
    );
  };
  const makePercentage = (num: number, denom: number) => {
    if (num === 0 || denom === 0) return "";
    return `${Math.round((100 * num) / denom)}`;
  };

  return (
    <>
      <div className="big-board">
        <table>
          <colgroup>
            {leftCols.map((col, i) => (
              <col key={i} />
            ))}
            {puzzleGroupCols.map((puzzleGroup) =>
              makeBigBoardColGroup(puzzleGroup)
            )}
          </colgroup>
          <thead>
            <tr className="big-board-header-groups">
              <th colSpan={leftCols.length} />
              {arrayZipMap(
                puzzleColGroupSpecs,
                sortedPuzzleGroups,
                ({ key, header }, puzzleGroup) =>
                  puzzleGroup.length > 0 ? (
                    <th key={key} colSpan={puzzleGroup.length}>
                      <div className="big-board-header-group">{header}</div>
                    </th>
                  ) : null
              )}
            </tr>
            <tr>
              {leftCols}
              {cols.map((colData) => (
                <BigBoardHeader key={colData.colKey} colData={colData} />
              ))}
            </tr>
          </thead>
          <tbody>
            {makePuzStatsRow("Solves", (puzName) => (
              <td key={puzName} className="big-board-solved">
                {puzStats[puzName]?.numSolves ?? 0}
              </td>
            ))}
            {makePuzStatsRow("Guesses", (puzName) =>
              puzzles[puzName].answer === null ? (
                <td key={puzName} />
              ) : (
                <td key={puzName} className="big-board-wrong">
                  {(puzStats[puzName]?.numWrongGuesses ?? 0) +
                    (puzStats[puzName]?.numSolves ?? 0)}
                </td>
              )
            )}
            {makePuzStatsRow("Unlocks", (puzName) => (
              <td key={puzName} className="big-board-unlocked">
                {puzStats[puzName]?.numUnlocks ?? 0}
              </td>
            ))}
            {makePuzStatsRow("Hints", (puzName) => (
              <td key={puzName} className="big-board-hinted">
                {puzStats[puzName]?.numHintsUsed ?? 0}
              </td>
            ))}
            {makePuzStatsRow("%Solve/Guess", (puzName) =>
              puzzles[puzName].answer === null ? (
                <td key={puzName} />
              ) : (
                <td key={puzName}>
                  {makePercentage(
                    puzStats[puzName]?.numSolves ?? 0,
                    (puzStats[puzName]?.numWrongGuesses ?? 0) +
                      (puzStats[puzName]?.numSolves ?? 0)
                  )}
                </td>
              )
            )}
            {makePuzStatsRow("%Solve/Unlock", (puzName) => (
              <td key={puzName}>
                {makePercentage(
                  puzStats[puzName]?.numSolves ?? 0,
                  puzStats[puzName]?.numUnlocks ?? 0
                )}
              </td>
            ))}
            {rowsDom}
          </tbody>
        </table>
        <div className="big-board-right-padding" />
      </div>
      <div className="big-board-footer">
        <BigBoardTeamSearch />
        <BigBoardPageSelection />
        <BigBoardCheckboxOption
          desc=<span className="big-board-show-hidden-teams-label">
            Show hidden teams
          </span>
          state={showHidden}
          onChange={setShowHidden}
        />
        <div className="big-board-sort-selection">
          <label htmlFor="big-board-sort-order">Sort puzzles:</label>
          <select
            id="big-board-sort-order"
            value={puzzleSortOrder}
            onChange={(e) => {
              setPuzzleSortOrder(e.target.value as BigBoardPuzzleSortOrder);
            }}
          >
            {Object.values(BigBoardPuzzleSortOrder).map((order) => (
              <option key={order} value={order}>
                {order}
              </option>
            ))}
          </select>
        </div>
        <BigBoardPuzzleSearch />
      </div>
    </>
  );
}

export default BigBoardPage;
