import { useRef, useState } from "react";

import { ScopeType } from "sockapi/scope-types";
import { Scope } from "sockapi/scopes";

import { PUZZLE_144_CONFIG } from "sockapi/scope-specs/team-puzzle-144-spec";

import { useTeamId, useSockClient } from "stores/ServerInteractionStore";
import { useScopeStateResolvable, useIsHuntOver } from "stores/ScopeStateStore";
import { toastr } from "Globals";
import { useUILock } from "ui-locks";
import { Spinner } from "components/Loading";
import { SubmissionsClosedInfobox } from "components/PuzzleContent/puzzle-infoboxes";
import "./Puzzle144.css";

export function Puzzle144() {
  const teamId = useTeamId();
  const sockClient = useSockClient();
  const puz144State = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_144,
    teamId === null ? null : { teamId }
  );
  const isHuntOver = useIsHuntOver();
  const textInputRef = useRef<HTMLTextAreaElement>(null);
  const submitLock = useUILock();
  const { isHeld: isSubmitLockHeld } = submitLock;

  if (teamId === null || puz144State === null || isHuntOver === null)
    return <Spinner />;
  const { req, resp } = puz144State;
  const isLocked = req !== undefined;
  const isPending = req !== undefined && resp === undefined;
  const scope: Scope<ScopeType.TEAM_PUZZLE_144> = {
    type: ScopeType.TEAM_PUZZLE_144,
    teamId,
  };

  const formatNumPoints = (numPoints: number): string => {
    const tenTimes = Math.round(numPoints * 10);
    if (tenTimes % 10 === 0) return numPoints.toString();
    return numPoints.toFixed(1);
  };

  return (
    <div className="puzzle-144">
      <textarea
        disabled={isLocked}
        defaultValue={req?.text ?? ""}
        maxLength={PUZZLE_144_CONFIG.maxLength}
        ref={textInputRef}
        placeholder={`Write your answer here (max ${PUZZLE_144_CONFIG.maxLength} characters).`}
      />
      {!isLocked ? (
        <>
          <div>Be sure to check your work. You may only submit once.</div>
          {isHuntOver ? <SubmissionsClosedInfobox /> : null}
          <div>
            <button
              disabled={isSubmitLockHeld}
              onClick={() => {
                submitLock.acquireAndRun(async (getIsCanceled) => {
                  if (textInputRef.current === null) return;
                  if (textInputRef.current.value.trim() === "") {
                    toastr.warning("Please enter a response.");
                    return;
                  }
                  await sockClient.sendScopeStepAndWaitAsync(scope, {
                    submitReq: {
                      text: textInputRef.current.value,
                    },
                  });
                });
              }}
            >
              Submit
            </button>
          </div>
        </>
      ) : null}
      {isPending ? (
        <>Thank you for your submission. We will evaluate it shortly.</>
      ) : null}
      {resp !== undefined ? (
        <>
          <div>{resp.text}</div>
          <div className="puzzle-144-grade">
            {formatNumPoints(resp.numPoints)} / 10
          </div>
        </>
      ) : null}
    </div>
  );
}

export function Puzzle144Rubric(props: {
  headers: string[];
  checkboxStrings: string[];
}) {
  const { headers, checkboxStrings } = props;
  const [selections, setSelections] = useState<boolean[]>(
    Array(11).fill(false)
  );
  const score = Math.min(
    Math.max(
      10 +
        (selections[0] ? 1 : 0) +
        (selections[1] ? 1 : 0) +
        (selections[2] ? -1 : 0) +
        (selections[3] ? -1 : 0) +
        (selections[4] ? -1 : 0) +
        (selections[5]
          ? -5
          : (selections[6] ? -3 : 0) + (selections[7] ? -1 : 0)) +
        (selections[8]
          ? -5
          : (selections[9] ? -2 : 0) + (selections[10] ? -1 : 0)),
      0
    ),
    11
  );
  const makeCheckbox = (index: number) => {
    return (
      <label>
        <input
          type="checkbox"
          checked={selections[index]}
          onChange={() => {
            const newSelections = [...selections];
            newSelections[index] = !selections[index];
            setSelections(newSelections);
          }}
        />
        {checkboxStrings[index]}
      </label>
    );
  };
  return (
    <>
      <p>{headers[0]}</p>
      <ul className="puz144-rubric-list">
        <li>{makeCheckbox(0)}</li>
        <li>{makeCheckbox(1)}</li>
      </ul>
      <p>{headers[1]}</p>
      <ul className="puz144-rubric-list">
        <li>{makeCheckbox(2)}</li>
        <li>{makeCheckbox(3)}</li>
        <li>{makeCheckbox(4)}</li>
      </ul>
      <p>{headers[2]}</p>
      <ul className="puz144-rubric-list">
        <li>{makeCheckbox(5)}</li>
        <li>{makeCheckbox(6)}</li>
        <li>{makeCheckbox(7)}</li>
      </ul>
      <p>{headers[3]}</p>
      <ul className="puz144-rubric-list">
        <li>{makeCheckbox(8)}</li>
        <li>{makeCheckbox(9)}</li>
        <li>{makeCheckbox(10)}</li>
      </ul>
      <p>
        Base score: <span className="puz144-rubric-score">{score} / 10</span>
      </p>
    </>
  );
}
