import { useState } from "react";
import Twemoji from "react-twemoji";
import "overlayscrollbars/overlayscrollbars.css";

import { ScopeType } from "sockapi/scope-types";
import { TeamPuzzleSockAPIScopeState } from "sockapi/scope-specs/team-spec";
import {
  doesSolutionExist,
  isSolutionPageAvailable,
} from "sockapi/scope-specs/solution-content-spec";
import { isPuzzleEligibleForHint } from "sockapi/scope-specs/team-hints-spec";
import { PuzzleMetadata } from "sockapi/puzzle-data";
import { useCampLayout, useInPuzzlePage } from "stores/NavStore";
import {
  useTeamId,
  useShouldDisplayAdmin,
} from "stores/ServerInteractionStore";
import {
  useUpdateBrowserWidePersistentState,
  makeDefaultCutsceneState,
} from "stores/BrowserWidePersistentState";
import {
  useScopeStateResolvable,
  useIsPuzzleSolved,
  isPuzzleTeamSolved,
  useIsHuntOver,
  usePuzzleDisplayNames,
} from "stores/ScopeStateStore";
import { IconType, Icon, PuzzleIcon } from "components/Icon";
import { RoutedLink, PuzzleLink } from "components/Link";
import { Spinner } from "components/Loading";
import { clsObj } from "client-util";
import Tooltip from "components/Tooltip";
import { usePuzzleBodyDependencies } from "pages/PuzzlePage";
import "./PuzzlePageToolbar.css";

const SCRAMBLE_FOR_THE_STARS_FAKE_PUZNAME = "scramble-for-the-stars";
const JFK_SEQUENCE_ID = "jfk";
const JFK_FAKE_PUZNAME = "jfk";

function SequenceDisplay(props: {
  puzzlesInSequence: PuzzleMetadata[];
  selectedPuzName: string;
}) {
  const { puzzlesInSequence, selectedPuzName } = props;
  const displayNames = usePuzzleDisplayNames();
  if (displayNames === null) return <Spinner inline={true} />;
  return (
    <>
      {puzzlesInSequence.map((puzData) => (
        <span
          className={clsObj({
            selected: puzData.puzName === selectedPuzName,
          })}
          key={puzData.puzName}
        >
          {puzData.puzName === selectedPuzName ? (
            <PuzzleIcon puzData={puzData} />
          ) : puzData.puzName === SCRAMBLE_FOR_THE_STARS_FAKE_PUZNAME ? (
            <a
              href="https://2017.galacticpuzzlehunt.com/puzzle/3/5.html"
              target="_blank"
              className="sequence-icon"
              rel="noreferrer"
            >
              <Tooltip text="Scramble for the Stars" placement="bottom">
                <Twemoji tag="span">🏀</Twemoji>
              </Tooltip>
            </a>
          ) : puzData.puzName === JFK_FAKE_PUZNAME ? (
            <a
              href="https://puzzles.mit.edu/2012/puzzles/ogre_of_la_mancha/jfk_shags_a_sad_slim_lass/"
              target="_blank"
              className="sequence-icon"
              rel="noreferrer"
            >
              <Tooltip text="JFK SHAGS A SAD SLIM LASS" placement="bottom">
                <Twemoji tag="span">🎭</Twemoji>
              </Tooltip>
            </a>
          ) : (
            <PuzzleLink puzName={puzData.puzName}>
              <Tooltip text={displayNames[puzData.puzName]} placement="bottom">
                <PuzzleIcon puzData={puzData} />
              </Tooltip>
            </PuzzleLink>
          )}
        </span>
      ))}
    </>
  );
}

export default function PuzzlePageToolbar(props: {
  puzData: TeamPuzzleSockAPIScopeState;
}) {
  const { puzData } = props;
  const {
    puzName,
    isScrambleSequel = false,
    isCelestial = false,
    isBigMeta = false,
    sequenceId,
  } = puzData;
  const deps = usePuzzleBodyDependencies(puzData);
  const updateBrowserWidePersistentState =
    useUpdateBrowserWidePersistentState();
  const campLayout = useCampLayout();
  const isSolved = useIsPuzzleSolved(puzName) ?? false;
  const teamId = useTeamId();
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const teamCannedHintsScopeState = useScopeStateResolvable(
    ScopeType.TEAM_CANNED_HINTS,
    teamId === null ? null : { teamId }
  );
  const teamHintsScopeState = useScopeStateResolvable(
    ScopeType.TEAM_HINTS,
    teamId === null ? null : { teamId }
  );
  const isHuntOver = useIsHuntOver();
  const showSolution =
    isHuntOver !== null
      ? doesSolutionExist(puzData) &&
        (isHuntOver ||
          isSolutionPageAvailable(puzName, true, isSolved) ||
          shouldDisplayAdmin)
      : null;
  const numTotalCannedHints =
    teamCannedHintsScopeState?.cannedHints[puzName]?.numTotal ?? 0;
  const numTotalHintTokens = teamHintsScopeState?.numTotalTokens ?? 0;
  const numUsedHints = Object.keys(
    teamHintsScopeState?.hints[puzName] ?? {}
  ).length;
  const showHints =
    isPuzzleEligibleForHint(puzData) &&
    (numTotalCannedHints > 0 || numTotalHintTokens > 0 || numUsedHints > 0);
  const [{ inPuzzle, inSolution, inHints, inStats }] = useState(
    useInPuzzlePage()
  );

  if (
    campLayout === null ||
    teamCannedHintsScopeState === null ||
    showSolution === null
  )
    return <Spinner inline={true} />;

  const { isSinglePane, isBeforeFirstWish } = campLayout;
  const showBackButton = isSinglePane && !isBeforeFirstWish;
  const {
    cutsceneState,
    isPuzzleSolved,
    puzzlesInSequence,
    celestialsAsSequence,
  } = deps ?? {};
  const hintIcons = [];
  if (numUsedHints > 0)
    hintIcons.push(
      <Twemoji key="custom" tag="span">
        💡
      </Twemoji>
    );
  if (puzName in teamCannedHintsScopeState.cannedHints) {
    const { numTotal, numOpened } =
      teamCannedHintsScopeState.cannedHints[puzName];
    for (let i = 0; i < numTotal; ++i)
      hintIcons.push(
        <Icon
          key={`canned-${i}`}
          icon={
            i < numOpened ? IconType.OPEN_CANNED_HINT : IconType.CANNED_HINT
          }
        />
      );
  }
  // if solution is open, we care less about hints, so declutter a little
  const showHintIcons =
    (!showSolution || shouldDisplayAdmin) && hintIcons.length;
  const shownPuzzlesInSequence = (() => {
    if (deps === null) return null;
    if (isCelestial || isBigMeta) return celestialsAsSequence ?? null;
    if (isScrambleSequel)
      return [
        {
          // HACK: use a fake puzzle entry
          puzName: SCRAMBLE_FOR_THE_STARS_FAKE_PUZNAME,
          slug: "",
          displayName: "",
          unlockTime: 0,
        },
        puzData,
      ];
    if (sequenceId !== undefined && sequenceId === JFK_SEQUENCE_ID)
      return [
        {
          // HACK: use a fake puzzle entry
          puzName: JFK_FAKE_PUZNAME,
          slug: "",
          displayName: "",
          unlockTime: 0,
        },
        ...(puzzlesInSequence ?? [puzData]),
      ];
    return puzzlesInSequence ?? [puzData];
  })();
  const showStats =
    !puzData.isStory &&
    (isHuntOver ||
      shouldDisplayAdmin ||
      puzData.customPuzzleData?.srcTeamId === teamId);

  return (
    <div className="puzzle-page-aux-toolbar">
      {showBackButton ? (
        <RoutedLink path="/puzzles" button={true}>
          ←
        </RoutedLink>
      ) : null}
      {shownPuzzlesInSequence === null ? (
        <Spinner
          inline
          style={{
            height: "2em",
            width: "2em",
            flexGrow: undefined,
          }}
        />
      ) : (
        <div className="sequence-nav">
          <SequenceDisplay
            puzzlesInSequence={shownPuzzlesInSequence}
            selectedPuzName={puzName}
          />
        </div>
      )}
      <div className="button-squish-zone secondary">
        {showSolution || showHints ? (
          <PuzzleLink puzName={puzName} button={true} disabled={inPuzzle}>
            <span className="squishable-link-text">Puzzle</span>
            <Twemoji className="squishable-link-icon">🧩️</Twemoji>
          </PuzzleLink>
        ) : null}
        {showSolution ? (
          <PuzzleLink
            puzName={puzName}
            subpage="solution"
            button={true}
            disabled={inSolution}
          >
            <span className="squishable-link-text">Solution</span>
            <Twemoji className="squishable-link-icon">📚️</Twemoji>
          </PuzzleLink>
        ) : null}
        {showHints ? (
          <PuzzleLink
            puzName={puzName}
            subpage="hints"
            button={true}
            disabled={inHints}
          >
            {showHintIcons ? hintIcons : null}
            <span className="squishable-link-text"> Hints</span>
            <Twemoji className="squishable-link-icon">❓️</Twemoji>
          </PuzzleLink>
        ) : null}
        {showStats ? (
          <PuzzleLink
            puzName={puzName}
            subpage="stats"
            button={true}
            disabled={inStats}
          >
            <span className="squishable-link-text">Stats</span>
            <Twemoji className="squishable-link-icon">🧮️</Twemoji>
          </PuzzleLink>
        ) : null}
        {(cutsceneState?.historyPosition ?? null) != null ? (
          isPuzzleTeamSolved(puzData) ? (
            // If the puzzle has been solved by the team but not
            // locally, give the user the option to skip it.
            <a
              onClick={() => {
                updateBrowserWidePersistentState({
                  completedStoryBeats: { [puzName]: true },
                  cutscenesState: {
                    [puzName]: makeDefaultCutsceneState(),
                  },
                });
              }}
            >
              <button>{isPuzzleSolved ? "Exit" : "Skip"}</button>
            </a>
          ) : (
            <a
              onClick={() => {
                updateBrowserWidePersistentState({
                  cutscenesState: {
                    [puzName]: makeDefaultCutsceneState(),
                  },
                });
              }}
            >
              <button>Reset</button>
            </a>
          )
        ) : null}
      </div>
    </div>
  );
}
