function PinButton({ puzName }: { puzName: string }) {
  const pinnedPuzzles = usePinnedPuzzles();
  const isPinned = pinnedPuzzles.includes(puzName);
  const updateBrowserWidePersistentState =
    useUpdateBrowserWidePersistentState();
  return (
    <a
      className={clsObj({
        "pin-button": true,
        selected: isPinned,
      })}
      href="#"
      onClick={(evt) => {
        evt.preventDefault();
        updateBrowserWidePersistentState({
          pinnedPuzzles: isPinned
            ? pinnedPuzzles.filter((other) => other !== puzName)
            : [...pinnedPuzzles, puzName],
        });
      }}
    >
      <Tooltip
        text={`${
          isPinned ? "Unpin" : "Pin"
        } this puzzle. This is just for your convenience and doesn’t affect your teammates.`}
        placement="bottom"
      >
        <Twemoji>📌️</Twemoji>
      </Tooltip>
    </a>
  );
}

function PuzzlePageTitleDisplay(props: {
  puzData: TeamPuzzleSockAPIScopeState;
}) {
  const { puzData } = props;
  const { puzName } = puzData;
  const teamId = useTeamId();
  const sockClient = useSockClient();
  const teamScopeState = useTeamScopeState();
  const displayName = usePuzzleDisplayName(puzName);
  const customTitles =
    useScopeStateResolvable(
      ScopeType.TEAM_TITLES,
      teamId !== null ? { teamId } : null
    )?.titles ?? null;
  const isPuzzle105Unlocked =
    teamScopeState?.puzzles[PUZZLE_105_CONFIG.puzName] !== undefined;
  const puzzle105State = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_105,
    isPuzzle105Unlocked && teamId !== null ? { teamId } : null
  );
  const puzzleContent = useScopeStateResolvable(ScopeType.PUZZLE_CONTENT, {
    puzName,
  });
  const [isSettingCustomTitle, setIsSettingCustomTitle] = useState(false);
  const setCustomTitleLock = useUILock();
  const customTitleInputRef = useRef<HTMLInputElement>(null);
  const campLayout = useCampLayout();

  if (
    teamId === null ||
    teamScopeState === null ||
    displayName === null ||
    customTitles === null ||
    puzzleContent === null ||
    (isPuzzle105Unlocked && puzzle105State === null) ||
    campLayout === null
  )
    return <Spinner inline={true} />;

  const { isBeforeFirstWish } = campLayout;
  const setCustomTitle = () => {
    setCustomTitleLock.acquireAndRun(async (getIsCanceled) => {
      if (customTitleInputRef.current === null) return;
      const newTitle = customTitleInputRef.current.value.trim();
      await sockClient.sendScopeStepAndWaitAsync(
        {
          type: ScopeType.TEAM_TITLES,
          teamId,
        },
        {
          setTitle: {
            puzName,
            title: newTitle,
          },
        }
      );
      if (getIsCanceled()) return;
      setIsSettingCustomTitle(false);
    });
  };
  const customTitle = customTitles[puzName];

  return (
    <>
      <div className="puzzle-header">
        {isSettingCustomTitle ? (
          <input
            type="text"
            ref={customTitleInputRef}
            autoFocus
            maxLength={CUSTOM_TITLE_MAX_LENGTH}
            defaultValue={customTitle}
            disabled={setCustomTitleLock.isHeld}
            onBlur={() => setCustomTitle()}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                setCustomTitle();
              }
            }}
          />
        ) : (
          <h1>
            {!isBeforeFirstWish ? <PinButton puzName={puzName} /> : null}{" "}
            {displayName}{" "}
            {puzData.displayName === "" &&
            puzzle105State?.confirmedTitles[puzName] === undefined ? (
              <a
                className="puzzle-rename-button"
                href="#"
                onClick={(evt) => {
                  evt.preventDefault();
                  setIsSettingCustomTitle(true);
                }}
              >
                <Tooltip
                  text={`${
                    customTitle ? "Rename" : "Name"
                  } this star. This is just for your convenience and is shared with your team.`}
                  placement="bottom"
                >
                  <Twemoji>✏️</Twemoji>
                </Tooltip>
              </a>
            ) : null}
          </h1>
        )}
        {/* TODO: allow turning this off per-puzzle */}
        {puzData.isStory || puzzleContent.content.trim() === "" ? null : (
          <Tooltip text="Copy to clipboard!" placement="bottom">
            <button
              className="clipboard-button"
              onClick={Globals.handleClipboardButton}
            >
              <Twemoji>📋️</Twemoji>
            </button>
          </Tooltip>
        )}
      </div>
      {isSettingCustomTitle ? (
        <div className="section-box puzzle-section-box">
          <div>
            This star doesn’t seem to have a name! You can give it one to make
            it easier for your team to find it. Come back to change it anytime.
            This is not part of the puzzle.
          </div>
        </div>
      ) : null}
    </>
  );
}

// HACK: If we take cesium's change to manually render the component
// from Node, we won't be able to embed this directly in puzzle content.
function CustomPuzzleAdminQueueLink(props: { puzName: string }) {
  const { puzName } = props;
  const adminQueueState = useGlobalScopeState(ScopeType.ADMIN_QUEUE);

  // HACK
  if (!puzName.startsWith(PUZZLE_105_CONFIG.customPuzzlePuzNamePrefix))
    return null;

  if (adminQueueState === null) return <Spinner inline />;
  const adminQueueEntry = Object.entries(adminQueueState.tasks).find(
    ([taskId, task]) =>
      task.type === AdminQueueTaskType.PUZZLE_SUBMISSION &&
      task.submissionType === PuzzleSubmissionType.PUZZLE_105 &&
      task.teamId ===
        puzName.slice(PUZZLE_105_CONFIG.customPuzzlePuzNamePrefix.length)
  );
  if (adminQueueEntry === undefined) return <Spinner inline />;
  return (
    <div>
      <RoutedLink
        path={`/admin-queue/task/${adminQueueEntry[0]}`}
        button={true}
      >
        Admin queue task
      </RoutedLink>
    </div>
  );
}

export default function PuzzleBodyDisplay() {
  const puzData = useOutletContext<TeamPuzzleSockAPIScopeState>();
  const deps = usePuzzleBodyDependencies(puzData);
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const isSpectating = useIsAdminEnabledStore((state) => state.isSpectating);
  const [showLocked, setShowLocked] = useState(false);

  const {
    puzName,
    isStory = false,
    answerNormalization,
    hasMultipleAnswers,
  } = puzData;
  const {
    teamId,
    errataContent,
    renderCtx,
    teamAnswerableScopeState,
    isPuzzleUnlocked = null,
  } = deps ?? {};
  // Always return a non-undefined value to make typescript
  // check for exhaustiveness.
  const answerNormalizationNotice = ((): string | null => {
    if (answerNormalization === undefined) return null;
    switch (answerNormalization) {
      case AnswerNormalization.UPPERCASE_LETTERS_ONLY:
        return null;
      case AnswerNormalization.UPPERCASE_LETTERS_OR_SYMBOLS_ONLY:
      case AnswerNormalization.NFKD:
        return "This puzzle’s answer may contain digits, punctuation marks or other symbols.";
    }
  })();
  const showControls =
    (shouldDisplayAdmin && !isSpectating) || (settings.isPosthunt && !isStory);

  return (
    <div
      className={clsObj({
        "puzzle-page-body": true,
        "puzzle-page-body-full-width": isStory,
      })}
    >
      {errataContent && <ErrataDisplay contents={errataContent} />}
      <PuzzlePageTitleDisplay puzData={puzData} />
      {shouldDisplayAdmin ? (
        <CustomPuzzleAdminQueueLink puzName={puzName} />
      ) : null}
      {!renderCtx || isPuzzleUnlocked === null ? (
        <Spinner inline />
      ) : isPuzzleUnlocked || settings.factcheckMode || showLocked ? (
        <PuzzleContentDisplayPreloaded renderCtx={renderCtx} />
      ) : (
        <div className="locked-puzzle-content">
          <div>
            You have not unlocked this puzzle. As{" "}
            {settings.isPosthunt ? "a postsolver" : "an admin"}, you may click
            the button below to view it. Note that answer submission and other
            interactive features may not work if the puzzle is locked.
          </div>
          <div>
            <button
              onClick={() => {
                setShowLocked(true);
              }}
            >
              Show puzzle
            </button>
          </div>
        </div>
      )}
      <div className="section-box puzzle-section-box">
        {answerNormalizationNotice !== null ? (
          <div>{answerNormalizationNotice}</div>
        ) : null}
        {hasMultipleAnswers ?? false ? (
          <div>This puzzle has multiple answers.</div>
        ) : null}
      </div>
      {teamId !== undefined &&
      teamAnswerableScopeState !== undefined &&
      teamAnswerableScopeState != null ? (
        <PreviousGuessesDisplayPreloaded
          teamId={teamId}
          teamAnswerableScopeState={teamAnswerableScopeState}
        />
      ) : null}
      {settings.factcheckMode && teamId !== undefined ? (
        <>
          <h1>Solution</h1>
          <SolutionBodyDisplay />
          <h1>Canned Hints</h1>
          <AdminCannedHintsDisplay puzName={puzName} teamId={teamId} />
        </>
      ) : null}
      {showControls ? (
        <div className="posthunt-controls">
          <h3>{shouldDisplayAdmin ? "Admin" : "Postsolver"} controls</h3>
          {!shouldDisplayAdmin ? (
            <p>
              These controls are for your convenience as a postsolver and were
              not part of the original hunt experience. You may access the full
              hunt controls in the{" "}
              <RoutedLink path="/unlock">Unlocking page</RoutedLink>.
            </p>
          ) : null}
          <div className="posthunt-control">
            <AdminPuzzleControl puzName={puzName} />
          </div>
          <div className="posthunt-control">
            <AdminHopeControl />
          </div>
        </div>
      ) : null}
    </div>
  );
}
