import { PuzzleContentPreviewWithLink } from "components/PuzzleContent/PuzzleContentPreview";
import { Puzzle105Content } from "components/PuzzleContent/Puzzle105";

import "./WrapupEditPage.css";

const COMPONENTS = {
  Twemoji,
  LongDate,
  ShortDate,
  Duration,
  Icon,
  PuzzleIcon,
  PrizeIcon,
  DjangoLink,
  RoutedLink,
  PuzzleLink,
  TeamDisplayNameDisplay,
  Tooltip,
  Blanks,
  Flavor,
  PuzzleImage,
  PuzzleGallery,
  PuzzleAudio,
  Table,
  PuzzleGrid,
  PuzzleContentPreviewWithLink,
  Puzzle105Content,
};

class Section extends Component<{ content: string; doneRender: () => void }> {
  state: { output: MDXModule | null; error: Error | null } = {
    output: null,
    error: null,
  };

  static getDerivedStateFromError(error: Error) {
    return { error };
  }

  componentDidMount() {
    this.componentDidUpdate({});
  }

  componentDidUpdate(prevProps: { content?: string }) {
    const { content, doneRender } = this.props;
    if (content === prevProps.content) return;
    evaluate(content, runtime as EvaluateOptions)
      .then((output) => this.setState({ output, error: null }, doneRender))
      .catch((error) => this.setState({ error }));
  }

  render() {
    const { output, error } = this.state;
    if (error) return <div className="errorlist">{error.toString()}</div>;
    if (output)
      return createElement(output.default, { components: COMPONENTS });
    return null;
  }
}

export default function WrapupEditPage() {
  const staffId = useAdminPreferencesStore((state) => state.staffId);
  const setStaffId = useAdminPreferencesStore((state) => state.setStaffId);
  const [staffIdInputVal, setStaffIdInputVal] = useState("");
  const sockClient = useSockClient();
  const wrapupState = useGlobalScopeState(ScopeType.WRAPUP);
  const stepLock = useUILock();

  const [heads, setHeads] = useState<Element[]>([]);
  const doneRender = () =>
    setHeads([...document.querySelectorAll("h1,h2,h3,h4,h5")]);
  useEffect(() => {
    const links = document.querySelectorAll(".wrapup-page aside div");
    const highlight = () => {
      const rects = heads.map((head) => head.getBoundingClientRect());
      heads.forEach((head, i) =>
        links[i].classList.toggle(
          "highlight",
          (!rects[i + 1] || rects[i + 1].top > 0) && rects[i].top < innerHeight
        )
      );
    };
    document.addEventListener("scroll", highlight, { passive: true });
    highlight();
    return () => document.removeEventListener("scroll", highlight);
  }, [heads]);

  useRedirectIfNonAdmin();
  if (wrapupState === null) return <LargeSpinner />;

  return (
    <div className="below-nav centered-page wrapup-page">
      <aside>
        {heads.map((head) => (
          <div
            key={head.textContent}
            style={{ paddingLeft: `${head.tagName.substr(1)}ch` }}
            onClick={() => head.scrollIntoView()}
          >
            {head.textContent}
          </div>
        ))}
      </aside>
      <Modal
        isOpen={staffId === null}
        wrapperClassName="admin-queue-staff-id-modal-wrapper"
      >
        <div>Enter your Discord username.</div>
        <input
          type="text"
          value={staffIdInputVal}
          onChange={(e) => setStaffIdInputVal(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") setStaffId(staffIdInputVal.trim());
          }}
        />
        <button
          onClick={() => {
            setStaffId(staffIdInputVal.trim());
          }}
          disabled={staffIdInputVal.trim() === ""}
        >
          Let&rsquo;s go!
        </button>
      </Modal>
      <div className="wrapup-wrapper">
        <h1>Wrapup “Collaborative” Editor</h1>
        <div className="admin-queue-header-actions">
          <div className="admin-queue-header-staff-id">
            <div>You are: {staffId}</div>
            <div>
              <button onClick={() => setStaffId(null)}>Change</button>
            </div>
          </div>
        </div>
        {Object.keys(wrapupState)
          .sort()
          .map((id, i, list) => {
            const { content, claimer } = wrapupState[id];
            let timer: number | undefined = undefined;
            return (
              <div key={id}>
                <div className="wrapup-section">
                  <div>
                    <Section content={content} doneRender={doneRender} />
                  </div>
                  {(() => {
                    if (claimer === null)
                      return (
                        <button
                          disabled={stepLock.isHeld}
                          onClick={() => {
                            stepLock.acquireAndRun(async (getIsCanceled) => {
                              await sockClient.sendScopeStepAndWaitAsync(
                                {
                                  type: ScopeType.WRAPUP,
                                },
                                {
                                  id: list[i],
                                  claimer: staffId,
                                }
                              );
                            });
                          }}
                        >
                          Edit
                        </button>
                      );
                    if (claimer !== staffId)
                      return <button disabled>{claimer}</button>;
                    return (
                      <div className="wrapup-editing">
                        <textarea
                          defaultValue={content}
                          onInput={(evt) => {
                            window.clearTimeout(timer);
                            const { value } = evt.target as HTMLTextAreaElement;
                            if (value === content) return;
                            timer = window.setTimeout(async () => {
                              await sockClient.sendScopeStepAndWaitAsync(
                                {
                                  type: ScopeType.WRAPUP,
                                },
                                {
                                  id: list[i],
                                  content: value,
                                }
                              );
                            }, 1000);
                          }}
                        />
                        <button
                          disabled={stepLock.isHeld}
                          onClick={() => {
                            stepLock.acquireAndRun(async (getIsCanceled) => {
                              await sockClient.sendScopeStepAndWaitAsync(
                                {
                                  type: ScopeType.WRAPUP,
                                },
                                {
                                  id: list[i],
                                  claimer: null,
                                }
                              );
                            });
                          }}
                        >
                          Done
                        </button>
                      </div>
                    );
                  })()}
                </div>
                <div className="wrapup-between">
                  <button
                    disabled={stepLock.isHeld}
                    onClick={() => {
                      stepLock.acquireAndRun(async (getIsCanceled) => {
                        await sockClient.sendScopeStepAndWaitAsync(
                          {
                            type: ScopeType.WRAPUP,
                          },
                          {
                            id: generateId(list[i], list[i + 1]),
                            claimer: staffId,
                          }
                        );
                      });
                    }}
                  >
                    Add a new section
                  </button>
                </div>
              </div>
            );
          })}
      </div>
    </div>
  );
}
