import { useEffect, useRef, memo } from "react";
import { isPuzzleMicropuzzle } from "sockapi/puzzle-data";
import { TeamPuzzleSockAPIScopeState } from "sockapi/scope-specs/team-spec";
import { ScopeType } from "sockapi/scope-types";
import {
  useTeamScopeState,
  isPuzzleSolved,
  useScopeStateResolvable,
  usePuzzleDisplayName,
} from "stores/ScopeStateStore";
import { useNavStore } from "stores/NavStore";
import { useGachaStore } from "stores/GachaStore";
import { useCompletedStoryBeats } from "stores/BrowserWidePersistentState";
import { useTeamId } from "stores/ServerInteractionStore";
import {
  useUpdateSeparatelyPersistedState,
  getCurrentSpinAngle,
} from "stores/UserPreferencesStore";
import { IconType, Icon, PuzzleIcon } from "components/Icon";
import { PuzzleLink } from "components/Link";
import Tooltip from "components/Tooltip";
import { clsObj } from "client-util";

import "./StarMap.css";

type MapPos = { x: number; y: number };

function starAngle({ x, y }: MapPos) {
  return {
    rightAscension: (x / 100) * (2 * Math.PI),
    declination: ((60 - y) / 100) * ((80 / 180) * Math.PI),
  };
}

function starCoords(mapPos: MapPos) {
  const { rightAscension, declination } = starAngle(mapPos);
  return {
    x: Math.cos(declination) * Math.sin(rightAscension),
    y: Math.sin(declination),
    z: Math.cos(declination) * Math.cos(rightAscension),
  };
}

function Star({ puzData }: { puzData: TeamPuzzleSockAPIScopeState }) {
  const { puzName, mapPos } = puzData;
  const displayName = usePuzzleDisplayName(puzName);
  const initialSpinAngleRef = useRef(getCurrentSpinAngle());

  if (mapPos === undefined || displayName === null) return null;

  const { rightAscension, declination } = starAngle(mapPos);
  const proximity =
    1 -
    Math.abs(
      Math.abs(
        (rightAscension / Math.PI - initialSpinAngleRef.current / 180) % 2
      ) - 1
    ) +
    declination / Math.PI;
  const celestial = {
    blocks: "kid",
    olive: "olive",
    branch: "big_branch",
    farmer: "farmer",
    rock_lobster: "rock_lobster",
    pom_pom: "pompom_mopmop",
    ten_lions: "lions",
  }[puzName];
  return (
    <Tooltip
      className={clsObj({
        "star-map-star": true,
        "star-map-big-star": puzName === "branch",
        "star-map-dog-star": puzName === "pom_pom",
      })}
      text={displayName}
      style={{
        transform: `rotateY(${-rightAscension}rad) rotateX(${-declination}rad) translateZ(calc(var(--star-map-baseline) * -2))`,
        animationDelay: `calc(${2 * proximity} * var(--star-map-fadein))`,
      }}
    >
      <PuzzleLink puzName={puzName}>
        {celestial === undefined ? (
          <PuzzleIcon puzData={puzData} />
        ) : (
          <img src={`/static/images/cutscenes/${celestial}.png`} />
        )}
      </PuzzleLink>
    </Tooltip>
  );
}

function Fish() {
  const mapPos = { x: 10, y: 37 };
  const { rightAscension, declination } = starAngle(mapPos);
  const count = useNavStore((state) => state.fishCount);
  const props = {
    className: "star-map-star star-map-big-star",
    style: {
      transform: `rotateY(${-rightAscension}rad) rotateX(${-declination}rad) translateZ(calc(var(--star-map-baseline) * -2))`,
      animation: "none",
    },
  };
  const img = (
    <img
      src="/static/images/cutscenes/kero.png"
      style={{ opacity: (count - 10) / 30 }}
    />
  );
  if (count < 10) return null;
  if (count < 20) return <div {...props}>{img}</div>;
  if (count < 30)
    return (
      <Tooltip text="OwO, what’s this?" {...props}>
        {img}
      </Tooltip>
    );
  return (
    <Tooltip
      text={`You found Kero! UwU\n(This is an Easter egg.\nIt is not a puzzle.)`}
      {...props}
    >
      {img}
    </Tooltip>
  );
}

function Line({ pos1, pos2 }: { pos1?: MapPos; pos2?: MapPos }) {
  if (pos1 === undefined || pos2 === undefined) return null;

  // I'm sure there's some fancy trig formula for spherical angles, but I don't
  // know it so we're coordinate bashing.
  const coords1 = starCoords(pos1);
  const coords2 = starCoords(pos2);
  const distance = Math.sqrt(
    (coords1.x - coords2.x) ** 2 +
      (coords1.y - coords2.y) ** 2 +
      (coords1.z - coords2.z) ** 2
  );
  const midpoint = {
    x: (coords1.x + coords2.x) / 2,
    y: (coords1.y + coords2.y) / 2,
    z: (coords1.z + coords2.z) / 2,
  };
  const rightAscension = Math.atan2(midpoint.x, midpoint.z);
  const declination = Math.atan2(
    midpoint.y,
    Math.sqrt(midpoint.x ** 2 + midpoint.z ** 2)
  );
  const dot =
    (coords1.x - coords2.x) * Math.cos(rightAscension) -
    (coords1.z - coords2.z) * Math.sin(rightAscension);
  const obliquity =
    Math.acos(dot / distance) * Math.sign(coords1.y - coords2.y);
  const radial = Math.sqrt(midpoint.x ** 2 + midpoint.y ** 2 + midpoint.z ** 2);
  return (
    <div
      className="star-map-line"
      style={{
        width: `calc(${distance} * var(--star-map-baseline) * 2 - 4em)`,
        transform: `rotateY(${-rightAscension}rad) rotateX(${-declination}rad) rotateZ(${-obliquity}rad) translateZ(calc(var(--star-map-baseline) * -2 * ${radial}))`,
      }}
    />
  );
}

function Grass({ image, angle }: { image: string; angle: number }) {
  return (
    <div
      className="star-map-grass"
      style={{
        transform: `rotateY(${angle}deg) rotateX(10deg) translateZ(-600px)`,
        filter: "brightness(0.1)",
      }}
    >
      <img src={`/static/images/bg/${image}.png`} />
    </div>
  );
}

function Cans() {
  const teamId = useTeamId();
  const teamCannedHintsScopeState = useScopeStateResolvable(
    ScopeType.TEAM_CANNED_HINTS,
    teamId === null ? null : { teamId }
  );
  if (teamId === null || teamCannedHintsScopeState === null) return null;

  let opened = 0;
  for (const state of Object.values(teamCannedHintsScopeState.cannedHints))
    opened += state.numOpened;
  if (opened <= 0) return <Grass image="flowers" angle={210} />;

  const rows = [
    [32],
    [28, 21],
    [24, 6, 12],
    [18, 5, 3, 10],
    [15, 4, 1, 2, 8],
  ].map((row, i) => (
    <div key={i} className="star-map-cans">
      {row.map((order, j) => (
        <Icon
          key={j}
          icon={IconType.OPEN_CANNED_HINT}
          style={{ opacity: opened >= order ? 1 : 0 }}
        />
      ))}
    </div>
  ));
  return (
    <div
      className="star-map-grass"
      style={{
        transform:
          "rotateY(210deg) rotateX(-2.5deg) translateZ(-600px) scale(1.5)",
        filter: "brightness(0)",
      }}
    >
      {rows}
    </div>
  );
}

const campTransform =
  "rotateY(306deg) rotateX(-5deg) translateZ(-600px) scale(-0.5, 0.5)";

const StarMap = memo(function StarMap() {
  const teamScopeState = useTeamScopeState();
  const activePullAnimation = useGachaStore(
    (state) => state.activePullAnimation
  );
  const updateSeparatelyPersistedState = useUpdateSeparatelyPersistedState();
  const isPulling = activePullAnimation !== null;
  const completedStoryBeats = useCompletedStoryBeats();
  const mapRef = useRef<HTMLDivElement>(null);
  const skyRef = useRef<HTMLDivElement>(null);
  const campRef = useRef<HTMLDivElement>(null);
  const setFishCount = useNavStore((state) => state.setFishCount);
  const spinAngleRef = useRef(getCurrentSpinAngle());
  const spinState = useRef({
    speed: 0,
    hover: 0,
    last: 0,
    drag: 0,
    scroll: 0,
    click: false,
  });
  useEffect(() => {
    setFishCount(0);
  }, [setFishCount]);
  useEffect(() => {
    let active = true;
    const update = () => {
      const { current } = spinState;
      if (current.scroll) {
        current.speed = Math.min(0.5, Math.max(-0.5, current.scroll * 2));
        spinAngleRef.current += current.scroll * 10;
      } else if (current.click) {
        current.speed = Math.min(0.5, Math.max(-0.5, current.drag * 4));
        spinAngleRef.current += current.drag * 80;
      } else {
        current.speed = isPulling
          ? 0 // no spinning when pulling
          : Math.min(
              current.speed + 0.005,
              Math.max(current.speed - 0.005, current.hover)
            );
        spinAngleRef.current += current.speed * 8;
      }
      updateSeparatelyPersistedState({ spinAngle: spinAngleRef.current });
      current.scroll = 0;
      current.drag = 0;
      const skyTransform = `translateZ(var(--star-map-baseline)) rotateX(22.5deg) rotateY(${spinAngleRef.current}deg)`;
      if (skyRef.current !== null)
        skyRef.current.style.transform = skyTransform;
      // Transform the camp manually since GIFs don't seem to play
      // properly when nested with transform-style: preserve-3d
      if (campRef.current !== null)
        campRef.current.style.transform = `${skyTransform} ${campTransform}`;
      if (active) requestAnimationFrame(update);
    };
    update();
    const keydown = (evt: KeyboardEvent) => {
      if (evt.key === "ArrowLeft") spinState.current.hover = -0.1;
      if (evt.key === "ArrowRight") spinState.current.hover = 0.1;
      if (evt.key === "a") spinState.current.hover = -0.1;
      if (evt.key === "d") spinState.current.hover = 0.1;
      updateCursor();
    };
    document.addEventListener("keydown", keydown);
    const keyup = (evt: KeyboardEvent) => {
      if (evt.key === "ArrowLeft") spinState.current.hover = 0;
      if (evt.key === "ArrowRight") spinState.current.hover = 0;
      if (evt.key === "a") spinState.current.hover = 0;
      if (evt.key === "d") spinState.current.hover = 0;
      updateCursor();
    };
    document.addEventListener("keyup", keyup);
    document.documentElement.style.overscrollBehavior = "none";
    return () => {
      active = false;
      document.removeEventListener("keydown", keydown);
      document.removeEventListener("keyup", keyup);
      document.documentElement.style.overscrollBehavior = "";
    };
  }, [isPulling, updateSeparatelyPersistedState]);

  if (teamScopeState === null) return null;
  const shownStars = Object.values(teamScopeState.puzzles).filter(
    (puzData) =>
      (isPuzzleMicropuzzle(puzData) || puzData.isCelestial) &&
      isPuzzleSolved(puzData, completedStoryBeats)
  );
  const lines = shownStars
    .flatMap(
      (puzData) =>
        puzData.constellationEdges?.map((otherPuzName) => ({
          node1: puzData,
          node2: teamScopeState.puzzles[otherPuzName],
        })) ?? []
    )
    .filter(
      ({ node2 }) =>
        node2 !== undefined &&
        isPuzzleMicropuzzle(node2) &&
        isPuzzleSolved(node2, completedStoryBeats)
    );

  const updateCursor = () => {
    if (mapRef.current === null) return;
    mapRef.current.style.cursor = (() => {
      if (spinState.current.click) return "grabbing";
      if (spinState.current.hover < 0) return "w-resize";
      if (spinState.current.hover > 0) return "e-resize";
      return "";
    })();
  };
  const handleMove = ({ clientX }: { clientX: number }) => {
    if (spinState.current.click && skyRef.current !== null)
      skyRef.current.style.pointerEvents = "none";
    spinState.current.drag -=
      (clientX - spinState.current.last) / window.innerHeight;
    spinState.current.last = clientX;
    updateCursor();
  };
  const handleDown = ({ clientX }: { clientX: number }) => {
    spinState.current.click = true;
    spinState.current.drag = 0;
    spinState.current.last = clientX;
    updateCursor();
  };
  const handleUp = () => {
    if (skyRef.current !== null) skyRef.current.style.pointerEvents = "";
    spinState.current.click = false;
    updateCursor();
  };
  return (
    <div
      className={clsObj({
        "star-map": true,
        "star-map-wishing": isPulling,
      })}
      ref={mapRef}
      onMouseMove={(evt) => {
        const fraction = evt.clientX / window.innerWidth;
        if (fraction < 0.1) spinState.current.hover = fraction - 0.1;
        else if (fraction > 0.9) spinState.current.hover = fraction - 0.9;
        else spinState.current.hover = 0;
        handleMove(evt);
      }}
      onMouseDown={(evt) => {
        if (evt.button) return;
        evt.preventDefault();
        handleDown(evt);
      }}
      onMouseUp={(evt) => {
        if (evt.button) return;
        evt.preventDefault();
        handleUp();
      }}
      onMouseLeave={() => {
        spinState.current.hover = 0;
        handleUp();
      }}
      onWheel={(evt) => {
        // Horizontal scrolling only
        spinState.current.scroll -= evt.deltaX / window.innerHeight;
      }}
      onTouchMove={(evt) => handleMove(evt.touches[0])}
      onTouchStart={(evt) => handleDown(evt.touches[0])}
      onTouchEnd={() => handleUp()}
    >
      <div className="star-map-sky" ref={skyRef}>
        {shownStars.map((puzData) => (
          <Star puzData={puzData} key={puzData.puzName} />
        ))}
        {lines.map(({ node1, node2 }) => (
          <Line
            pos1={node1.mapPos}
            pos2={node2.mapPos}
            key={`${node1.puzName}-${node2.puzName}`}
          />
        ))}
        <Fish />
        <Grass image="grass2" angle={0} />
        <Grass image="flowers" angle={30} />
        <Grass image="grass3" angle={60} />
        <Grass image="grass2" angle={90} />
        <Grass image="grass2" angle={120} />
        <Grass image="grass1" angle={150} />
        <Grass image="grass3" angle={180} />
        <Cans />
        <Grass image="grass1" angle={240} />
        <Grass image="grass3" angle={270} />
      </div>
      <div
        className="star-map-grass star-map-fire"
        ref={campRef}
        style={{ transform: campTransform }}
      >
        <img src="/static/images/bg/fire.webp" />
        <div
          className="star-map-camp"
          onClick={(evt) => {
            setFishCount(useNavStore.getState().fishCount + 1);
            const { offsetX, offsetY } = evt.nativeEvent;
            const pie = new Image();
            pie.src = "/static/images/pie.svg";
            pie.style.left = `${offsetX}px`;
            pie.style.top = `${offsetY}px`;
            (evt.target as Element).append(pie);
            setTimeout(() => pie.remove(), 1000);
          }}
        />
      </div>
    </div>
  );
});

export default StarMap;
