const NEW_INDICATOR_SHOW_TIME_MS = 60 * 1000; // 1 minute

function SidebarPuzzleCard(
  props: Omit<PuzzleCardProps, "isActive" | "isNew"> & { unlockTime: number }
) {
  const {
    puzData: { puzName },
    unlockTime,
  } = props;
  const pagePuzName = usePuzName();
  const ref = useRef<HTMLDivElement>(null);
  const isActive = pagePuzName !== null && pagePuzName === puzName;
  const viewTimes = useViewTimes();
  const isSeen = viewTimes[puzName] !== undefined;
  const isLongPastUnlockTime = useReactiveTimeout(
    unlockTime + NEW_INDICATOR_SHOW_TIME_MS
  );
  const isNew = !isSeen && !(isLongPastUnlockTime ?? false);

  useEffect(() => {
    if (pagePuzName === null) return;
    if (pagePuzName !== puzName) return;
    if (ref.current === null) return;
    const boundingRect = ref.current.getBoundingClientRect();
    if (boundingRect.top < 0 || boundingRect.bottom > window.innerHeight)
      // This used to be smooth scrolling. For me, that causes janky animations
      // when navigating and doesn't even always end up at the right position.
      ref.current.scrollIntoView({ block: "center" });
  }, [pagePuzName, puzName]);

  return (
    <motion.div layout key={puzName} ref={ref}>
      <PuzzleCard {...props} isActive={isActive} isNew={isNew} />
    </motion.div>
  );
}

function CelestialsRequirementPuzzleCard() {
  const teamScopeState = useTeamScopeState();

  if (teamScopeState === null) return <Spinner inline={true} />;

  const celestialsData = Object.values(teamScopeState.puzzles).filter(
    ({ isCelestial }) => isCelestial ?? false
  );
  const numCelestialsUnlocked = celestialsData.length;
  const numCelestialsSolved = celestialsData.filter(
    ({ solveTime }) => solveTime !== undefined
  ).length;

  if (
    numCelestialsUnlocked < NUM_CELESTIALS ||
    numCelestialsSolved >= NUM_CELESTIALS
  )
    return null;

  return (
    <Tooltip text="Restore all Celestials to proceed!">
      <div className="puzzle-card unsolved puzzle-card-dummy">
        <div className="puzzle-card-title">
          <span className="puzzle-card-icons">
            <Twemoji tag="span">🔒</Twemoji>
          </span>
          <h3>
            {numCelestialsSolved} / {numCelestialsUnlocked} Celestials restored
          </h3>
        </div>
      </div>
    </Tooltip>
  );
}

function SidebarCardsWishLockedNoMemo({
  puzzles,
}: {
  puzzles: TeamPuzzleSockAPIScopeState[];
}) {
  const teamId = useTeamId();
  const completedStoryBeats = useCompletedStoryBeats();
  const teamCannedHintsScopeState = useScopeStateResolvable(
    ScopeType.TEAM_CANNED_HINTS,
    teamId === null ? null : { teamId }
  );
  const teamHintsScopeState = useScopeStateResolvable(
    ScopeType.TEAM_HINTS,
    teamId === null ? null : { teamId }
  );
  const displayNames = usePuzzleDisplayNames();
  const teamScopeState = useTeamScopeState();
  const isPuzzle105Unlocked =
    teamScopeState?.puzzles[PUZZLE_105_CONFIG.puzName] !== undefined;
  const isPuzzle139Unlocked =
    teamScopeState?.puzzles[PUZZLE_139_CONFIG.puzName] !== undefined;
  const puzzle105State = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_105,
    isPuzzle105Unlocked && teamId !== null ? { teamId } : null
  );
  const puzzle139State = useScopeStateResolvable(
    ScopeType.TEAM_PUZZLE_139,
    isPuzzle139Unlocked && teamId !== null ? { teamId } : null
  );

  if (
    teamId === null ||
    teamCannedHintsScopeState === null ||
    teamHintsScopeState === null ||
    displayNames === null ||
    (isPuzzle105Unlocked && puzzle105State === null) ||
    (isPuzzle139Unlocked && puzzle139State === null)
  )
    return <Spinner />;

  const { cannedHints } = teamCannedHintsScopeState;
  const puzzle105Status = puzzle105State?.status ?? null;
  const puzzle139Status = puzzle139State?.status ?? null;
  const rejections = {
    [PUZZLE_105_CONFIG.puzName]:
      puzzle105Status !== null &&
      puzzle105Status.type === Puzzle105StatusType.REJECTED,
    [PUZZLE_139_CONFIG.puzName]:
      puzzle139Status !== null &&
      puzzle139Status.type === Puzzle139StatusType.REJECTED,
  };

  return (
    <>
      {puzzles.map((puzData, i) => {
        const { puzName, answer } = puzData;
        const {
          numTotal: numTotalCannedHints,
          numOpened: numOpenedCannedHints,
        } = cannedHints[puzName] ?? { numTotal: 0, numOpened: 0 };
        const hasCannedHints = numTotalCannedHints > 0;
        const hasOpenedCannedHints = numOpenedCannedHints > 0;
        const hasUnpenedCannedHints =
          numTotalCannedHints - numOpenedCannedHints > 0;
        const hasHints =
          Object.keys(teamHintsScopeState?.hints[puzName] ?? {}).length > 0;
        return (
          <SidebarPuzzleCard
            key={puzName}
            answer={answer}
            isSolved={isPuzzleSolved(puzData, completedStoryBeats)}
            puzData={puzData}
            displayName={displayNames[puzName] ?? "Locked puzzle"}
            unlockTime={puzData.unlockTime}
            hasCannedHints={hasCannedHints}
            hasOpenedCannedHints={hasOpenedCannedHints}
            hasUnopenedCannedHints={hasUnpenedCannedHints}
            hasHints={hasHints}
            isRejected={rejections[puzName] ?? false}
          />
        );
      })}
    </>
  );
}

const SidebarCardsWishLocked = memo(SidebarCardsWishLockedNoMemo);

function SidebarCards({ puzzles }: { puzzles: TeamPuzzleSockAPIScopeState[] }) {
  const isPullInProgress = useIsPullInProgress();
  const [shownPuzzles, setShownPuzzles] = useState(puzzles);
  useEffect(() => {
    if (isPullInProgress) return;
    setShownPuzzles(puzzles);
  }, [puzzles, isPullInProgress]);
  return <SidebarCardsWishLocked puzzles={shownPuzzles} />;
}

const FILTERS = {
  cutscene: {
    icon: "🎬",
    name: "Cutscenes",
  },
  celestial: {
    icon: "💫",
    name: "Celestials",
  },
  star: {
    icon: "⭐",
    name: "Canonical Stars",
  },
  custom: {
    icon: "🌠",
    name: "Custom Stars",
  },
};

const SORTS = {
  default: "Default",
  alphabetical: "Alphabetical",
  oldest: "Oldest first",
  newest: "Newest first",
};

export function normalizeForSearch(s: string) {
  return s
    .toLowerCase()
    .replaceAll("×", "x")
    .replaceAll("’", "'")
    .replaceAll("ȷ", "j")
    .replaceAll("ó", "o")
    .replaceAll("ö", "o")
    .replaceAll("æ", "ae")
    .replaceAll("。", ".");
}

// Screw it we're doing this here too. We just need a quick and dirty way to
// save this scroll value while we're navigating around. There's still some
// jank but it's a little better???
let sidebarScroll = 0;

function Sidebar() {
  const sortedPuzzles = useSortedPuzzles();
  const pinnedPuzzles = usePinnedPuzzles();
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState<Record<string, boolean>>({
    cutscene: true,
    celestial: true,
    star: true,
    custom: true,
  });
  const [sort, setSort] = useState<keyof typeof SORTS>("default");
  const [showDrawer, setShowDrawer] = useState(false);
  const hasCelestialsUnlocked = !!sortedPuzzles?.find(
    ({ isCelestial }) => isCelestial ?? false
  );
  const hasCustomPuzzle = !!sortedPuzzles?.find(
    ({ customPuzzleData }) => !!customPuzzleData
  );
  const displayNames = usePuzzleDisplayNames();

  const puzzles = useMemo(() => {
    if (sortedPuzzles === null || displayNames === null) return null;

    return sortedPuzzles
      .map((puzData) => {
        const { puzName } = puzData;
        const name = displayNames[puzName] ?? "Unknown puzzle";
        return { ...puzData, name };
      })
      .filter(({ name }) => {
        return normalizeForSearch(name).includes(normalizeForSearch(search));
      })
      .filter((puzData) => {
        const {
          isStory = false,
          isCelestial = false,
          isBigMeta = false,
        } = puzData;
        return (
          (isStory && filter.cutscene) ||
          ((isCelestial || isBigMeta) && filter.celestial) ||
          (isPuzzleMicropuzzle(puzData) &&
            (puzData.customPuzzleData !== undefined
              ? filter.custom
              : filter.star))
        );
      })
      .sort((a, b) => {
        const isPinnedA = pinnedPuzzles.includes(a.puzName);
        const isPinnedB = pinnedPuzzles.includes(b.puzName);
        if (isPinnedA != isPinnedB) return +isPinnedB - +isPinnedA;
        switch (sort) {
          case "default": {
            if (!isPinnedA) return 0;
            return (
              pinnedPuzzles.indexOf(b.puzName) -
              pinnedPuzzles.indexOf(a.puzName)
            );
          }
          case "alphabetical":
            return displayNameOrder(a.name, b.name);
          case "oldest":
            return a.unlockTime - b.unlockTime;
          case "newest":
            return b.unlockTime - a.unlockTime;
        }
      });
  }, [filter, search, sort, sortedPuzzles, pinnedPuzzles, displayNames]);

  useEffect(() => {
    const handleClick = (ev: MouseEvent) => {
      const evTarget = ev.target as Element;
      if (!evTarget.closest(".sidebar-header")) setShowDrawer(false);
    };
    window.addEventListener("click", handleClick);
    return () => {
      window.removeEventListener("click", handleClick);
    };
  }, []);

  if (puzzles === null) return <Spinner />;
  return (
    <SidebarWrapper>
      <div className="sidebar-header">
        <input
          className="sidebar-search"
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Search"
          value={search}
        />
        <button
          className={clsObj({
            "sidebar-drawer-button": true,
            active: showDrawer,
          })}
          onClick={() => setShowDrawer(!showDrawer)}
        >
          ⥥
        </button>
        {showDrawer && (
          <div className="sidebar-drawer">
            <div className="sidebar-drawer-section">
              Show:
              {Object.entries(FILTERS).map(([key, { icon, name }]) =>
                (key === "celestial" && !hasCelestialsUnlocked) ||
                (key === "custom" && !hasCustomPuzzle) ? null : (
                  <button
                    key={key}
                    className={clsObj({ active: filter[key] })}
                    onClick={() =>
                      setFilter((prev) => ({ ...prev, [key]: !prev[key] }))
                    }
                  >
                    <Twemoji tag="span">{icon}</Twemoji>{" "}
                    {key === "star" && !hasCustomPuzzle ? "Stars" : name}
                  </button>
                )
              )}
            </div>
            <div className="sidebar-drawer-section">
              Sort:
              {Object.entries(SORTS).map(([key, name]) => (
                <button
                  key={key}
                  className={clsObj({ active: sort === key })}
                  onClick={() => setSort(key as keyof typeof SORTS)}
                >
                  {name}
                </button>
              ))}
            </div>
          </div>
        )}
      </div>
      <OverlayScrollbarsComponent
        options={defaultOverlayScrollbarsOptions}
        events={{
          initialized: (instance) => {
            const { scrollOffsetElement } = instance.elements();
            if (scrollOffsetElement.scrollTop === 0)
              scrollOffsetElement.scrollTop = sidebarScroll;
          },
          scroll: (instance) => {
            const { scrollOffsetElement } = instance.elements();
            sidebarScroll = scrollOffsetElement.scrollTop;
          },
        }}
        defer
      >
        <div className="sidebar-cards">
          {search ? null : <CelestialsRequirementPuzzleCard />}
          <SidebarCards puzzles={puzzles} />
        </div>
      </OverlayScrollbarsComponent>
    </SidebarWrapper>
  );
}

export default Sidebar;
