import "./ExchangePuzzle.css";

import { useState } from "react";

function range(n: number) {
  return [...Array(n).keys()];
}

export function ExchangePuzzle() {
  const [text, setText] = useState<string[]>(
    Array.from("ALNOAMCDAWDSDEPPATHTELKYDTERGNHI")
  );
  function handle(stride: number, start: number) {
    const buf = text.slice();
    for (const i of range(stride)) {
      const a = start + i;
      const b = a + stride;

      const t = buf[a];
      buf[a] = buf[b];
      buf[b] = t;
    }
    setText(buf);
  }
  return (
    <div className="exchange-puzzle-wrapper">
      <table className="exchange-puzzle">
        <tbody>
          {[16, 8, 4, 2, 1].map((stride) => (
            <tr key={stride}>
              {range(16 / stride).map((index) => {
                return (
                  <td colSpan={2 * stride} key={index}>
                    <button
                      onClick={() => handle(stride, 2 * stride * index)}
                      role="button"
                    >
                      ↔
                    </button>
                  </td>
                );
              })}
            </tr>
          ))}
          <tr>
            {text.map((c, i) => (
              <td key={i}>{c}</td>
            ))}
          </tr>
        </tbody>
      </table>
    </div>
  );
}
