import { useEffect } from "react";

export function FaviconChanger({ staticPuzDir }: { staticPuzDir: string }) {
  useEffect(() => {
    const links = document.querySelectorAll("link[rel~='icon']");
    if (links.length === 0) {
      const newLink = document.createElement("link");
      newLink.rel = "icon";
      newLink.href = `${staticPuzDir}/default.png`;
      document.getElementsByTagName("head")[0].appendChild(newLink);
      return () => {
        document.getElementsByTagName("head")[0].removeChild(newLink);
      };
    }
    const currentHrefs: string[] = [];
    for (const link of links) {
      if (!(link instanceof HTMLLinkElement))
        throw new Error("Must get a link when fetching link!");
      currentHrefs.push(link.href);
      link.href = `${staticPuzDir}/default.png`;
    }
    return () => {
      links.forEach((link, i) => {
        if (!(link instanceof HTMLLinkElement))
          throw new Error("Must get a link when fetching link!");
        link.href = currentHrefs[i];
      });
    };
  }, [staticPuzDir]);
  return <></>;
}
