import { useRef, useState } from "react";
import "./Puzzle205.css";

async function doAfterDelay(fn: () => void, delayMs: number) {
  await new Promise<void>((res) =>
    setTimeout(() => {
      fn();
      res();
    }, delayMs)
  );
}

const FLIP_TIME = 2000;
const FLIP_DELAY = 200;
const MESSAGES = [
  "Flipping",
  "Flipping.",
  "Flipping..",
  "Flipping...",
  "Flipping....",
  "Done!",
];

export function Puzzle205() {
  const [text, setText] = useState("");
  const [inProgress, setInProgress] = useState(false);

  const coinRefs = useRef<(HTMLDivElement | null)[]>([null, null, null, null]);

  const flipCoins = async () => {
    if (inProgress || coinRefs.current.some((c) => c === null)) {
      return;
    }

    setInProgress(true);
    setText(MESSAGES[0]);

    coinRefs.current.map((ref, i) => {
      if (!ref) return;
      ref.style.animation = "none";
      setTimeout(() => {
        ref.style.animation = `spin-heads ${FLIP_TIME / 1000}s`;
      }, i * FLIP_DELAY);
    });

    const totalTime = (coinRefs.current.length - 1) * FLIP_DELAY + FLIP_TIME;

    for (const message of MESSAGES.slice(1)) {
      await doAfterDelay(() => {
        setText(message);
        if (message === MESSAGES[MESSAGES.length - 1]) {
          setInProgress(false);
        }
      }, totalTime / (MESSAGES.length - 1));
    }
  };

  return (
    <>
      <div>
        <p>The answer is a nine letter word.</p>
        <button onClick={flipCoins} disabled={inProgress}>
          Flip coins!
        </button>
      </div>
      <div style={{ marginTop: "20px" }}>{text}</div>
      <div className="coins">
        {coinRefs.current.map((_, i) => (
          <div
            className="coin"
            key={i}
            ref={(ref) => {
              coinRefs.current[i] = ref;
            }}
          >
            <div className="heads">heads</div>
            <div className="tails no-copy">tails</div>
          </div>
        ))}
      </div>
    </>
  );
}
