import {
  OverlayScrollbarsComponent,
  OverlayScrollbarsComponentProps,
} from "overlayscrollbars-react";

/**
 * Horizontal scrollbar wrapper using OverlayScrollbars,
 *  mapping mousewheel vertical scroll to horizontal scroll.
 *  Pass the same options as you would an OverlayScrollbarsComponent.
 */
function HorizontalScrollbar(props: OverlayScrollbarsComponentProps) {
  const SCROLL_SMOOTHNESS = 30;

  let scrollValue = 0;
  const animateScroll = function (target: HTMLElement) {
    const currScroll = target.scrollLeft;
    let delta = (scrollValue - currScroll) / SCROLL_SMOOTHNESS;
    if (delta !== 0 && Math.abs(delta) < 1) {
      delta = delta > 0 ? 1 : -1;
    }
    const easedValue = currScroll + delta;

    // console.log(
    //   `target: ${scrollValue}, curr: ${currScroll}, delta: ${delta}, easedValue: ${easedValue}, diff: ${Math.abs(
    //     easedValue - scrollValue
    //   )}`
    // );

    if (Math.abs(easedValue - scrollValue) > 1) {
      target.scrollLeft = easedValue;
      requestAnimationFrame(() => animateScroll(target));
    } else {
      target.scrollLeft = scrollValue;
    }
  };

  const onWheel = (event: WheelEvent, target: HTMLElement) => {
    // map only vertical scrolls
    if (event.deltaY === 0 || event.deltaX !== 0) return;

    // console.log(event);

    // heuristic: trackpads have noninteger deltaY < 50
    //    (fails to detect mac trackpads)
    const isTrackpad =
      !Number.isInteger(event.deltaY) && Math.abs(event.deltaY) < 50;
    if (isTrackpad) return;

    // scrollValue += deltaY, clamp to [0, scrollLeftMax]
    scrollValue = Math.max(
      0,
      Math.min(
        scrollValue + event.deltaY,
        target.scrollWidth - target.clientWidth
      )
    );
    animateScroll(target);
    event.preventDefault();
  };

  return (
    <OverlayScrollbarsComponent
      {...props}
      events={{
        ...props.events,
        initialized: (instance) => {
          const target = instance.elements().viewport;
          target.addEventListener("wheel", (event) => onWheel(event, target));

          // pass down initialized event
          if (props.events && typeof props.events?.initialized === "function") {
            props.events.initialized(instance);
          }
        },
        destroyed: (instance, canceled) => {
          const target = instance.elements().viewport;
          target.removeEventListener("wheel", (event) =>
            onWheel(event, target)
          );

          // pass down destroyed event
          if (props.events && typeof props.events?.destroyed === "function") {
            props.events.destroyed(instance, canceled);
          }
        },
      }}
    >
      {props.children}
    </OverlayScrollbarsComponent>
  );
}

export default HorizontalScrollbar;
