import { Spinner } from "components/Loading";
import { defaultOverlayScrollbarsOptions } from "HuntLib";
import type { OverlayScrollbars } from "overlayscrollbars";
import Twemoji from "react-twemoji";
import { OLIVE_CONFIG } from "sockapi/scope-specs/team-olive-spec";
import { ScopeType } from "sockapi/scope-types";
import { Scope } from "sockapi/scopes";
import { useScopeStateResolvable } from "stores/ScopeStateStore";
import {
  useServerInteractionStore,
  useTeamId,
} from "stores/ServerInteractionStore";
import "./OlivePuzzle.css";
import HorizontalScrollbar from "components/HorizontalScrollbar";

export function OlivePuzzle() {
  const teamId = useTeamId();
  const teamOliveState = useScopeStateResolvable(
    ScopeType.TEAM_OLIVE,
    teamId === null ? null : { teamId }
  );
  const sockClient = useServerInteractionStore(
    (state) => state.getSockClient
  )();
  if (teamOliveState === null || sockClient === null || teamId === null)
    return <Spinner inline={true} />;
  const scope: Scope<ScopeType.TEAM_OLIVE> = {
    type: ScopeType.TEAM_OLIVE,
    teamId,
  };

  const { grid1, grid2, numWishes, numTotalGrid1Tokens, numTotalGrid2Tokens } =
    teamOliveState;
  const numUsedGrid1Tokens = Object.entries(grid1).filter(
    ([k, v]) => v !== null
  ).length;
  const numUsedGrid2Tokens = Object.entries(grid2).filter(
    ([k, v]) => v !== null
  ).length;
  const numGrid1Cells = OLIVE_CONFIG.grid1Length;
  const numGrid2Cells = OLIVE_CONFIG.grid2Width * OLIVE_CONFIG.grid2Height;
  const numUnusedGrid1Tokens = numTotalGrid1Tokens - numUsedGrid1Tokens;
  const numUnusedGrid2Tokens = numTotalGrid2Tokens - numUsedGrid2Tokens;

  // use mask-image css to show scrollable content fading out
  const onScrollPenlights = (instance: OverlayScrollbars) => {
    const { scrollOffsetElement: element } = instance.elements();
    if (!element) return;

    const scrollLeft = element.scrollLeft;
    const scrollWidth = element.scrollWidth;
    const clientWidth = element.clientWidth;
    const fadeWidth = clientWidth * 0.05;
    const maxScrollLeft = scrollWidth - clientWidth;

    const leftOpacity = Math.max(0, 1 - scrollLeft / fadeWidth);
    const rightOpacity = Math.max(
      0,
      1 - (maxScrollLeft - scrollLeft) / fadeWidth
    );

    // console.log(`Left opacity: ${leftOpacity}, Right opacity: ${rightOpacity}`);

    element.style.maskImage = `
      linear-gradient(
        to right,
        rgba(0, 0, 0, ${leftOpacity}),
        rgba(0, 0, 0, 1) 10%,
        rgba(0, 0, 0, 1) 90%,
        rgba(0, 0, 0, ${rightOpacity})
      )
    `;
  };

  return (
    <div className="olive">
      <p>
        you’ve found {numWishes + 1} of my wishes, which lets you discover{" "}
        {numTotalGrid1Tokens} marks and {numTotalGrid2Tokens} penlights. wishing
        might help you find more! click on a cell to permanently discover a mark
        or penlight.
      </p>
      <div>
        marks: {numUsedGrid1Tokens} of {numGrid1Cells} collected
      </div>
      {numUnusedGrid1Tokens > 0 ? (
        <div>
          you may discover {numUnusedGrid1Tokens} more
          {numUnusedGrid1Tokens === 1 ? " mark" : " marks"}.
        </div>
      ) : null}
      <div className="olive-grid-marks no-copy">
        {grid1.map((mark, idx) => (
          <div key={idx} className="olive-grid-mark">
            {mark === null ? (
              <button
                className="olive-button"
                disabled={numUnusedGrid1Tokens === 0}
                onClick={() => {
                  (async () => {
                    await sockClient.sendScopeStepAndWaitAsync(scope, {
                      revealGrid1: idx,
                    });
                  })().catch((err) => console.error(err));
                }}
              ></button>
            ) : (
              <Twemoji>{mark}</Twemoji>
            )}
          </div>
        ))}
      </div>
      <table className="olive-grid-marks-table copy-only">
        <tbody>
          <tr>
            {grid1.map((mark, idx) => (
              <td key={idx}>{mark === null ? "?" : mark}</td>
            ))}
          </tr>
        </tbody>
      </table>
      <div>
        penlights: {numUsedGrid2Tokens} of {numGrid2Cells} collected
      </div>
      {numUnusedGrid2Tokens > 0 ? (
        <div>
          you may discover {numUnusedGrid2Tokens} more
          {numUnusedGrid2Tokens === 1 ? " penlight" : " penlights"}.
        </div>
      ) : null}
      <div className="olive-grid-penlights">
        <HorizontalScrollbar
          options={defaultOverlayScrollbarsOptions}
          events={{
            initialized: onScrollPenlights,
            scroll: onScrollPenlights,
          }}
          style={{
            paddingBottom: "1rem",
          }}
          defer
        >
          <table className="olive-grid-penlights-table">
            <tbody>
              {Array.from({ length: OLIVE_CONFIG.grid2Height }).map(
                (_, row) => (
                  <tr key={row}>
                    {Array.from({ length: OLIVE_CONFIG.grid2Width }).map(
                      (_, col) => {
                        const idx = row * OLIVE_CONFIG.grid2Width + col;
                        const penlight = grid2[idx];
                        return (
                          <td key={col}>
                            {penlight === null ? (
                              <button
                                className="olive-button"
                                disabled={numUnusedGrid2Tokens === 0}
                                onClick={() => {
                                  (async () => {
                                    await sockClient.sendScopeStepAndWaitAsync(
                                      scope,
                                      {
                                        revealGrid2: idx,
                                      }
                                    );
                                  })().catch((err) => console.error(err));
                                }}
                              >
                                <span className="copy-only">?</span>
                              </button>
                            ) : (
                              penlight
                            )}
                          </td>
                        );
                      }
                    )}
                  </tr>
                )
              )}
            </tbody>
          </table>
        </HorizontalScrollbar>
      </div>
    </div>
  );
}
