import { useRef } from "react";

import FallingStar4 from "images/wish/falling-star-4.webm";
import FallingStar5 from "images/wish/falling-star-5.webm";
import FallingStar6 from "images/wish/falling-star-6.webm";
import FallingStar7 from "images/wish/falling-star-7.webm";
import FallingStar8 from "images/wish/falling-star-8.webm";
import FallingStick from "images/wish/falling-stick.webm";
import FallingBlocks from "images/wish/falling-blocks.webm";
import FallingCan from "images/wish/falling-can.webm";
import FallingJackpot from "images/wish/falling-jackpot.webm";
import FallingCelestial from "images/wish/falling-celestial.webm";
import FallingCollectible from "images/wish/falling-collectible.webm";
import FallingHint from "images/wish/falling-hint.webm";

import { GachaPrizeType, GachaPull, Rarity } from "sockapi/gacha/pulls";
import { useTeamScopeState } from "stores/ScopeStateStore";
import { Spinner } from "components/Loading";

function WishAnimation(props: {
  teamId: string;
  pull: GachaPull;
  onJustBeforeEnd?: () => void;
}) {
  // TODO: maybe want to make sure the video replays from start, in case the component never unloaded (can this happen?)

  const { teamId, pull, onJustBeforeEnd } = props;
  const teamScopeState = useTeamScopeState(teamId);
  const videoElem = useRef<HTMLVideoElement>(null);

  if (teamScopeState === null) return <Spinner inline={true} />;
  const { puzzles } = teamScopeState;

  const videoSrc = (() => {
    switch (pull.type) {
      case GachaPrizeType.UNLOCK: {
        const puzData = puzzles[pull.puzName];
        if (puzData === undefined) return null;
        const {
          rarity = Rarity.COMMON,
          isCelestial = false,
          isFindCelestial = false,
        } = puzData;

        if (isCelestial || isFindCelestial) {
          return FallingCelestial;
        }

        switch (rarity) {
          case Rarity.COMMON:
            return FallingStar4;
          case Rarity.UNCOMMON:
            return FallingStar5;
          case Rarity.RARE:
            return FallingStar6;
          case Rarity.EPIC:
            return FallingStar7;
          case Rarity.LEGENDARY:
            return FallingStar8;
          default:
            return FallingStar4;
        }
      }
      case GachaPrizeType.BLOCKS:
        return FallingBlocks;
      case GachaPrizeType.OLIVE:
        return FallingStick;
      case GachaPrizeType.COLLECTIBLE:
        return FallingCollectible;
      case GachaPrizeType.JACKPOT:
        return FallingJackpot;
      case GachaPrizeType.CANNED_HINT:
        return FallingCan;
      case GachaPrizeType.HINT_TOKEN:
        return FallingHint;
      default:
        return FallingCollectible;
    }
  })();

  if (videoSrc === null) return <Spinner inline />;

  return (
    <video
      ref={videoElem}
      autoPlay
      muted
      playsInline
      src={videoSrc}
      onTimeUpdate={() => {
        if (videoElem.current === null) return;
        if (videoElem.current.duration - videoElem.current.currentTime < 0.3)
          onJustBeforeEnd?.();
      }}
      onEnded={onJustBeforeEnd}
    />
  );
}

export default WishAnimation;
