function TeamCustomPuzzleDisplay(props: { teamId: string }) {
  const { teamId } = props;
  const ownTeamId = useTeamId();
  const customPuzzlePuzName = `${PUZZLE_105_CONFIG.customPuzzlePuzNamePrefix}${teamId}`;
  const puzzles = useAccessiblePuzzles();

  if (puzzles === null || ownTeamId === null) return <Spinner inline />;
  if (puzzles[customPuzzlePuzName] === undefined) return null;

  return (
    <div className="team-page-free-puzzle">
      <img src="/static/images/cutscenes/moonick.png" />
      <div>
        <p>
          {teamId === ownTeamId ? "Your" : <>This team&rsquo;s</>} Free Puzzle
          is public!
        </p>
        <PuzzleLink button puzName={customPuzzlePuzName}>
          Go to puzzle
        </PuzzleLink>
      </div>
    </div>
  );
}

function TeamDownloadStateDisplay(props: { teamId: string }) {
  const { teamId } = props;
  const downloadLock = useUILock();
  const sockClient = useSockClient();

  return (
    <div className="download-state">
      <img src="/static/images/cutscenes/stelle.png" />
      <div>
        <p>
          Download your team’s state to continue working on the hunt after the
          hunt has closed!
        </p>
        <button
          onClick={() => {
            downloadLock.acquireAndRun(async (getIsCanceled) => {
              await downloadTeamStateAsync(sockClient, teamId, getIsCanceled);
            });
          }}
          disabled={downloadLock.isHeld}
        >
          Download state
        </button>
      </div>
    </div>
  );
}

function TeamCollectiblesDisplay(props: { teamId: string }) {
  const { teamId } = props;
  const ownTeamId = useTeamId();
  const huntEndTime = useTeamScopeState()?.huntEndTime ?? null;
  const teamCollectiblesScopeStateResult = useScopeStateResolvablePosthuntable(
    ScopeType.TEAM_COLLECTIBLES,
    ownTeamId === null ? null : { teamId },
    { hasPosthunt: teamId !== ownTeamId }
  );
  const isPullInProgress = useIsPullInProgress();
  const [sortedCollectibles, setSortedCollectibles] = useState<
    SockAPITeamCollectibleState[] | null
  >(null);

  const teamCollectiblesScopeState =
    teamCollectiblesScopeStateResult === null
      ? null
      : !teamCollectiblesScopeStateResult.success
      ? null
      : teamCollectiblesScopeStateResult.state;
  useEffect(() => {
    if (isPullInProgress) return;
    if (teamCollectiblesScopeState === null) return;
    if (ownTeamId === null) return;
    if (huntEndTime === null) return;
    setSortedCollectibles(
      Object.values(teamCollectiblesScopeState.collectibles)
        .filter(
          (collectible) =>
            ownTeamId === teamId || collectible.timestamp < huntEndTime
        )
        .sort((collectible1, collectible2) => {
          // Sort larger quantities first.
          const num1 = collectible1.num;
          const num2 = collectible2.num;
          const diffNum = num2 - num1;
          if (diffNum !== 0) return diffNum;

          const name1 = collectible1.name;
          const name2 = collectible2.name;
          return name1.localeCompare(name2);
        })
    );
  }, [
    ownTeamId,
    teamId,
    teamCollectiblesScopeState,
    isPullInProgress,
    huntEndTime,
  ]);

  if (teamCollectiblesScopeStateResult === null) return <Spinner inline />;
  if (!teamCollectiblesScopeStateResult.success)
    return <DownloadFailedDisplay {...teamCollectiblesScopeStateResult} />;
  if (sortedCollectibles === null) return <Spinner inline={true} />;
  if (sortedCollectibles.length === 0) return null;

  return (
    <div>
      <h3>Artifacts</h3>
      <div className="team-collectibles">
        {sortedCollectibles.map(({ name, icon, num }) => (
          <div key={name} className="team-collectible">
            <Twemoji
              className="team-collectible-icon"
              options={{ folder: "svg", ext: ".svg" }}
            >
              {icon}
            </Twemoji>
            <div className="team-collectible-desc">
              {num === 1 ? "" : `${num} `}
              {capitalize(name)}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function GachaList(props: { teamId: string; sortedPulls: GachaPull[] }) {
  const { teamId } = props;
  const teamScopeState = useTeamScopeState(teamId);
  const teamCollectiblesScopeState = useScopeStateResolvable(
    ScopeType.TEAM_COLLECTIBLES,
    teamId === null ? null : { teamId }
  );
  const displayNames = usePuzzleDisplayNames();

  function prizeKey(prize: GachaPull) {
    switch (prize.type) {
      case GachaPrizeType.UNLOCK: {
        if (teamScopeState === null) return "star";
        const puzData = teamScopeState.puzzles[prize.puzName];
        if (puzData === undefined) return "star";
        const { rarity = Rarity.COMMON, isFindCelestial = false } = puzData;
        if (isFindCelestial) return "star 0";
        if (!isPuzzleMicropuzzle(puzData)) return "star";
        return `star ${Object.values(Rarity).indexOf(rarity) + 2}`;
      }
      case GachaPrizeType.JACKPOT:
        return `hope ${prize.amount}`;
      case GachaPrizeType.COLLECTIBLE: {
        if (teamCollectiblesScopeState === null) return "artifact";
        const collectibleData =
          teamCollectiblesScopeState.collectibles[prize.collectibleId];
        return `artifact ${prize.num} ${collectibleData?.name ?? ""}`;
      }
      case GachaPrizeType.OLIVE:
      case GachaPrizeType.BLOCKS:
        return "something useful";
      default:
        return prize.type;
    }
  }

  function prizeSummary(prize: GachaPull) {
    switch (prize.type) {
      case GachaPrizeType.UNLOCK: {
        if (teamScopeState === null) return null;
        const puzData = teamScopeState.puzzles[prize.puzName];
        if (puzData === undefined) return null;
        const { rarity = Rarity.COMMON, isFindCelestial = false } = puzData;
        if (isFindCelestial) return " celestial";
        if (!isPuzzleMicropuzzle(puzData)) return " star";
        return (
          <>
            {" "}
            <span
              style={{
                color: "#ffac33",
                filter: `hue-rotate(${starHue[rarity]}deg)`,
              }}
            >
              {rarity}
            </span>{" "}
            star
          </>
        );
      }
      case GachaPrizeType.CANNED_HINT:
        return " canned hint";
      case GachaPrizeType.HINT_TOKEN:
        return " hint token";
      case GachaPrizeType.JACKPOT:
        return ` ${prize.amount} hope`;
      case GachaPrizeType.COLLECTIBLE: {
        if (teamCollectiblesScopeState === null) return null;
        const collectibleData =
          teamCollectiblesScopeState.collectibles[prize.collectibleId];
        if (collectibleData === undefined) return null;
        return ` ${
          prize.num === 1
            ? collectibleData.nounPrefix !== ""
              ? `${collectibleData.nounPrefix} `
              : ""
            : `${prize.num} `
        } ${collectibleData.name}`;
      }
      case GachaPrizeType.OLIVE:
      case GachaPrizeType.BLOCKS:
        return " something useful";
    }
  }

  function prizeLink(prize: GachaPull) {
    let puzName: string;
    let subpage: "puzzle" | "hints";
    switch (prize.type) {
      case GachaPrizeType.UNLOCK:
        puzName = prize.puzName;
        subpage = "puzzle";
        break;
      case GachaPrizeType.CANNED_HINT:
        puzName = prize.puzName;
        subpage = "hints";
        break;
      case GachaPrizeType.HINT_TOKEN:
      case GachaPrizeType.JACKPOT:
      case GachaPrizeType.COLLECTIBLE:
        return { text: "", html: "—" };
      case GachaPrizeType.OLIVE:
        puzName = OLIVE_CONFIG.puzName;
        subpage = "puzzle";
        break;
      case GachaPrizeType.BLOCKS:
        puzName = BLOCKS_CONFIG.puzName;
        subpage = "puzzle";
        break;
    }
    if (displayNames === null) return { text: "", html: null };
    const name = displayNames[puzName] ?? "???";
    return {
      text: name,
      html: (
        <PuzzleLink puzName={puzName} subpage={subpage} title={name}>
          {name}
        </PuzzleLink>
      ),
    };
  }

  const sortedPulls = props.sortedPulls.map((pull) => ({
    ...pull,
    teamId,
    key: prizeKey(pull),
    summary: prizeSummary(pull),
    ...prizeLink(pull),
  }));

  return (
    <SortableTable
      spec={{
        columns: [
          {
            label: "Wishes",
            sortFunc: (a, b) => displayNameOrder(a.key, b.key),
            width: "20%",
            isTitle: true,
          },
          {
            label: "Puzzle",
            sortFunc: (a, b) => displayNameOrder(a.text, b.text),
            width: "60%",
          },
          {
            label: "Time",
            sortFunc: (a, b) => a.timestamp - b.timestamp,
            width: "20%",
          },
        ],
        renderRow: (prize, i) => (
          <tr key={i}>
            <td>
              <PrizeIcon teamId={prize.teamId} prize={prize} />
              {prize.summary}
            </td>
            <td>{prize.html}</td>
            <td>
              <ShortDate timestamp={prize.timestamp} />
            </td>
          </tr>
        ),
        pageSize: 20,
      }}
      records={sortedPulls}
      className="list-table team-wishes-table"
    />
  );
}

function GachaHistory(props: { teamId: string }) {
  const { teamId } = props;
  const sockClient = useSockClient();
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const teamGachaScopeState = useTeamGachaScopeState(teamId);
  const isPullInProgress = useIsPullInProgress();
  const [sortedPulls, setSortedPulls] = useState<GachaPull[] | null>(null);

  useEffect(() => {
    if (isPullInProgress) return;
    if (teamGachaScopeState === null) return;
    setSortedPulls(
      Object.values(teamGachaScopeState.pulls).sort(
        (a, b) => b.timestamp - a.timestamp
      )
    );
  }, [teamGachaScopeState, isPullInProgress]);

  if (teamId === null || sortedPulls === null) return <Spinner inline={true} />;

  const iconSummary = sortedPulls.map((pull) => (
    <PrizeIcon key={pull.timestamp} teamId={teamId} prize={pull} />
  ));

  return (
    <>
      {sortedPulls.length > 0 ? (
        <GachaList teamId={teamId} sortedPulls={sortedPulls} />
      ) : null}
      {shouldDisplayAdmin ? (
        <div>
          <h4>Wish history (admin only)</h4>
          <div>{iconSummary}</div>
          <button
            onClick={() => {
              sockClient.sendScopeStep(
                {
                  type: ScopeType.TEAM_GACHA,
                  teamId,
                },
                {
                  ignoreHopeLimit: true,
                  numPulls: 100,
                }
              );
            }}
          >
            Wish ×100 (admin only)
          </button>
        </div>
      ) : null}
    </>
  );
}

function HintsList(props: { teamId: string }) {
  const { teamId } = props;
  const teamScopeState = useTeamScopeState(teamId);
  const teamHintsScopeState = useScopeStateResolvable(ScopeType.TEAM_HINTS, {
    teamId,
  });
  const hintIds = teamHintsScopeState?.hints
    ? Object.values(teamHintsScopeState.hints)
        .map((hints) => Object.keys(hints))
        .flat()
        .map((hintId) => ({ hintId }))
    : null;
  const hints = useScopeStateArrayResolvable(ScopeType.HINT, hintIds);
  const displayNames = usePuzzleDisplayNames();

  if (
    teamScopeState === null ||
    hintIds === null ||
    hints === null ||
    displayNames === null
  )
    return <Spinner inline={true} />;
  const { puzzles } = teamScopeState;

  const sortedHints = hints
    .filter(({ puzName }) => puzzles[puzName] !== undefined)
    .map(({ puzName, request, response }, i) => ({
      ...puzzles[puzName],
      ...hintIds[i],
      name: displayNames[puzName] ?? "???",
      reqTime: request.timestamp,
      resTime: response?.timestamp ?? Infinity,
      status: response?.type ?? "pending",
    }))
    .sort((a, b) => b.reqTime - a.reqTime);

  return (
    <SortableTable
      spec={{
        columns: [
          {
            label: "Hints",
            sortFunc: (a, b) => displayNameOrder(a.name, b.name),
            width: "50%",
            isTitle: true,
          },
          {
            label: "Request time",
            sortFunc: (a, b) => a.reqTime - b.reqTime,
            width: "20%",
          },
          {
            label: "Status",
            sortFunc: (a, b) => a.status.localeCompare(b.status),
            width: "10%",
          },
          {
            label: "Response time",
            sortFunc: (a, b) => a.resTime - b.resTime,
            width: "20%",
          },
        ],
        renderRow: (puzData, i) => {
          const { puzName, name, reqTime, resTime, status } = puzData;
          return (
            <tr key={i}>
              <td>
                <PuzzleIcon puzData={puzData} />{" "}
                <PuzzleLink puzName={puzName} subpage="hints" title={name}>
                  {name}
                </PuzzleLink>
              </td>
              <td>
                <ShortDate timestamp={reqTime} />
              </td>
              <td>{status}</td>
              <td>
                {isFinite(resTime) ? <ShortDate timestamp={resTime} /> : "—"}
              </td>
            </tr>
          );
        },
        pageSize: 20,
      }}
      records={sortedHints}
      className="list-table team-solves-table"
    />
  );
}

function SequencesProgressDisplay(props: { teamId: string }) {
  const { teamId } = props;
  const huntAdminScopeState = useGlobalScopeState(ScopeType.HUNT_ADMIN);
  const teamScopeState = useTeamScopeState(teamId);

  if (huntAdminScopeState === null || teamScopeState === null)
    return <Spinner inline={true} />;
  const teamPuzzles = teamScopeState.puzzles;

  const { puzzles } = huntAdminScopeState;
  const sequencesInfo: {
    [sequenceId: string]: {
      len: number;
      numSolved: number;
      numUnlocked: number;
      lastSolveTime: number;
    };
  } = {};
  for (const { puzName, sequenceId } of Object.values(puzzles)) {
    if (sequenceId === undefined) continue;
    sequencesInfo[sequenceId] ??= {
      len: 0,
      numSolved: 0,
      numUnlocked: 0,
      lastSolveTime: 0,
    };
    const sequenceInfo = sequencesInfo[sequenceId];
    sequenceInfo.len++;

    const teamPuzzle = teamPuzzles[puzName];
    if (teamPuzzle !== undefined) {
      const { solveTime } = teamPuzzle;
      sequenceInfo.numUnlocked++;
      if (solveTime !== undefined) {
        sequenceInfo.lastSolveTime = Math.max(
          solveTime,
          sequenceInfo.lastSolveTime
        );
        sequenceInfo.numSolved++;
      }
    }
  }
  return (
    <div>
      <h4>Sequences progress (admin only)</h4>
      {Object.entries(sequencesInfo).map(([sequenceId, sequenceInfo]) => (
        <div key={sequenceId}>
          {sequenceId}: {sequenceInfo.numSolved}s/{sequenceInfo.numUnlocked}u/
          {sequenceInfo.len}
          {sequenceInfo.numSolved === sequenceInfo.len ? (
            <>
              , completed <ShortDate timestamp={sequenceInfo.lastSolveTime} />
            </>
          ) : null}
        </div>
      ))}
    </div>
  );
}

function SolvesList(props: { teamId: string }) {
  const { teamId } = props;
  const ownTeamId = useTeamId();
  const huntEndTime = useTeamScopeState()?.huntEndTime ?? null;
  const teamScopeStateResult = useTeamScopeStatePosthuntable(
    ownTeamId === null ? null : teamId,
    { hasPosthunt: teamId !== ownTeamId }
  );
  const displayNames = usePuzzleDisplayNames();
  const shouldDisplayAdmin = useShouldDisplayAdmin();

  if (
    teamScopeStateResult === null ||
    displayNames === null ||
    ownTeamId === null ||
    huntEndTime === null
  )
    return <Spinner inline={true} />;
  if (!teamScopeStateResult.success)
    return <DownloadFailedDisplay {...teamScopeStateResult} />;
  const { puzzles } = teamScopeStateResult.state;

  const sortedSolves = Object.entries(puzzles)
    .filter(
      ([puzName, { isStory = false, solveTime }]) =>
        !isStory &&
        solveTime !== undefined &&
        (ownTeamId === teamId || solveTime < huntEndTime)
    )
    .map(([puzName, puzData]) => ({
      ...puzData,
      puzName,
      solveTime: puzData.solveTime ?? 0,
      name: displayNames[puzName] ?? "???",
    }))
    .sort((a, b) => b.solveTime - a.solveTime);

  return (
    <>
      {shouldDisplayAdmin ? (
        <div>
          <h4>Open puzzles (admin only)</h4>
          {Object.values(puzzles)
            .sort((a, b) => b.unlockTime - a.unlockTime)
            .map((puzData) => {
              const { puzName, unlockTime, solveTime } = puzData;
              if (solveTime !== undefined) return null;
              const name = displayNames[puzName] ?? "???";
              return (
                <div key={puzName}>
                  <PuzzleIcon puzData={puzData} />{" "}
                  <PuzzleLink puzName={puzName}>{name}</PuzzleLink>{" "}
                  <ShortDate timestamp={unlockTime} />
                </div>
              );
            })}
        </div>
      ) : null}
      <SortableTable
        spec={{
          columns: [
            {
              label: "Solves",
              sortFunc: (a, b) => displayNameOrder(a.name, b.name),
              width: "50%",
              isTitle: true,
            },
            {
              label: "Unlock time",
              sortFunc: (a, b) => a.unlockTime - b.unlockTime,
              width: "20%",
            },
            {
              label: "→",
              sortFunc: (a, b) =>
                a.solveTime - a.unlockTime - (b.solveTime - b.unlockTime),
              width: "10%",
            },
            {
              label: "Solve time",
              sortFunc: (a, b) => a.solveTime - b.solveTime,
              width: "20%",
            },
          ],
          renderRow: (puzData, i) => {
            const { puzName, name, unlockTime, solveTime } = puzData;
            const subpage = doesSolutionExist(puzData) ? "solution" : "puzzle";
            return (
              <tr key={i}>
                <td>
                  <PuzzleIcon puzData={puzData} />{" "}
                  <PuzzleLink puzName={puzName} subpage={subpage} title={name}>
                    {name}
                  </PuzzleLink>
                </td>
                <td>
                  <ShortDate timestamp={unlockTime} />
                </td>
                <td>
                  <Duration from={unlockTime} to={solveTime} />
                </td>
                <td>
                  <ShortDate timestamp={solveTime} />
                </td>
              </tr>
            );
          },
          pageSize: 20,
        }}
        records={sortedSolves}
        className="list-table team-solves-table"
      />
      {shouldDisplayAdmin ? <SequencesProgressDisplay teamId={teamId} /> : null}
    </>
  );
}

function HopeGraph(props: { teamId: string }) {
  const { teamId } = props;
  const ownTeamId = useTeamId();
  const huntEndTime = useTeamScopeState()?.huntEndTime ?? null;
  const teamScopeStateResult = useTeamScopeStatePosthuntable(
    ownTeamId === null ? null : teamId,
    { hasPosthunt: teamId !== ownTeamId }
  );
  const teamHistoryResult = useScopeStateResolvablePosthuntable(
    ScopeType.TEAM_HISTORY,
    ownTeamId === null ? null : { teamId },
    { hasPosthunt: teamId !== ownTeamId }
  );
  const displayNames = usePuzzleDisplayNames();

  if (
    huntEndTime === null ||
    teamScopeStateResult === null ||
    teamHistoryResult === null ||
    displayNames === null
  )
    return <Spinner inline={true} />;
  if (!teamHistoryResult.success)
    return <DownloadFailedDisplay {...teamHistoryResult} />;
  if (!teamScopeStateResult.success)
    return <DownloadFailedDisplay {...teamScopeStateResult} />;
  const isOwnTeam = ownTeamId === teamId;
  const fullTeamHistory = teamHistoryResult.state;
  const teamHistory = fullTeamHistory.filter(
    ({ timestamp }) => isOwnTeam || timestamp < huntEndTime
  );
  const teamScopeState = teamScopeStateResult.state;
  if (teamHistory.length <= 1) return null;

  const start = teamHistory[0].timestamp;
  const end = teamHistory[teamHistory.length - 1].timestamp;
  const max = Math.max(
    hopeBounds.upper,
    ...teamHistory.map(({ hope }) => hope)
  );
  const coords = (hope: number, timestamp: number) => ({
    x: (99 * (timestamp - start)) / (end - start) + 0.5,
    y: 93 * (1 - hope / max) + 1,
  });
  const segment = (type: string, hope: number, timestamp: number) => {
    const { x, y } = coords(hope, timestamp);
    return `${type} ${x.toFixed(2)} ${y.toFixed(1)}`;
  };
  const path = teamHistory
    .flatMap(({ hope, timestamp }, i) => {
      if (i === 0) return segment("M", hope, timestamp);
      const endSegment = segment("L", hope, timestamp);
      const prev = teamHistory[i - 1];
      if (prev.hope >= hopeBounds.upper)
        return [segment("L", prev.hope, timestamp), endSegment];
      const uncappedHope =
        prev.hope + (hopeGainPerSecond * (timestamp - prev.timestamp)) / 1000;
      if (uncappedHope <= hopeBounds.upper)
        return [segment("L", uncappedHope, timestamp), endSegment];
      const capTime =
        ((hopeBounds.upper - prev.hope) * 1000) / hopeGainPerSecond +
        prev.timestamp;
      return [
        segment("L", hopeBounds.upper, capTime),
        segment("L", hopeBounds.upper, timestamp),
        endSegment,
      ];
    })
    .filter((elt, i, arr) => elt !== arr[i + 1])
    .join(" ");
  const nodes = Object.values(teamScopeState.puzzles).map(
    ({ puzName, solveTime }) => {
      if (solveTime === undefined) return null;
      if (!isOwnTeam && solveTime >= huntEndTime) return null;
      const name = displayNames[puzName] ?? "???";
      let prev = null;
      for (const snapshot of teamHistory)
        if (snapshot.timestamp <= solveTime) prev = snapshot;
      const hope = actualHope(prev, solveTime);
      const { x, y } = coords(hope, solveTime);
      return (
        <Tooltip
          key={puzName}
          className="node"
          text={`${Math.floor(hope)}: solved ${name}`}
          style={{ left: `${x}%`, top: `${y}%` }}
        />
      );
    }
  );
  const ticks = [];
  const day = new Date(new Date(start).toDateString());
  for (let i = 0; i < 100; ++i) {
    day.setDate(day.getDate() + 1);
    if (+day > end) break;
    const { x } = coords(0, +day);
    ticks.push(<path key={x} className="tick" d={`M ${x} 95 L ${x} 100`} />);
  }
  return (
    <div className="history-graph">
      <h3>Hope</h3>
      <div className="grid">
        <svg viewBox="0 0 100 100" preserveAspectRatio="none">
          {ticks}
          <path d={path} />
        </svg>
        {nodes}
      </div>
      <div className="axis">
        <ShortDate timestamp={start} />
        <ShortDate timestamp={end} />
      </div>
    </div>
  );
}

function TeamPageBody() {
  const teams = useGlobalScopeState(ScopeType.TEAM_LIST);
  const posthuntTeamsResult = useGlobalScopeStatePosthuntable(
    ScopeType.TEAM_LIST,
    true,
    { hasPosthunt: true }
  );
  const posthuntTeams =
    posthuntTeamsResult === null || !posthuntTeamsResult.success
      ? null
      : posthuntTeamsResult.state;
  const { teamName: teamNameEncoded } = useParams();
  const resolvedTeam =
    posthuntTeams === null || teams === null || teamNameEncoded === undefined
      ? null
      : Object.values(posthuntTeams).find(
          (team) => team.displayName == decodeURIComponent(teamNameEncoded)
        ) ??
        Object.values(teams).find(
          (team) => team.displayName == decodeURIComponent(teamNameEncoded)
        ) ??
        null;

  const teamId = resolvedTeam?.teamId ?? null;
  const team =
    teamId === null ? null : teams?.[teamId] ?? posthuntTeams?.[teamId] ?? null;
  const ownTeamId = useTeamId();
  const teamMembersScopeStateResult = useTeamMembersScopeStatePosthuntable(
    ownTeamId === null ? null : teamId,
    { hasPosthunt: teamId !== ownTeamId }
  );
  const areTeamsLoaded = posthuntTeams !== null && teams !== null;
  const shouldDisplayAdmin = useShouldDisplayAdmin();
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);
  const isSameTeamOrAdmin =
    shouldDisplayAdmin ||
    (teamId !== null && ownTeamId !== null && ownTeamId === teamId);
  const isHuntOver = useIsHuntOver();
  const sockClient = useSockClient();

  if (teamNameEncoded === undefined) throw new Error("expect team name in url");

  useEffect(() => {
    if (!areTeamsLoaded) return;
    if (team !== null) {
      const canonicalPath = makeTeamPagePath(team.displayName);
      if (location.pathname !== canonicalPath)
        setRedirectCommand({ path: canonicalPath, replace: true });
      return;
    }

    return addFlushSockAPIMessagesEffect(sockClient, () => {
      Globals.toastr.error(
        `Team “${decodeURIComponent(teamNameEncoded)}” not found.`
      );
      setRedirectCommand({ path: "/teams" });
    });
  }, [areTeamsLoaded, team, teamNameEncoded, setRedirectCommand, sockClient]);

  if (posthuntTeamsResult !== null && !posthuntTeamsResult.success)
    return <DownloadFailedDisplay {...posthuntTeamsResult} />;
  if (!areTeamsLoaded || team === null || teamId === null)
    return <LargeSpinner />;

  return (
    <div className="centered-page team-page">
      <h1>
        <TeamDisplayNameDisplayPreloaded teamData={team} noLink={true} />
        {!settings.isPosthunt && isSameTeamOrAdmin ? (
          <div className="button-squish-zone">
            <DjangoLink href="edit-team" button={true}>
              Edit team members
            </DjangoLink>
            <DjangoLink href="password-change" button={true}>
              Change password
            </DjangoLink>
          </div>
        ) : null}
      </h1>
      {teamMembersScopeStateResult === null ? (
        <Spinner inline={true} />
      ) : !teamMembersScopeStateResult.success ? (
        <DownloadFailedDisplay {...teamMembersScopeStateResult} />
      ) : (
        teamMembersScopeStateResult.state.members?.join(", ")
      )}
      {shouldDisplayAdmin || (isHuntOver && isSameTeamOrAdmin) ? (
        <TeamDownloadStateDisplay teamId={teamId} />
      ) : null}
      {settings.isPosthunt || isSameTeamOrAdmin ? (
        <TeamCustomPuzzleDisplay teamId={teamId} />
      ) : null}
      <TeamCollectiblesDisplay teamId={teamId} />
      {isSameTeamOrAdmin ? <GachaHistory teamId={teamId} /> : null}
      {isSameTeamOrAdmin ? <HintsList teamId={teamId} /> : null}
      {isSameTeamOrAdmin || isHuntOver ? <SolvesList teamId={teamId} /> : null}
      {isSameTeamOrAdmin || isHuntOver ? <HopeGraph teamId={teamId} /> : null}
    </div>
  );
}

function TeamPage() {
  return (
    <PuzzlePageWrapper>
      <TeamPageBody />
    </PuzzlePageWrapper>
  );
}

export default TeamPage;
