import Twemoji from "react-twemoji";
import { spellOutNumber } from "util/util";
import GachaButton from "components/Gacha/GachaButton";
import { RoutedLink } from "components/Link";
import { clsObj } from "client-util";
import { hopeBounds, formatHope } from "sockapi/gacha/hope";
import { PULL_COST } from "sockapi/gacha/pulls";
import { useCurrentHope } from "stores/ScopeStateStore";
import { useInPuzzlePage, useCampLayout } from "stores/NavStore";
import Tooltip from "components/Tooltip";
import { Spinner } from "components/Loading";
import "overlayscrollbars/overlayscrollbars.css";

import "./HopeMeter.css";

function minifiableLink(
  path: string,
  text: string,
  emoji: string,
  active: boolean
) {
  const button = (
    <div className="minifiable-link">
      <span className="minifiable-link-text">{text}</span>
      <Twemoji tag="span" className="minifiable-link-icon">
        {emoji}
      </Twemoji>
    </div>
  );
  return active ? (
    <RoutedLink path={path} className="hope-meter-link">
      {button}
    </RoutedLink>
  ) : (
    button
  );
}

function HopeMeter() {
  const { inPuzzlePage, inCamp } = useInPuzzlePage();
  const campLayout = useCampLayout();

  const currentHope = useCurrentHope() ?? 0;
  const maxHope = hopeBounds.upper;
  const fractionOfPull = currentHope / PULL_COST;
  const percentOfMax = Math.max(
    Math.min((100 * currentHope) / maxHope, 100),
    0
  );
  const canPull = fractionOfPull >= 1;
  const numWishesAvailable = Math.floor(fractionOfPull);

  if (campLayout === null) return <Spinner inline={true} />;
  const { isBeforeFirstWish } = campLayout;

  return (
    <>
      {!isBeforeFirstWish ? (
        <>
          {minifiableLink("/lastpuzzle", "Puzzles", "📝️", !inPuzzlePage)}
          {minifiableLink("/camp", "Camp", "🏕️", !inCamp)}
        </>
      ) : null}
      <Tooltip
        className={clsObj({ "hope-meter": true, "can-pull": canPull })}
        text={`You have ${formatHope(currentHope)} hope${
          canPull
            ? `, enough for ${spellOutNumber(numWishesAvailable)} ${
                numWishesAvailable === 1 ? "wish" : "wishes"
              }.`
            : ". You need 100 to wish."
        }`}
        style={{
          backgroundSize: `${percentOfMax}%`,
          maskSize: `${(100 * PULL_COST) / hopeBounds.upper}%`,
        }}
      >
        {canPull ? "Ready!" : formatHope(currentHope)}
      </Tooltip>
      <GachaButton />
    </>
  );
}

export default HopeMeter;
