import { useEffect, useRef } from "react";
import "./Puzzle207.css";

// holy jank, we inject into the iframe
interface GameWindow extends Window {
  updatePresses: (event: PointerEvent, pressed: number) => void;
}

export function Puzzle207({ staticPuzDir }: { staticPuzDir: string }) {
  const gameRef = useRef<HTMLIFrameElement>(null);

  // resize the iframe to be 2:1
  const onResize = () => {
    const iframe = gameRef.current;
    if (iframe === null) return;

    const width = iframe.clientWidth;
    iframe.style.height = `${width / 2}px`;
  };

  // inject non-mouse pointer events into the iframe to prevent mobile cheese
  const onPointerDown = (event: PointerEvent) => {
    if (event.pointerType === "mouse") return;

    const iframe = gameRef.current;
    if (iframe === null) return;

    const updatePresses = (iframe.contentWindow as GameWindow | null)
      ?.updatePresses;
    if (updatePresses === undefined) return;

    updatePresses(event, 1);
    // // release pointer capture
    // document.releasePointerCapture(event.pointerId);
  };

  const onPointerUp = (event: PointerEvent) => {
    if (event.pointerType === "mouse") return;

    const iframe = gameRef.current;
    if (iframe === null) return;

    const updatePresses = (iframe.contentWindow as GameWindow | null)
      ?.updatePresses;
    if (updatePresses === undefined) return;

    return updatePresses(event, 0);
  };

  useEffect(() => {
    window.addEventListener("resize", onResize);
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("pointerup", onPointerUp);

    onResize();
    return () => {
      window.removeEventListener("resize", onResize);
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("pointerup", onPointerUp);
    };
  }, []);

  return (
    <iframe
      id="get-home-game"
      ref={gameRef}
      src={`${staticPuzDir}/default/get-home.html`}
    ></iframe>
  );
}
