export const usePuzzleBodyDependencies = (
  puzData: TeamPuzzleSockAPIScopeState
): {
  teamId: string;
  /** Null only if the puzzle is not an answerable. */
  teamAnswerableScopeState: SockAPIScopeState<ScopeType.TEAM_ANSWERABLE> | null;
  errataContent: {
    erratumId: string;
    content: SockAPIScopeState<ScopeType.ERRATUM_CONTENT>;
  }[];
  renderCtx: PuzzleContentRenderContext;
  puzzlesInSequence: PuzzleMetadata[] | null;
  celestialsAsSequence: TeamPuzzleSockAPIScopeState[];
  isPuzzleUnlocked: boolean;
  isPuzzleSolved: boolean;
  cutsceneState: CutsceneState;
} | null => {
  const { puzName, hasAnswer = false, sequenceId } = puzData;
  const teamId = useTeamId();
  const teamScopeState = useTeamScopeState();
  // Only subscribe to answerable scope state if the puzzle
  // is an answerable.
  const teamAnswerableScopeState = useTeamAnswerableScopeState(
    teamId,
    hasAnswer ? puzName : null
  );
  const errataContent = useErrataContentForPuzzle(puzName, true);
  const { renderCtx } = usePuzzleContent(puzName, PuzzleContentType.PUZZLE);
  const puzzlesInSequence = usePuzzlesInSequence(sequenceId ?? null);
  const celestialsAsSequence = useCelestialsAsSequence();
  const isPuzzleUnlocked =
    teamScopeState !== null
      ? teamScopeState.puzzles[puzName] !== undefined
      : null;
  const isPuzzleSolved = useIsPuzzleSolved(puzName);
  const cutsceneState = useCutsceneState(puzName);

  if (teamId === null) return null;
  if (errataContent === null) return null;
  if (renderCtx === null) return null;
  if (hasAnswer && teamAnswerableScopeState === null) return null;
  if (sequenceId !== undefined && puzzlesInSequence === null) return null;
  if (celestialsAsSequence === null) return null;
  if (isPuzzleUnlocked === null) return null;
  if (isPuzzleSolved === null) return null;

  return {
    teamId,
    errataContent,
    renderCtx,
    teamAnswerableScopeState,
    puzzlesInSequence,
    celestialsAsSequence,
    isPuzzleUnlocked,
    isPuzzleSolved,
    cutsceneState,
  };
};

function PuzzleBodyDisplayPuz212() {
  const { renderCtx } = usePuzzleContent("puz212.1", PuzzleContentType.PUZZLE);
  if (renderCtx === null) return <Spinner inline={true} />;
  return (
    <PuzzlePageAuxWrapper pageHeading="You found a secret!">
      <PuzzleContentDisplayPreloaded renderCtx={renderCtx} />
    </PuzzlePageAuxWrapper>
  );
}

function PuzzlePage({ puz212 = false }: { puz212?: boolean }) {
  // send view puzzle req when selected puzzle changes
  const sockClient = useSockClient();
  const parsedSlug = useParsedSlug();
  const {
    slug = null,
    puzName = null,
    puzData: puzMetadata = null,
  } = parsedSlug ?? {};
  const updateSeparatelyPersistedState = useUpdateSeparatelyPersistedState();
  const updateBrowserWidePersistentState =
    useUpdateBrowserWidePersistentState();
  const viewTimes = useViewTimes();
  const { inPuzzlePage } = useInPuzzlePage();
  const [inPuzzle] = useState(useInPuzzlePage().inPuzzle);
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);
  const viewTime = puzName !== null ? viewTimes[puzName] ?? null : null;
  const isSolved = useIsPuzzleSolved(puzName);
  const campBaseRedirectPath = useCampBaseRedirectPath();

  useEffect(() => {
    if (puzName === null) return;
    if (viewTime !== null) return;
    updateBrowserWidePersistentState({
      viewTimes: {
        [puzName]: Date.now(),
      },
    });
  }, [sockClient, puzName, viewTime, updateBrowserWidePersistentState]);

  useEffect(() => {
    if (slug === null) return;
    // If the slug is invalid, don't save it.
    if (puzName === null) return;
    updateSeparatelyPersistedState({
      lastSeenPuzSlug: slug,
      lastSeenNonNullPuzSlug: slug,
    });
  }, [slug, puzName, updateSeparatelyPersistedState]);

  const needRedirectForInvalidPuzzle = (() => {
    // Handle effects going out of sync with React Router.
    if (!inPuzzlePage) return null;
    if (campBaseRedirectPath === null) return null;
    if (parsedSlug === null) return null;
    // Don't race with intro redirects.
    if (campBaseRedirectPath.path !== null) return null;

    return (
      parsedSlug.puzName === null &&
      // Don't check slug for the special puzzle212 case.
      !puz212
    );
  })();
  useEffect(() => {
    if (!(needRedirectForInvalidPuzzle ?? false)) return;
    return addFlushSockAPIMessagesEffect(sockClient, () => {
      toastr.error("Invalid puzzle name.");
      // If the slug is invalid, redirect to the puzzles list.
      setRedirectCommand({ path: "/puzzles", replace: true });
    });
  }, [needRedirectForInvalidPuzzle, setRedirectCommand, sockClient]);

  const puzData =
    puzMetadata !== null
      ? {
          hasAnswer: undefined,
          unlockTime: 0,
          ...puzMetadata,
        }
      : null;
  const hasAnswer =
    puzData?.hasAnswer ??
    (puzData !== null && "answer" in puzData && puzData.answer !== null) ??
    false;
  const showSubmitAnswerForm = inPuzzle && hasAnswer && !(isSolved ?? false);

  // Let toastr know if we have a puzzle page with submit answer enabled.
  useEffect(() => {
    if (showSubmitAnswerForm)
      document.body.classList.add("has-submit-answer-form");
    else document.body.classList.remove("has-submit-answer-form");
    return () => {
      document.body.classList.remove("has-submit-answer-form");
    };
  }, [showSubmitAnswerForm]);

  if (
    needRedirectForInvalidPuzzle === null ||
    (!puz212 && (puzName === null || slug === null || puzData === null))
  )
    return <LargeSpinner inline={true} />;

  return (
    <PuzzlePageWrapper showSubmitAnswerForm={showSubmitAnswerForm}>
      {puzData ? (
        <>
          <PuzzlePageToolbar puzData={puzData} />
          <Outlet context={puzData} />
        </>
      ) : (
        <PuzzleBodyDisplayPuz212 />
      )}
    </PuzzlePageWrapper>
  );
}

export function PuzzlePageWrapper({
  children,
  showSubmitAnswerForm = false,
}: PropsWithChildren<{ showSubmitAnswerForm?: boolean }>) {
  return (
    <div className="puzzle-page-root">
      <OverlayScrollbarsComponent
        options={defaultOverlayScrollbarsOptions}
        defer
        style={{ flex: 1 }}
      >
        <div className="puzzle-page-content">{children}</div>
      </OverlayScrollbarsComponent>
      <AnimatePresence>
        {showSubmitAnswerForm ? <SubmitAnswerForm /> : null}
      </AnimatePresence>
    </div>
  );
}

function PuzzlePageAuxWrapper({
  children,
  pageHeading = null,
}: PropsWithChildren<{
  pageHeading?: ReactNode;
}>) {
  const campLayout = useCampLayout();
  if (campLayout === null) return <LargeSpinner inline={true} />;
  const { isSinglePane, isBeforeFirstWish } = campLayout;
  const showBackButton = isSinglePane && !isBeforeFirstWish;

  return (
    <>
      {showBackButton ? (
        <div className="puzzle-page-aux-toolbar">
          <RoutedLink path="/puzzles" button={true}>
            ←
          </RoutedLink>
        </div>
      ) : null}
      <div className="puzzle-page-body">
        {pageHeading ? (
          <div className="puzzle-header">
            <h1>{pageHeading}</h1>
          </div>
        ) : null}
        {children}
      </div>
    </>
  );
}

export function NoPuzzlePage() {
  const campLayout = useCampLayout();
  if (campLayout === null) return <LargeSpinner />;
  const { isSinglePane, isBeforeFirstWish } = campLayout;
  if (isBeforeFirstWish) return <LargeSpinner />;
  if (isSinglePane) return null;
  return (
    <div className="no-puzzle-page">
      <img src="/static/images/cutscenes/stelle.png" />
      Select a puzzle!
    </div>
  );
}

export function LastPuzzlePage() {
  const setRedirectCommand = useNavStore((state) => state.setRedirectCommand);
  const sortedPuzzles = useSortedPuzzles();
  const firstPuzzleSlug = sortedPuzzles?.[0]?.slug ?? null;
  const lastSeenPuzSlug = useSeparatelyPersistedState(
    (state) => state.lastSeenPuzSlug
  );
  if (sortedPuzzles !== null && sortedPuzzles.length === 0)
    throw new Error("expect at least one puzzle unlocked");

  useEffect(() => {
    if (firstPuzzleSlug === null) return;
    setRedirectCommand({
      path:
        lastSeenPuzSlug === null
          ? "/puzzles"
          : `/puzzle/${lastSeenPuzSlug ?? firstPuzzleSlug}`,
      replace: true,
    });
  }, [lastSeenPuzSlug, firstPuzzleSlug, setRedirectCommand]);

  return null;
}

export default PuzzlePage;
