import { useState } from "react";
import { formatHope } from "sockapi/gacha/hope";
import { ScopeType } from "sockapi/scope-types";
import { Scope } from "sockapi/scopes";
import { HOPE_POOL_CONFIG } from "sockapi/scope-specs/hope-pool-spec";
import { useTeamId, useSockClient } from "stores/ServerInteractionStore";
import {
  useGlobalScopeState,
  useScopeStateResolvable,
  useIsPuzzleSolved,
  useCurrentHope,
} from "stores/ScopeStateStore";
import { Spinner } from "components/Loading";
import { useUILock } from "ui-locks";
import "./HopePool.css";

function HopePool() {
  const teamId = useTeamId();
  const sockClient = useSockClient();
  const hopePoolScopeState = useGlobalScopeState(ScopeType.HOPE_POOL);
  const teamHopePoolScopeState = useScopeStateResolvable(
    ScopeType.TEAM_HOPE_POOL,
    teamId !== null ? { teamId } : null
  );
  const currentHope = useCurrentHope();
  const isSolved = useIsPuzzleSolved(HOPE_POOL_CONFIG.puzName);
  const stepLock = useUILock();
  const [isContributing, setIsContributing] = useState(false);
  const [isClaiming, setIsClaiming] = useState(false);

  if (
    teamId === null ||
    hopePoolScopeState === null ||
    teamHopePoolScopeState === null ||
    isSolved === null ||
    currentHope === null
  )
    return <Spinner inline={true} />;
  const { poolAmt } = hopePoolScopeState;
  const { cycleContribution, hopeFromSolve } = teamHopePoolScopeState;
  const teamHopePoolScope: Scope<ScopeType.TEAM_HOPE_POOL> = {
    type: ScopeType.TEAM_HOPE_POOL,
    teamId,
  };

  const barPercent = Math.max(
    Math.min((poolAmt / HOPE_POOL_CONFIG.minToClaim) * 100, 100),
    0
  );
  const canContribute = currentHope >= HOPE_POOL_CONFIG.contributionAmt;
  const canClaim =
    !isSolved &&
    poolAmt >= HOPE_POOL_CONFIG.minToClaim &&
    cycleContribution <= 0;

  return (
    <div>
      <h4>The Pool</h4>
      <div
        className="hope-pool-meter"
        style={{ backgroundSize: `${barPercent}%` }}
      >
        {poolAmt} / {HOPE_POOL_CONFIG.minToClaim}
      </div>
      <div className="hope-pool-control">
        <div className="hope-pool-current-hope">
          You have {formatHope(currentHope)} hope.
        </div>
        <div className="hope-pool-buttons">
          <button
            disabled={stepLock.isHeld || !canContribute}
            onClick={() => {
              stepLock.acquireAndRun(async (getIsCanceled) => {
                setIsContributing(true);
                await sockClient.sendScopeStepAndWaitAsync(teamHopePoolScope, {
                  contribute: HOPE_POOL_CONFIG.contributionAmt,
                });
                setIsContributing(false);
              });
            }}
          >
            {isContributing ? <Spinner inline /> : "Contribute"}
          </button>
          <button
            className="hope-pool-claim-button"
            disabled={!canClaim || stepLock.isHeld}
            onClick={() => {
              stepLock.acquireAndRun(async (getIsCanceled) => {
                setIsClaiming(true);
                await sockClient.sendScopeStepAndWaitAsync(teamHopePoolScope, {
                  claim: true,
                });
                setIsClaiming(false);
              });
            }}
          >
            {isClaiming ? <Spinner inline /> : "Claim"}
          </button>
        </div>
      </div>
      {cycleContribution > 0 ? (
        <div>
          Your team has contributed {cycleContribution} hope to the pool since
          the last reset.
        </div>
      ) : null}
      {cycleContribution > 0 && !isSolved ? (
        <div>Your team may not claim the pool until the pool is reset.</div>
      ) : null}
      {isSolved && hopeFromSolve !== undefined ? (
        <div>
          You claimed the pool for {formatHope(hopeFromSolve)} hope! You cannot
          claim the pool again, but you may still contribute to it.
        </div>
      ) : null}
    </div>
  );
}

export default HopePool;
